INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ac51264-5721-44f5-8d8c-b97db570f0ef', '蓬州野望', '蓬州野望', '47c3aee4-1914-4789-b3b2-489064265eef', '唐', '["飄颻宕渠域，曠望蜀門隈。","水共三巴遠，山隨八陣開。","橋形疑漢接，石勢似煙迴。","欲下他鄉淚，猿聲幾處催。"]', '["飄颻宕渠域，曠望蜀门隈。","水共三巴远，山隨八陣开。","橋形疑漢接，石勢似煙迴。","欲下他乡泪，猿声幾处催。"]', '诗', 'shi', '', NULL, '蓬州野望 元兢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db278499-b987-4182-8c15-7854be54d079', '贈日本僧空海離合詩', '贈日本僧空海離合诗', 'e37af745-bb51-4744-a289-46d83a6b3431', '唐', '["仍可萬里來，可非衒其才。","增學助元機，土人如子稀。"]', '["仍可万里来，可非衒其才。","增学助元機，土人如子稀。"]', '诗', 'shi', '', NULL, '贈日本僧空海離合詩 馬總 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1db23ff3-fb03-4e31-ad17-6c5998f261d4', '贈釋空海歌', '贈釋空海歌', 'dfe43a0f-2c53-4569-a6e6-b3d598e75f07', '唐', '["說四句，演毘尼，凡夫聽者盡歸依。","天假吾師多伎術，就中草聖最狂逸。"]', '["说四句，演毘尼，凡夫听者尽归依。","天假吾師多伎術，就中草聖最狂逸。"]', '诗', 'shi', '', NULL, '贈釋空海歌 胡伯崇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca325dea-15a9-4c3b-a7a2-efcda1fac3ce', '因使日本願謁鑒真和尚既滅度不覲尊顏嗟而述懷', '因使日本願謁鑒真和尚既滅度不覲尊顏嗟而述懷', 'a54fa663-acf1-4ea0-bf51-e01bc91a3db4', '唐', '["上方傳佛燈，名僧號鑒真。","懷藏通鄰國，真如轉付民。","早嫌居五濁，寂滅離囂塵。","禪院從今古，青松遶塔新。","斯法留千載，名記萬年春。"]', '["上方傳佛灯，名僧號鑒真。","懷藏通鄰国，真如轉付民。","早嫌居五濁，寂滅離囂塵。","禪院從今古，青松遶塔新。","斯法留千載，名記万年春。"]', '诗', 'shi', '', NULL, '因使日本願謁鑒真和尚既滅度不覲尊顏嗟而述懷 高鶴林 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6762f8c9-aeeb-4621-b159-fe3be2f063c1', '句', '句', '2ea957d6-e9a0-4f5c-a98b-48ac55840abd', '唐', '["錦纜扁舟花岸靜，玉壺春酒管絃清。"]', '["錦纜扁舟花岸静，玉壺春酒管絃清。"]', '诗', 'shi', '', NULL, '句 朱千乘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('954fd1b9-b55c-40d6-bb78-8976410f74a8', '句', '句', '291e6a6b-9c73-4113-8370-e8b669b83bba', '唐', '["叡山新月冷，台嶠古風清。"]', '["叡山新月冷，台嶠古风清。"]', '诗', 'shi', '', NULL, '句 清觀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd602deb-e5f1-4140-9b28-40c06eddf3d1', '罷官後卻歸舊居', '罷官後卻归旧居', '2cbb04f1-80c2-4d53-9145-7999ea1bea26', '唐', '["不歸江畔久，舊業已凋殘。","露草蟲絲溼，湖泥鳥跡乾。","買山開客舍，選竹作漁竿。","何必勞州縣，驅馳効一官。"]', '["不归江畔久，旧業已凋殘。","露草蟲絲溼，湖泥鸟跡乾。","買山开客舍，選竹作漁竿。","何必勞州縣，驱驰効一官。"]', '诗', 'shi', '', NULL, '罷官後卻歸舊居 陳閏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39b78820-e9ce-4962-8720-af1c5ee56e1b', '句', '句', '959db82d-7c68-47b2-b1b1-da37153ac016', '唐', '["此心復何已，新月清江長。","雲歸石壁盡，月照霜林清。"]', '["此心复何已，新月清江长。","云归石壁尽，月照霜林清。"]', '诗', 'shi', '', NULL, '句 李堪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fae586d8-3b75-4075-9806-214666fab3d4', '兗州留獻李員外', '兗州留獻李員外', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["芙蓉零落秋池雨，楊柳蕭疎曉岸風。","神思只勞書卷上，年光任過酒杯中。"]', '["芙蓉零落秋池雨，楊柳蕭疎晓岸风。","神思只勞书卷上，年光任過酒杯中。"]', '诗', 'shi', '', NULL, '兗州留獻李員外 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7184e7d3-95b3-4140-84da-fc34e3b9446d', '句', '句', 'dd2abb55-42eb-4115-bf73-720137b4c451', '唐', '["畫角聲中朝暮浪，青山影裏古今人。","煙低紫陌千行柳，日暮朱樓一曲歌。","洛水波聲新草樹，嵩山雲影舊樓臺。","雲布長天龍勢逸，風高秋月雁行齊。","風遞鶯聲喧座上，日移花影倒林中。","芳園醉散花盈袖，幽逕吟歸月在帷。","極目遠山煙外暮，傷心歸棹月邊遲。"]', '["畫角声中朝暮浪，青山影裏古今人。","煙低紫陌千行柳，日暮朱楼一曲歌。","洛水波声新草樹，嵩山云影旧楼台。","云布长天龙勢逸，风高秋月雁行齊。","风遞鶯声喧座上，日移花影倒林中。","芳园醉散花盈袖，幽逕吟归月在帷。","極目远山煙外暮，傷心归棹月邊遲。"]', '诗', 'shi', '', NULL, '句 崔致遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25884f7d-64b7-4c32-9688-9811d89ed41e', '句', '句', '80830063-bc13-43ab-bd88-36450a1a1072', '唐', '["煙破樹頭驚宿鳥，露凝苔上暗流螢。","山人見月寧思寢，更掬寒泉滿手霜。","紺殿雨晴松色冷，禪林風起竹聲餘。","風過古殿香煙散，月到前林竹露清。","更有閑宵清淨境，曲江澄月對心虛。","寒露已催鴻北去，火雲漸散月西流。","園梅坼甲迎春笑，庭草抽心待節芳。"]', '["煙破樹头驚宿鸟，露凝苔上暗流螢。","山人见月寧思寢，更掬寒泉满手霜。","紺殿雨晴松色冷，禪林风起竹声餘。","风過古殿香煙散，月到前林竹露清。","更有闲宵清淨境，曲江澄月对心虛。","寒露已催鴻北去，火云漸散月西流。","园梅坼甲迎春笑，庭草抽心待節芳。"]', '诗', 'shi', '', NULL, '句 金立之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d1bc452-707b-49ad-8709-938c1dbe9ef6', '句', '句', '67588d9b-fbc8-4c19-8777-5dd89175a1ad', '唐', '["波衝亂石長如雨，風激疎松鎮似秋。"]', '["波衝亂石长如雨，风激疎松鎮似秋。"]', '诗', 'shi', '', NULL, '句 金可紀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86d0d593-db39-4135-afcf-8caaf9f49f29', '尋幽居不遇', '尋幽居不遇', '99790e3f-1ae4-474a-9bf6-465b2181fa8f', '唐', '["滿庭花落迷行路，遶院泉聲寫半山。","向暮此中回首去，洞門深處鳥關關。"]', '["满庭花落迷行路，遶院泉声寫半山。","向暮此中回首去，洞门深处鸟关关。"]', '诗', 'shi', '', NULL, '尋幽居不遇 莊翱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('649c0ac9-a18f-4eee-9ae1-a38820d2033e', '句', '句', '99790e3f-1ae4-474a-9bf6-465b2181fa8f', '唐', '["天外夜深風漸遠，高松長似水流聲。","焚香暮入飜花殿，凈手秋開貝葉經。","野性本憐松下月，幽情唯愛洞中春。","慇懃笑喻人間事，遙指庭花對夕陽。"]', '["天外夜深风漸远，高松长似水流声。","焚香暮入飜花殿，凈手秋开貝葉經。","野性本怜松下月，幽情唯愛洞中春。","慇懃笑喻人间事，遙指庭花对夕陽。"]', '诗', 'shi', '', NULL, '句 莊翱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('829126ea-3a84-40d4-80e5-24e2278a1f52', '春日', '春日', 'ed669f6b-84c5-4cce-b0fd-154d2ce78f36', '唐', '["鶯歸樹頂繁聲轉，雁去天邊細影斜。","雨拂青青行處草，煙含灼灼望中花。"]', '["鶯归樹頂繁声轉，雁去天邊細影斜。","雨拂青青行处草，煙含灼灼望中花。"]', '诗', 'shi', '', NULL, '春日 陸翬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ce5f755-0b1b-409c-b019-e0830399c24b', '句', '句', 'ed669f6b-84c5-4cce-b0fd-154d2ce78f36', '唐', '["三尺寒光冰在手，一張弓勢月當心。","巖下光陰生戶牗，澗邊形勢入池臺。","孤帆影入江煙盡，百舌聲流浦樹新。"]', '["三尺寒光冰在手，一張弓勢月當心。","巖下光陰生戶牗，澗邊形勢入池台。","孤帆影入江煙尽，百舌声流浦樹新。"]', '诗', 'shi', '', NULL, '句 陸翬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9586f26a-c78e-48fe-a06e-780d5dbebbdb', '夜泊越州逢北使', '夜泊越州逢北使', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["天地降雷雨，放逐還國都。","重以風潮事，年月戒回艫。","容顏荒外老，心想域中愚。","憩泊在茲夜，炎雲逐斗樞。","䬓{風兪}縈海若，霹靂耿天吳。","鼇抃羣島失，鯨吞衆流輸。","偶逢金華使，握手淚相濡。","飢共噬齊棗，眠共席秦蒲。","既北思攸濟，將南睿所圖。","往來固無咎，何忽憚前桴。"]', '["天地降雷雨，放逐還国都。","重以风潮事，年月戒回艫。","容顏荒外老，心想域中愚。","憩泊在茲夜，炎云逐斗樞。","䬓{风兪}縈海若，霹靂耿天吳。","鼇抃羣島失，鯨吞衆流輸。","偶逢金华使，握手泪相濡。","飢共噬齊棗，眠共席秦蒲。","既北思攸濟，將南睿所圖。","往来固無咎，何忽憚前桴。"]', '诗', 'shi', '', NULL, '夜泊越州逢北使 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('604e1a1a-9ecf-47d1-97fa-efb08357d492', '紹隆寺', '紹隆寺', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["吾從釋迦久，無上師涅槃。","探道三十載，得道天南端。","非勝適殊方，起諠歸理難。","放棄乃良緣，世慮不曾干。","香界縈北渚，花龕隱南巒。","危昂階下石，演漾窗中瀾。","雲蓋看木秀，天空見藤盤。","處俗勒宴坐，居貧業行壇。","試將有漏軀，聊作無生觀。","了然究諸品，彌覺靜者安。"]', '["吾從釋迦久，無上師涅槃。","探道三十載，得道天南端。","非勝適殊方，起諠归理难。","放棄乃良緣，世慮不曾干。","香界縈北渚，花龕隐南巒。","危昂階下石，演漾窗中瀾。","云蓋看木秀，天空见藤盤。","处俗勒宴坐，居貧業行壇。","試將有漏軀，聊作無生观。","了然究諸品，彌覺静者安。"]', '诗', 'shi', '', NULL, '紹隆寺 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b525f817-8750-43db-bdfc-7366b7ef5936', '神龍初廢逐南荒途出郴口北望蘇耽山', '神龙初廢逐南荒途出郴口北望蘇耽山', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["少曾讀仙史，知有蘇耽君。","流望來南國，依然會昔聞。","泊舟問耆老，遙指孤山雲。","孤山郴郡北，不與衆山羣。","重崖下縈映，嶛嶢上乣紛。","碧峰泉附落，紅壁樹傍分。","選地今方爾，昇天因可云。","不才予竄迹，羽化子遺芬。","將覽成麟鳳，旋驚禦鬼文。","此中迷出處，含思獨氛氳。"]', '["少曾读仙史，知有蘇耽君。","流望来南国，依然會昔闻。","泊舟问耆老，遙指孤山云。","孤山郴郡北，不與衆山羣。","重崖下縈映，嶛嶢上乣紛。","碧峰泉附落，紅壁樹傍分。","選地今方爾，昇天因可云。","不才予竄迹，羽化子遺芬。","將覽成麟鳳，旋驚禦鬼文。","此中迷出处，含思独氛氳。"]', '诗', 'shi', '', NULL, '神龍初廢逐南荒途出郴口北望蘇耽山 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d12566ee-cd4c-4927-af6e-28e20a6df6c1', '初達驩州', '初達驩州', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["流子一十八，命予偏不偶。","配遠天遂窮，到遲日最後。","水行儋耳國，陸行雕題藪。","魂魄遊鬼門，骸骨遺鯨口。","夜則忍飢臥，朝則抱病走。","搔首向南荒，拭淚看北斗。","何年赦書來？重飲洛陽酒。"]', '["流子一十八，命予偏不偶。","配远天遂窮，到遲日最後。","水行儋耳国，陸行雕題藪。","魂魄游鬼门，骸骨遺鯨口。","夜則忍飢臥，朝則抱病走。","搔首向南荒，拭泪看北斗。","何年赦书来？重饮洛陽酒。"]', '诗', 'shi', '', NULL, '初達驩州 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5e61ffe-83a4-4e5f-be6f-9f42c6ecadfa', '被彈', '被彈', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["知人昔不易，舉非貴易失。","爾何按國章，無罪見呵叱。","平生守直道，遂爲衆所嫉。","少以文作吏，手不曾開律。","一旦法相持，荒忙意如漆。","幼子雙囹圄，老夫一念室。","昆弟兩三人，相次俱囚桎。","萬鑠當衆怒，千謗無片實。","庶以白黑讒，顯此涇渭質。","劾吏何咆哮，晨夜聞撲抶。","事間拾虛證，理外存枉筆。","懷痛不見伸，抱冤竟難悉。","窮囚多垢膩，愁坐饒蟣虱。","三日唯一飯，兩旬不再櫛。","是時盛夏中，暵赫多瘵疾。","瞪目眠欲閉，暗嗚氣不出。","有風自扶搖，鼓蕩無倫匹。","安得吹浮雲，令我見白日。"]', '["知人昔不易，舉非貴易失。","爾何按国章，無罪见呵叱。","平生守直道，遂爲衆所嫉。","少以文作吏，手不曾开律。","一旦法相持，荒忙意如漆。","幼子雙囹圄，老夫一念室。","昆弟兩三人，相次俱囚桎。","万鑠當衆怒，千謗無片實。","庶以白黑讒，显此涇渭質。","劾吏何咆哮，晨夜闻撲抶。","事间拾虛證，理外存枉笔。","懷痛不见伸，抱冤竟难悉。","窮囚多垢膩，愁坐饒蟣虱。","三日唯一飯，兩旬不再櫛。","是时盛夏中，暵赫多瘵疾。","瞪目眠欲閉，暗嗚氣不出。","有风自扶搖，鼓蕩無倫匹。","安得吹浮云，令我见白日。"]', '诗', 'shi', '', NULL, '被彈 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfda4102-2446-4daa-a7bb-1539ec77c5d3', '枉繫二首 一', '枉繫二首 一', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["吾憐曾家子，昔有投杼疑。","吾憐姬公旦，非無鴟鴞詩。","臣子竭忠孝，君親惑讒欺。","萋斐離骨肉，含愁興此辭。"]', '["吾怜曾家子，昔有投杼疑。","吾怜姬公旦，非無鴟鴞诗。","臣子竭忠孝，君親惑讒欺。","萋斐離骨肉，含愁兴此辞。"]', '诗', 'shi', '', NULL, '枉繫二首 一 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('312131ec-449f-405a-ac52-8a6b33845b17', '枉繫二首 二', '枉繫二首 二', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["昔日公冶長，非罪遇縲絏。","聖人降其子，古來歎獨絕。","我無毫髪瑕，苦心懷冰雪。","今代多秀士，誰能繼明轍。"]', '["昔日公冶长，非罪遇縲絏。","聖人降其子，古来歎独絕。","我無毫髪瑕，苦心懷冰雪。","今代多秀士，誰能繼明轍。"]', '诗', 'shi', '', NULL, '枉繫二首 二 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ebb6d7a-d5ce-4e4d-9d95-cdc2cffe687e', '黃鶴', '黄鹤', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["黃鶴佐丹鳳，不能羣白鷴。","拂雲遊四海，弄影到三山。","遙憶君軒上，來下天池間。","明珠世不重，知有報恩環。"]', '["黄鹤佐丹鳳，不能羣白鷴。","拂云游四海，弄影到三山。","遙憶君軒上，来下天池间。","明珠世不重，知有報恩环。"]', '诗', 'shi', '', NULL, '黃鶴 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b58dc484-b3dc-4d76-b38d-dcc46793c594', '傷王學土', '傷王学土', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["閉囚斷外事，昧坐半餘朞。","有言頴叔子，亡來已一時。","初聞宛不信，中話涕漣洏。","痛哉玄夜重，何遽青春姿。","憶汝曾旅食，屢空瀍澗湄。","吾徒祿未厚，筲斗愧相貽。","原憲貧無愁，顏回樂自持。","詔書擇才善，君爲王子師。","寵儒名可尚，論秩官猶欺。","化往不復見，情來安可思。","目絕毫翰灑，耳無歌諷期。","靈柩寄何處，精魂今何之？","恨予在丹棘，不得看素旗。","孀妻知己歎，幼子路人悲。","感遊值商日，絕弦留此詞。"]', '["閉囚斷外事，昧坐半餘朞。","有言頴叔子，亡来已一时。","初闻宛不信，中話涕漣洏。","痛哉玄夜重，何遽青春姿。","憶汝曾旅食，屢空瀍澗湄。","吾徒祿未厚，筲斗愧相貽。","原憲貧無愁，顏回乐自持。","詔书擇才善，君爲王子師。","寵儒名可尚，論秩官猶欺。","化往不复见，情来安可思。","目絕毫翰灑，耳無歌諷期。","靈柩寄何处，精魂今何之？","恨予在丹棘，不得看素旗。","孀妻知己歎，幼子路人悲。","感游值商日，絕弦留此词。"]', '诗', 'shi', '', NULL, '傷王學土 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2d38f74-b343-4833-ac18-4d72ae70f225', '古鏡', '古镜', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["莓苔翳清池，蝦蟆蝕明月。","埋落今如此，照心未嘗歇。","願垂拂拭恩，爲君鑒玄髪。"]', '["莓苔翳清池，蝦蟆蝕明月。","埋落今如此，照心未嘗歇。","願垂拂拭恩，爲君鑒玄髪。"]', '诗', 'shi', '', NULL, '古鏡 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35dcfd2c-5afd-48d1-a906-541d5cac7017', '鳳簫曲', '鳳簫曲', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["八月涼風動高閣，千金麗人捲綃幕。","已憐池上歇芳菲，不念君恩坐搖落。","世上榮華如轉蓬，朝隨阡陌暮雲中。","飛燕侍寢昭陽殿，班姬飲恨長信宮。","長信宮，昭陽殿，春來歌舞妾自知，秋至簾櫳君不見。","昔時嬴女厭世紛，學吹鳳簫乘彩雲。","含情轉睞向蕭史，千載紅顏持贈君。"]', '["八月涼风动高閣，千金丽人捲綃幕。","已怜池上歇芳菲，不念君恩坐搖落。","世上榮华如轉蓬，朝隨阡陌暮云中。","飞燕侍寢昭陽殿，班姬饮恨长信宮。","长信宮，昭陽殿，春来歌舞妾自知，秋至簾櫳君不见。","昔时嬴女厭世紛，学吹鳳簫乘彩云。","含情轉睞向蕭史，千載紅顏持贈君。"]', '诗', 'shi', '', NULL, '鳳簫曲 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01b06a31-10d7-448a-9207-04096ca4610a', '古歌', '古歌', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["落葉流風向玉臺，夜寒秋思洞房開。","水晶簾外金波下，雲母窗前銀漢回。","玉階陰陰苔蘚色，君王屢綦難再得。","璇閨窈窕秋夜長，繡戶徘徊明月光。","燕姬綵帳芙蓉色，秦女金爐蘭麝香。","北斗七星橫夜半，清歌一曲斷君腸。"]', '["落葉流风向玉台，夜寒秋思洞房开。","水晶簾外金波下，云母窗前銀漢回。","玉階陰陰苔蘚色，君王屢綦难再得。","璇閨窈窕秋夜长，繡戶徘徊明月光。","燕姬綵帳芙蓉色，秦女金爐蘭麝香。","北斗七星橫夜半，清歌一曲斷君腸。"]', '诗', 'shi', '', NULL, '古歌 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03602668-16a3-449f-9898-3e082aa82e4a', '七夕曝衣篇', '七夕曝衣篇', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["君不見昔日宜春太液邊，披香畫閣與天連。","燈火灼爍九微暎，香氣氛氳百和然。","此夜星繁河正白，人傳織女牽牛客。","宮中擾擾曝衣樓，天上娥娥紅粉席。","曝衣何許曛半黃，宮中綵女提玉箱。","珠履奔騰上蘭砌，金梯宛轉出梅梁。","絳河裏，碧煙上，雙花伏兔畫屏風，四子盤龍擎斗帳。","舒羅散縠雲霧開，綴玉垂珠星漢回。","朝霞散彩羞衣架，晚月分光劣鏡臺。","上有仙人長命綹，中看玉女迎歡繡。","玳瑁簾中別作春，珊瑚窗裏翻成晝。","椒房金屋寵新流，意氣嬌奢不自由。","漢文宜惜露臺費，晉武須焚前殿裘。"]', '["君不见昔日宜春太液邊，披香畫閣與天連。","灯火灼爍九微暎，香氣氛氳百和然。","此夜星繁河正白，人傳织女牽牛客。","宮中擾擾曝衣楼，天上娥娥紅粉席。","曝衣何許曛半黄，宮中綵女提玉箱。","珠履奔腾上蘭砌，金梯宛轉出梅梁。","絳河裏，碧煙上，雙花伏兔畫屏风，四子盤龙擎斗帳。","舒羅散縠云霧开，綴玉垂珠星漢回。","朝霞散彩羞衣架，晚月分光劣镜台。","上有仙人长命綹，中看玉女迎歡繡。","玳瑁簾中別作春，珊瑚窗裏翻成晝。","椒房金屋寵新流，意氣嬌奢不自由。","漢文宜惜露台費，晉武須焚前殿裘。"]', '诗', 'shi', '', NULL, '七夕曝衣篇 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84d64ee8-b6de-4160-9047-5bc297dc4b9e', '入少密溪', '入少密溪', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["雲峯苔壁繞溪斜，江路香風夾岸花。","樹密不言通鳥道，雞鳴始覺有人家。","人家更在深巖口，澗水周流宅前後。","遊魚瞥瞥雙釣童，伐木丁丁一樵叟。","自言避喧非避秦，薜衣耕鑿帝堯人。","相留且待雞黍熟，夕臥深山蘿月春。"]', '["云峯苔壁繞溪斜，江路香风夾岸花。","樹密不言通鸟道，雞鳴始覺有人家。","人家更在深巖口，澗水周流宅前後。","游鱼瞥瞥雙釣童，伐木丁丁一樵叟。","自言避喧非避秦，薜衣耕鑿帝堯人。","相留且待雞黍熟，夕臥深山蘿月春。"]', '诗', 'shi', '', NULL, '入少密溪 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70241001-7757-4bf2-aa33-9eb69f6f5dc2', '霹靂引', '霹靂引', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["歲七月，火伏而金生。","客有鼓琴於門者，奏霹靂之商聲。","始戛羽以騞砉，終扣宮而砰駖。","電耀耀兮龍躍，雷闐闐兮雨冥。","氣嗚唅以會雅，態歘翕以橫生。","有如驅千旗，制五兵。","截荒虺，斮長鯨。","孰與廣陵比，意別鶴儔精而已。","俾我雄子魄動，毅夫髪立。","懷恩不淺，武義雙輯。","視胡若芥，剪羯如拾。","豈徒慷慨中筵，備羣娛之翕習哉。"]', '["歲七月，火伏而金生。","客有鼓琴於门者，奏霹靂之商声。","始戛羽以騞砉，終扣宮而砰駖。","電耀耀兮龙躍，雷闐闐兮雨冥。","氣嗚唅以會雅，態歘翕以橫生。","有如驱千旗，制五兵。","截荒虺，斮长鯨。","孰與廣陵比，意別鹤儔精而已。","俾我雄子魄动，毅夫髪立。","懷恩不淺，武義雙輯。","視胡若芥，剪羯如拾。","豈徒慷慨中筵，備羣娛之翕習哉。"]', '诗', 'shi', '', NULL, '霹靂引 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c1b9462-bc83-4f35-950d-ada6442017e9', '立春日內出綵花應制', '立春日內出綵花應制', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["合殿春應早，開箱綵預知。","花迎宸翰發，葉待御筵披。","梅訝香全少，桃驚色頓移。","輕生承剪拂，長伴萬年枝。"]', '["合殿春應早，开箱綵預知。","花迎宸翰發，葉待御筵披。","梅訝香全少，桃驚色頓移。","轻生承剪拂，长伴万年枝。"]', '诗', 'shi', '', NULL, '立春日內出綵花應制 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('babd3684-1745-4346-95d0-fc383fd0e443', '晦日滻水應制', '晦日滻水應制', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["素滻接宸居，青門盛祓除。","摘蘭喧鳳野，浮藻溢龍渠。","苑蝶飛殊懶，宮鶯囀不疎。","星移天上入，歌舞向儲胥。"]', '["素滻接宸居，青门盛祓除。","摘蘭喧鳳野，浮藻溢龙渠。","苑蝶飞殊懶，宮鶯囀不疎。","星移天上入，歌舞向儲胥。"]', '诗', 'shi', '', NULL, '晦日滻水應制 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b12a161c-6a4f-4313-8f9f-a9d7f5dee0c1', '奉和洛陽翫雪應制', '奉和洛陽翫雪應制', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["周王甲子旦，漢后德陽宮。","灑瑞天庭裏，驚春御苑中。","氛氳生浩氣，颯杳舞回風。","宸藻光盈尺，賡歌樂歲豐。"]', '["周王甲子旦，漢后德陽宮。","灑瑞天庭裏，驚春御苑中。","氛氳生浩氣，颯杳舞回风。","宸藻光盈尺，賡歌乐歲豐。"]', '诗', 'shi', '', NULL, '奉和洛陽翫雪應制 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b5c9844-6e46-4d8d-8714-bd7c23382376', '三日梨園侍宴', '三日梨园侍宴', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["九重馳道出，三巳禊堂開。","畫鷁中流動，青龍上苑來。","野花飄御座，河柳拂天杯。","日晚迎祥處，笙鏞下帝臺。"]', '["九重驰道出，三巳禊堂开。","畫鷁中流动，青龙上苑来。","野花飄御座，河柳拂天杯。","日晚迎祥处，笙鏞下帝台。"]', '诗', 'shi', '', NULL, '三日梨園侍宴 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70585fc1-31c6-4d25-92a0-f8c52cc26957', '幸梨園亭觀打毬應制', '幸梨园亭观打毬應制', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["今春芳苑遊，接武上瓊樓。","宛轉縈香騎，飄颻拂畫毬。","俯身迎未落，迴轡逐傍流。","秖爲看花鳥，時時誤失籌。"]', '["今春芳苑游，接武上瓊楼。","宛轉縈香騎，飄颻拂畫毬。","俯身迎未落，迴轡逐傍流。","秖爲看花鸟，时时誤失籌。"]', '诗', 'shi', '', NULL, '幸梨園亭觀打毬應制 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83486b6d-e84b-481b-aa2b-577bd03b32af', '九日臨渭亭侍宴應制得長字', '九日臨渭亭侍宴應制得长字', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["御氣幸金方，憑高薦羽觴。","魏文頒菊蕋，漢武賜萸房。","秋變銅池色，晴添銀樹光。","年年重九慶，日月奉天長。"]', '["御氣幸金方，憑高薦羽觴。","魏文頒菊蕋，漢武賜萸房。","秋变銅池色，晴添銀樹光。","年年重九慶，日月奉天长。"]', '诗', 'shi', '', NULL, '九日臨渭亭侍宴應制得長字 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64274b57-6ee8-424e-8989-a67214e491cc', '歲夜安樂公主滿月侍宴', '歲夜安乐公主满月侍宴', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["除夜子星回，天孫滿月杯。","詠歌麟趾合，簫管鳳雛來。","歲炬常然桂，春盤預折梅。","聖皇千萬壽，垂曉御樓開。"]', '["除夜子星回，天孫满月杯。","詠歌麟趾合，簫管鳳雛来。","歲炬常然桂，春盤預折梅。","聖皇千万壽，垂晓御楼开。"]', '诗', 'shi', '', NULL, '歲夜安樂公主滿月侍宴 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91af8429-3dbe-4152-8493-679e074bb548', '安樂公主移入新宅', '安乐公主移入新宅', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["初聞衡漢來，移住斗城隈。","錦帳迎風轉，瓊筵拂霧開。","馬香遺舊埒，鳳吹繞新臺。"]', '["初闻衡漢来，移住斗城隈。","錦帳迎风轉，瓊筵拂霧开。","马香遺旧埒，鳳吹繞新台。"]', '诗', 'shi', '', NULL, '安樂公主移入新宅 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cd66d8d-eeb4-4945-9e35-8488993e994f', '仙萼亭初成侍宴應制', '仙萼亭初成侍宴應制', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["山中氣色和，宸賞第中過。","輦路披仙掌，帷宮拂帝蘿。","泉臨香澗落，峰入翠雲多。","無異登玄圃，東南望白河。"]', '["山中氣色和，宸賞第中過。","輦路披仙掌，帷宮拂帝蘿。","泉臨香澗落，峰入翠云多。","無異登玄圃，东南望白河。"]', '诗', 'shi', '', NULL, '仙萼亭初成侍宴應制 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1303b08-746e-48e9-93a2-66797e60da94', '送金城公主適西蕃應制', '送金城公主適西蕃應制', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["金牓扶丹掖，銀河屬紫閽。","那堪將鳳女，還以嫁烏孫。","玉就歌中怨，珠辭掌上恩。","西戎非我匹，明主至公存。"]', '["金牓扶丹掖，銀河屬紫閽。","那堪將鳳女，還以嫁烏孫。","玉就歌中怨，珠辞掌上恩。","西戎非我匹，明主至公存。"]', '诗', 'shi', '', NULL, '送金城公主適西蕃應制 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47aaf877-96fe-4ebf-80f4-56d48ce6217e', '幸白鹿觀應制', '幸白鹿观應制', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["紫鳳真人府，斑龍太上家。","天流芝蓋下，山轉桂旗斜。","聖藻垂寒露，仙杯落晚霞。","唯應問王母，桃作幾時花。"]', '["紫鳳真人府，斑龙太上家。","天流芝蓋下，山轉桂旗斜。","聖藻垂寒露，仙杯落晚霞。","唯應问王母，桃作幾时花。"]', '诗', 'shi', '', NULL, '幸白鹿觀應制 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2266376-60c8-4d9b-ac64-4d37bbabd721', '洛陽道', '洛陽道', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["九門開洛邑，雙闕對河橋。","白日青春道，軒裳半下朝。","乘羊稚子看，拾翠美人嬌。","行樂歸恆晚，香塵撲地遙。"]', '["九门开洛邑，雙闕对河橋。","白日青春道，軒裳半下朝。","乘羊稚子看，拾翠美人嬌。","行乐归恆晚，香塵撲地遙。"]', '诗', 'shi', '', NULL, '洛陽道 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a10509b0-ebb7-44c2-8a8f-068ff75d9b89', '驄馬', '驄马', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["西北五花驄，來時道向東。","四蹄碧玉片，雙眼黃金瞳。","鞍上留明月，嘶間動朔風。","借君馳沛艾，一戰取雲中。"]', '["西北五花驄，来时道向东。","四蹄碧玉片，雙眼黄金瞳。","鞍上留明月，嘶间动朔风。","借君驰沛艾，一戰取云中。"]', '诗', 'shi', '', NULL, '驄馬 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5aa31f21-9af5-40bc-9480-3672fc88dd5b', '銅雀臺', '銅雀台', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["昔年分鼎地，今日望陵臺。","一旦雄圖盡，千秋遺令開。","綺羅君不見，歌舞妾空來。","恩共漳河水，東流無重回。"]', '["昔年分鼎地，今日望陵台。","一旦雄圖尽，千秋遺令开。","綺羅君不见，歌舞妾空来。","恩共漳河水，东流無重回。"]', '诗', 'shi', '', NULL, '銅雀臺 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9780108b-bb66-41f2-be89-7535fc3b694e', '長門怨', '长门怨', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["月皎風泠泠，長門次掖庭。","玉階聞墜葉，羅幌見飛螢。","清露凝珠綴，流塵下翠屏。","妾心君未察，愁歎劇繁星。"]', '["月皎风泠泠，长门次掖庭。","玉階闻墜葉，羅幌见飞螢。","清露凝珠綴，流塵下翠屏。","妾心君未察，愁歎劇繁星。"]', '诗', 'shi', '', NULL, '長門怨 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5a94e24-96f3-4645-a628-3ea2359b872d', '巫山高二首 一', '巫山高二首 一', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["巫山峯十二，合沓隱昭回。","俯眺琵琶峽，平看雲雨臺。","古槎天外倚，瀑水日邊來。","何忍猿啼夜，荆王枕席開。"]', '["巫山峯十二，合沓隐昭回。","俯眺琵琶峽，平看云雨台。","古槎天外倚，瀑水日邊来。","何忍猿啼夜，荆王枕席开。"]', '诗', 'shi', '', NULL, '巫山高二首 一 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84070be0-fa7c-4b1b-a7bb-65e8d74844dd', '巫山高二首 二', '巫山高二首 二', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["神女向高唐，巫山下夕陽。","裴回作行雨，婉孌逐荆王。","電影江前落，雷聲峽外長。","霽雲無處所，臺館曉蒼蒼。"]', '["神女向高唐，巫山下夕陽。","裴回作行雨，婉孌逐荆王。","電影江前落，雷声峽外长。","霽云無处所，台館晓蒼蒼。"]', '诗', 'shi', '', NULL, '巫山高二首 二 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d06a3cc-bddb-49e9-a80d-5b3adc3de3e1', '巫山高', '巫山高', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["巫山高不極，合沓狀奇新。","暗谷疑風雨，陰崖若鬼神。","月明三峽曙，潮滿九江春。","爲問陽臺客，應知入夢人。"]', '["巫山高不極，合沓狀奇新。","暗谷疑风雨，陰崖若鬼神。","月明三峽曙，潮满九江春。","爲问陽台客，應知入梦人。"]', '诗', 'shi', '', NULL, '巫山高 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04d92f40-d412-4eb5-ab64-d58aa0a779c6', '七夕', '七夕', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["秋近雁行稀，天高鵲夜飛。","妝成應懶織，今夕渡河歸。","月皎宜穿線，風輕得曝衣。","來時不可覺，神驗有光輝。"]', '["秋近雁行稀，天高鵲夜飞。","妝成應懶织，今夕渡河归。","月皎宜穿線，风轻得曝衣。","来时不可覺，神驗有光輝。"]', '诗', 'shi', '', NULL, '七夕 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd19c09d-4d11-4209-870a-0fc03e73e647', '春閨', '春閨', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["鐵馬三軍去，金閨二月還。","邊愁離上國，春夢失陽關。","池水琉璃淨，園花玳瑁斑。","歲華空自擲，憂思不勝顏。"]', '["鐵马三軍去，金閨二月還。","邊愁離上国，春梦失陽关。","池水琉璃淨，园花玳瑁斑。","歲华空自擲，憂思不勝顏。"]', '诗', 'shi', '', NULL, '春閨 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcc690c1-ca11-4142-8d78-dc2505a4ebc7', '奉和聖製同皇太子遊慈恩寺應制', '奉和聖製同皇太子游慈恩寺應制', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["肅肅蓮花界，熒熒貝葉宮。","金人來夢裏，白馬出城中。","湧塔初從地，焚香欲遍空。","天歌應春籥，非是爲春風。"]', '["肅肅蓮花界，熒熒貝葉宮。","金人来梦裏，白马出城中。","湧塔初從地，焚香欲遍空。","天歌應春籥，非是爲春风。"]', '诗', 'shi', '', NULL, '奉和聖製同皇太子遊慈恩寺應制 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49be49dc-b305-4bba-9319-72aa0a8186b1', '和洛州康士曹庭芝望月有懷', '和洛州康士曹庭芝望月有懷', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["天使下西樓，光含萬象秋。","臺前疑挂鏡，簾外似懸鉤。","張尹將眉學，班姬取扇儔。","佳期應借問，爲報在刀頭。"]', '["天使下西楼，光含万象秋。","台前疑挂镜，簾外似懸鉤。","張尹將眉学，班姬取扇儔。","佳期應借问，爲報在刀头。"]', '诗', 'shi', '', NULL, '和洛州康士曹庭芝望月有懷 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fb8bbab-4b48-4f00-a090-54ff850713fb', '壽陽王花燭', '壽陽王花燭', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["仙媛乘龍夕，天孫捧雁來。","可憐桃李樹，更遶鳳皇臺。","燭送香車入，花臨寶扇開。","莫令銀箭曉，爲盡合歡杯。"]', '["仙媛乘龙夕，天孫捧雁来。","可怜桃李樹，更遶鳳皇台。","燭送香车入，花臨寶扇开。","莫令銀箭晓，爲尽合歡杯。"]', '诗', 'shi', '', NULL, '壽陽王花燭 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('916f9fab-d4c9-4619-8b63-aab55d467d35', '隴頭水', '隴头水', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["隴山飛落葉，隴雁度寒天。","愁見三秋水，分爲兩地泉。","西流入羗郡，東下向秦川。","征客重回首，肝腸空自憐。"]', '["隴山飞落葉，隴雁度寒天。","愁见三秋水，分爲兩地泉。","西流入羗郡，东下向秦川。","征客重回首，肝腸空自怜。"]', '诗', 'shi', '', NULL, '隴頭水 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27bb726e-3b6f-41b3-941a-66db00f46d51', '關山月', '关山月', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["漢月生遼海，朣朧出半暉。","合昏玄菟郡，中夜白登圍。","暈落關山迥，光含霜霰微。","將軍聽曉角，戰馬欲南歸。"]', '["漢月生遼海，朣朧出半暉。","合昏玄菟郡，中夜白登圍。","暈落关山迥，光含霜霰微。","將軍听晓角，戰马欲南归。"]', '诗', 'shi', '', NULL, '關山月 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23617543-e0f3-44bf-9360-2772ec9ca8d9', '折楊柳', '折楊柳', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["玉窗朝日暎，羅帳春風吹。","拭淚攀楊柳，長條踠地垂。","白花飛歷亂，黃鳥思參差。","妾自肝腸斷，傍人那得知。"]', '["玉窗朝日暎，羅帳春风吹。","拭泪攀楊柳，长條踠地垂。","白花飞歷亂，黄鸟思參差。","妾自肝腸斷，傍人那得知。"]', '诗', 'shi', '', NULL, '折楊柳 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fee8bf1-2306-4b76-96a2-6d014212f320', '梅花落', '梅花落', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["鐵騎幾時回，金閨怨早梅。","雪寒花已落，風暖葉應開。","夕逐新春管，香迎小歲杯。","盛時何足貴，書裏報輪臺。"]', '["鐵騎幾时回，金閨怨早梅。","雪寒花已落，风暖葉應开。","夕逐新春管，香迎小歲杯。","盛时何足貴，书裏報輪台。"]', '诗', 'shi', '', NULL, '梅花落 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17e061a9-a122-419c-aa21-215d37c4e3e1', '紫騮馬', '紫騮马', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["青玉紫騮鞍，驕多影屢盤。","荷君能剪拂，躞蹀噴桑乾。","踠足追奔易，長鳴遇賞難。","摐金一萬里，霜露不辭寒。"]', '["青玉紫騮鞍，驕多影屢盤。","荷君能剪拂，躞蹀噴桑乾。","踠足追奔易，长鳴遇賞难。","摐金一万里，霜露不辞寒。"]', '诗', 'shi', '', NULL, '紫騮馬 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f8bdfa2-20aa-45a4-a460-77df1ebab288', '上之回', '上之回', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["制書下關右，天子問回中。","壇墠經過遠，威儀侍從雄。","黃麾搖晝日，青幰曳松風。","迴望甘泉道，龍山隱漢宮。"]', '["制书下关右，天子问回中。","壇墠經過远，威儀侍從雄。","黄麾搖晝日，青幰曳松风。","迴望甘泉道，龙山隐漢宮。"]', '诗', 'shi', '', NULL, '上之回 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10d47f62-8f26-4045-a296-7579def9fbde', '王昭君', '王昭君', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["非君惜鸞殿，非妾妬蛾眉。","薄命由驕虜，無情是畫師。","嫁來胡地日，不並漢宮時。","心苦無聊賴，何堪馬上辭。"]', '["非君惜鸾殿，非妾妬蛾眉。","薄命由驕虜，無情是畫師。","嫁来胡地日，不並漢宮时。","心苦無聊賴，何堪马上辞。"]', '诗', 'shi', '', NULL, '王昭君 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9d7d787-1068-4c53-a6a2-0abc4a020545', '被試出塞', '被試出塞', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["十年通大漠，萬里出長平。","寒日生戈劒，陰雲拂斾旌。","飢烏啼舊壘，疲馬戀空城。","辛苦臯蘭北，胡霜損漢兵。"]', '["十年通大漠，万里出长平。","寒日生戈劒，陰云拂斾旌。","飢烏啼旧壘，疲马戀空城。","辛苦臯蘭北，胡霜損漢兵。"]', '诗', 'shi', '', NULL, '被試出塞 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce55c20d-64c1-4dbf-ad70-4aae1c0b9e92', '牛女', '牛女', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["粉席秋期緩，針樓別怨多。","奔龍爭度日，飛鵲亂填河。","失喜先臨鏡，含羞未解羅。","誰能留夜色，來夕倍還梭。"]', '["粉席秋期緩，針楼別怨多。","奔龙爭度日，飞鵲亂填河。","失喜先臨镜，含羞未解羅。","誰能留夜色，来夕倍還梭。"]', '诗', 'shi', '', NULL, '牛女 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e568765-f484-4616-9ca7-676b6831dc32', '雜詩三首 一', '杂诗三首 一', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["落葉驚秋婦，高砧促暝機。","蜘蛛尋月度，螢火傍人飛。","清鏡紅埃入，孤燈綠焰微。","怨啼能至曉，獨自懶縫衣。"]', '["落葉驚秋婦，高砧促暝機。","蜘蛛尋月度，螢火傍人飞。","清镜紅埃入，孤灯綠焰微。","怨啼能至晓，独自懶縫衣。"]', '诗', 'shi', '', NULL, '雜詩三首 一 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12e099e7-7474-41c3-a332-76035325ef81', '雜詩三首 二', '杂诗三首 二', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["妾家臨渭北，春夢著遼西。","何苦朝鮮郡，年年事鼓鼙。","燕來紅壁語，鶯向綠窗啼。","爲許長相憶，闌干玉筯齊。"]', '["妾家臨渭北，春梦著遼西。","何苦朝鲜郡，年年事鼓鼙。","燕来紅壁語，鶯向綠窗啼。","爲許长相憶，闌干玉筯齊。"]', '诗', 'shi', '', NULL, '雜詩三首 二 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fb10ea4-f46c-4c08-bd06-f039f1907be6', '雜詩三首 三', '杂诗三首 三', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["聞道黃龍戍，頻年不解兵。","可憐閨裏月，長在漢家營。","少婦今春意，良人昨夜情。","誰能將旗鼓，一爲取龍城。"]', '["闻道黄龙戍，頻年不解兵。","可怜閨裏月，长在漢家營。","少婦今春意，良人昨夜情。","誰能將旗鼓，一爲取龙城。"]', '诗', 'shi', '', NULL, '雜詩三首 三 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0391d0b5-e133-4042-b2f6-cda55cbcdd5c', '剪綵', '剪綵', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["宮女憐芳樹，裁花競早榮。","寒依刀尺盡，春向綺羅生。","弱蔕盤絲發，香蕤結素成。","纖枝幸不棄，長就玉階傾。"]', '["宮女怜芳樹，裁花競早榮。","寒依刀尺尽，春向綺羅生。","弱蔕盤絲發，香蕤結素成。","纖枝幸不棄，长就玉階傾。"]', '诗', 'shi', '', NULL, '剪綵 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('378811bc-7daf-4769-b8c1-e0dc27f5110c', '和中書侍郎楊再思春夜宿直', '和中书侍郎楊再思春夜宿直', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["西禁青春滿，南端皓月微。","千廬宵駕合，五夜曉鐘稀。","星斗橫綸閣，天河度瑣闈。","煙光章奏裏，紛向夕郎飛。"]', '["西禁青春满，南端皓月微。","千廬宵駕合，五夜晓鐘稀。","星斗橫綸閣，天河度瑣闈。","煙光章奏裏，紛向夕郎飞。"]', '诗', 'shi', '', NULL, '和中書侍郎楊再思春夜宿直 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6374eebf-a2b0-4dca-82af-9dbe01305e0d', '和常州崔使君寒食夜', '和常州崔使君寒食夜', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["聞道清明近，春闈向夕闌。","行遊晝不厭，風物夜宜看。","斗柄更初轉，梅香暗裏殘。","無勞秉華燭，晴月在南端。"]', '["闻道清明近，春闈向夕闌。","行游晝不厭，风物夜宜看。","斗柄更初轉，梅香暗裏殘。","無勞秉华燭，晴月在南端。"]', '诗', 'shi', '', NULL, '和常州崔使君寒食夜 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('850d9fba-c517-4de4-b391-61aa0e254673', '和崔正諫登秋日早朝', '和崔正諫登秋日早朝', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["雞鳴朝謁滿，露白禁門秋。","爽氣臨旌戟，朝光暎冕旒。","河宗來獻寶，天子命焚裘。","獨負池陽議，言從建禮遊。"]', '["雞鳴朝謁满，露白禁门秋。","爽氣臨旌戟，朝光暎冕旒。","河宗来獻寶，天子命焚裘。","独負池陽議，言從建禮游。"]', '诗', 'shi', '', NULL, '和崔正諫登秋日早朝 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b52e374f-ebc9-4e26-a96b-73553f987953', '答甯處州書', '答甯处州书', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["書報天中赦，人從海上聞。","九泉開白日，六翮起青雲。","質幸恩先貸，情孤枉未分。","自憐涇渭別，誰與奏明君。"]', '["书報天中赦，人從海上闻。","九泉开白日，六翮起青云。","質幸恩先貸，情孤枉未分。","自怜涇渭別，誰與奏明君。"]', '诗', 'shi', '', NULL, '答甯處州書 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c70f20d-13fe-412e-8f42-c5a39ee16831', '李舍人山園送龐邵', '李舍人山园送龐邵', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["符傳有光輝，諠諠出帝畿。","東隣借山水，南陌駐驂騑。","握手涼風至，當歌秋日微。","高幨去勿緩，人吏待霜威。"]', '["符傳有光輝，諠諠出帝畿。","东隣借山水，南陌駐驂騑。","握手涼风至，當歌秋日微。","高幨去勿緩，人吏待霜威。"]', '诗', 'shi', '', NULL, '李舍人山園送龐邵 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f16cd2b4-b395-432f-888b-27a1246fdb32', '送陸侍御餘慶北使', '送陸侍御餘慶北使', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["古人貴將命，之子出輶軒。","受委當不辱，隨時敢贈言。","朔途際遼海，春思繞轘轅。","安得回白日，留歡盡綠樽。"]', '["古人貴將命，之子出輶軒。","受委當不辱，隨时敢贈言。","朔途際遼海，春思繞轘轅。","安得回白日，留歡尽綠樽。"]', '诗', 'shi', '', NULL, '送陸侍御餘慶北使 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00a68422-3760-4d1a-bb1b-81adad61c08b', '洛州蕭司兵謁兄還赴洛成禮', '洛州蕭司兵謁兄還赴洛成禮', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["棠棣日光輝，高襟應序歸。","來成鴻雁聚，去作鳳皇飛。","細草乘輕傳，驚花慘別衣。","灞亭春有酒，岐路惜芬菲。"]', '["棠棣日光輝，高襟應序归。","来成鴻雁聚，去作鳳皇飞。","細草乘轻傳，驚花慘別衣。","灞亭春有酒，岐路惜芬菲。"]', '诗', 'shi', '', NULL, '洛州蕭司兵謁兄還赴洛成禮 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5eb45a70-3279-4487-9268-18758f290cb7', '餞高唐州詢', '餞高唐州詢', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["弱冠相知早，中年不見多。","生涯在王事，客鬢各蹉跎。","良守初分岳，嘉聲即潤河。","還從漢闕下，傾耳聽中和。"]', '["弱冠相知早，中年不见多。","生涯在王事，客鬢各蹉跎。","良守初分岳，嘉声即潤河。","還從漢闕下，傾耳听中和。"]', '诗', 'shi', '', NULL, '餞高唐州詢 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82d50614-2c93-46eb-bed1-82740842146b', '餞唐郎中洛陽令', '餞唐郎中洛陽令', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["一臺推往妙，三史佇來修。","應宰鳧還集，辭郎雉少留。","郊筵乘落景，亭傳理殘秋。","願以弦歌暇，芝蘭想舊遊。"]', '["一台推往妙，三史佇来修。","應宰鳧還集，辞郎雉少留。","郊筵乘落景，亭傳理殘秋。","願以弦歌暇，芝蘭想旧游。"]', '诗', 'shi', '', NULL, '餞唐郎中洛陽令 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4c988e1-7771-45dc-8c48-80fe1451233c', '樂城白鶴寺', '乐城白鹤寺', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["碧海開龍藏，青雲起雁堂。","潮聲迎法鼓，雨氣濕天香。","樹接前山暗，溪承瀑水涼。","無言謫居遠，清淨得空王。"]', '["碧海开龙藏，青云起雁堂。","潮声迎法鼓，雨氣濕天香。","樹接前山暗，溪承瀑水涼。","無言謫居远，清淨得空王。"]', '诗', 'shi', '', NULL, '樂城白鶴寺 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a5ba65c-a7b6-4059-92c9-31c088efaa48', '遊少林寺', '游少林寺', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["長歌遊寶地，徙倚對珠林。","雁塔風霜古，龍池歲月深。","紺園澄夕霽，碧殿下秋陰。","歸路煙霞晚，山蟬處處吟。"]', '["长歌游寶地，徙倚对珠林。","雁塔风霜古，龙池歲月深。","紺园澄夕霽，碧殿下秋陰。","归路煙霞晚，山蟬处处吟。"]', '诗', 'shi', '', NULL, '遊少林寺 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dd79e76-4b32-43c0-9516-6f17a87c016c', '嶽館', '嶽館', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["洞壑仙人館，孤峰玉女臺。","空濛朝氣合，窈窕夕陽開。","流澗含輕雨，虛巖應薄雷。","正逢鸞與鶴，歌舞出天來。"]', '["洞壑仙人館，孤峰玉女台。","空濛朝氣合，窈窕夕陽开。","流澗含轻雨，虛巖應薄雷。","正逢鸾與鹤，歌舞出天来。"]', '诗', 'shi', '', NULL, '嶽館 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ff9bf9f-7434-4851-995f-43f366500c9e', '早發平昌島', '早發平昌島', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["解纜春風後，鳴榔曉漲前。","陽烏出海樹，雲雁下江煙。","積氣衝長島，浮光溢大川。","不能懷魏闕，心賞獨泠然。"]', '["解纜春风後，鳴榔晓漲前。","陽烏出海樹，云雁下江煙。","積氣衝长島，浮光溢大川。","不能懷魏闕，心賞独泠然。"]', '诗', 'shi', '', NULL, '早發平昌島 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63250717-a10a-4815-bcaf-175ede125559', '夜宿七盤嶺', '夜宿七盤嶺', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["獨遊千里外，高臥七盤西。","曉月臨窗近，天河入戶低。","芳春平仲綠，清夜子規啼。","浮客空留聽，褒城聞曙雞。"]', '["独游千里外，高臥七盤西。","晓月臨窗近，天河入戶低。","芳春平仲綠，清夜子規啼。","浮客空留听，褒城闻曙雞。"]', '诗', 'shi', '', NULL, '夜宿七盤嶺 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('616c4630-6fe7-46fb-8108-928e1425706a', '十三四時嘗從巫峽過他日偶然有思', '十三四时嘗從巫峽過他日偶然有思', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["小度巫山峽，荆南春欲分。","使君灘上草，神女館前雲。","樹悉江中見，猿多天外聞。","別來如夢裏，一想一氛氳。"]', '["小度巫山峽，荆南春欲分。","使君灘上草，神女館前云。","樹悉江中见，猿多天外闻。","別来如梦裏，一想一氛氳。"]', '诗', 'shi', '', NULL, '十三四時嘗從巫峽過他日偶然有思 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8645670-f21b-4437-96f7-bb8a6a6d5972', '初達驩州', '初達驩州', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["自昔聞銅柱，行來向一年。","不知林邑地，猶隔道明天。","雨露何時及？京華若個邊。","思君無限淚，堪作日南泉。"]', '["自昔闻銅柱，行来向一年。","不知林邑地，猶隔道明天。","雨露何时及？京华若個邊。","思君無限泪，堪作日南泉。"]', '诗', 'shi', '', NULL, '初達驩州 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e308da2f-7092-4d52-9bfd-0e60197017f1', '嶺表逢寒食', '嶺表逢寒食', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["嶺外無寒食，春來不見餳。","洛陽新甲子，何日是清明？","花柳爭朝發，軒車滿路迎。","帝鄉遙可念，腸斷報親情。"]', '["嶺外無寒食，春来不见餳。","洛陽新甲子，何日是清明？","花柳爭朝發，軒车满路迎。","帝乡遙可念，腸斷報親情。"]', '诗', 'shi', '', NULL, '嶺表逢寒食 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40d32391-64e6-4c4c-bc8b-61cbe581b6da', '驩州南亭夜望', '驩州南亭夜望', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["昨夜南亭望，分明夢洛中。","室家誰道別，兒女案嘗同。","忽覺猶言是，沈思始悟空。","肝腸餘幾寸，拭淚坐春風。"]', '["昨夜南亭望，分明梦洛中。","室家誰道別，兒女案嘗同。","忽覺猶言是，沈思始悟空。","肝腸餘幾寸，拭泪坐春风。"]', '诗', 'shi', '', NULL, '驩州南亭夜望 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49590ad5-2e5d-424d-8e89-be28ddb4adb0', '少遊荆湘因有是題', '少游荆湘因有是題', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["峴北焚蛟浦，巴東射雉田。","歲時宜楚俗，耆舊在襄川。","憶昨經過處，離今二十年。","因君訪生死，相識幾人全。"]', '["峴北焚蛟浦，巴东射雉田。","歲时宜楚俗，耆旧在襄川。","憶昨經過处，離今二十年。","因君訪生死，相識幾人全。"]', '诗', 'shi', '', NULL, '少遊荆湘因有是題 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10b11d93-1d65-4449-bc10-24dc2494a5dd', '咸陽覽古', '咸陽覽古', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["咸陽秦帝居，千載坐盈虛。","版築林光盡，壇場霤聽疎。","野橋疑望日，山火類焚書。","唯有驪峰在，空聞厚葬餘。"]', '["咸陽秦帝居，千載坐盈虛。","版築林光尽，壇場霤听疎。","野橋疑望日，山火類焚书。","唯有驪峰在，空闻厚葬餘。"]', '诗', 'shi', '', NULL, '咸陽覽古 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef89af2c-3616-46ad-a2e9-4bb3300fe7e1', '覽鏡', '覽镜', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["霏霏日搖蕙，騷騷風灑蓮。","時芳固相奪，俗態豈恆堅。","恍忽夜川裏，蹉跎朝鏡前。","紅顏與壯志，太息此流年。"]', '["霏霏日搖蕙，騷騷风灑蓮。","时芳固相奪，俗態豈恆堅。","恍忽夜川裏，蹉跎朝镜前。","紅顏與壯志，太息此流年。"]', '诗', 'shi', '', NULL, '覽鏡 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72d0b232-6662-4199-a74f-ce4000d620df', '題椰子樹', '題椰子樹', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["日南椰子樹，香褭出風塵。","叢生調木首，圓實檳榔身。","玉房九霄露，碧葉四時春。","不及塗林果，移根隨漢臣。"]', '["日南椰子樹，香褭出风塵。","叢生調木首，圓實檳榔身。","玉房九霄露，碧葉四时春。","不及塗林果，移根隨漢臣。"]', '诗', 'shi', '', NULL, '題椰子樹 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f711032-2b3d-4603-9578-51209add995d', '同獄者歎獄中無燕', '同獄者歎獄中無燕', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["何許乘春燕，多知辨夏臺。","三時欲併盡，雙影未嘗來。","食蕋嫌叢棘，銜泥怯死灰。","不如黃雀語，能雪冶長猜。"]', '["何許乘春燕，多知辨夏台。","三时欲併尽，雙影未嘗来。","食蕋嫌叢棘，銜泥怯死灰。","不如黄雀語，能雪冶长猜。"]', '诗', 'shi', '', NULL, '同獄者歎獄中無燕 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31dd857a-849d-42bf-a9ce-5eda1bdf0a08', '則天門赦改年', '則天门赦改年', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["聖人宥天下，幽鑰動圜狴。","六甲迎黃氣，三元降紫泥。","籠僮上西鼓，振迅廣陽雞。","歌舞將金帛，汪洋被遠黎。"]', '["聖人宥天下，幽鑰动圜狴。","六甲迎黄氣，三元降紫泥。","籠僮上西鼓，振迅廣陽雞。","歌舞將金帛，汪洋被远黎。"]', '诗', 'shi', '', NULL, '則天門赦改年 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2eea58f3-4c5c-411b-92ac-8abf530fae6d', '喜赦', '喜赦', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["去歲投荒客，今春肆眚歸。","律通幽谷暖，盆舉太陽輝。","喜氣迎冤氣，青衣報白衣。","還將合浦葉，俱向洛城飛。"]', '["去歲投荒客，今春肆眚归。","律通幽谷暖，盆舉太陽輝。","喜氣迎冤氣，青衣報白衣。","還將合浦葉，俱向洛城飞。"]', '诗', 'shi', '', NULL, '喜赦 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('781d15eb-381b-4c8e-8484-b5e072c8ba20', '秦州薛都督挽詞', '秦州薛都督挽词', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["十里絳山幽，千年汾水流。","碑傳門客建，劒是故人留。","隴樹烟含夕，山門月對秋。","古來鐘鼎盛，共盡一蒿丘。"]', '["十里絳山幽，千年汾水流。","碑傳门客建，劒是故人留。","隴樹烟含夕，山门月对秋。","古来鐘鼎盛，共尽一蒿丘。"]', '诗', 'shi', '', NULL, '秦州薛都督挽詞 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72b48e21-072a-464e-afc5-1576f7357086', '天官崔侍郎夫人盧氏挽歌', '天官崔侍郎夫人盧氏挽歌', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["偕老言何謬，香魂事永違。","潘魚從此隔，陳鳳宛然飛。","埋鏡泉中暗，藏鐙地下微。","猶憑少君術，彷彿覩容輝。"]', '["偕老言何謬，香魂事永違。","潘鱼從此隔，陳鳳宛然飞。","埋镜泉中暗，藏鐙地下微。","猶憑少君術，彷彿覩容輝。"]', '诗', 'shi', '', NULL, '天官崔侍郎夫人盧氏挽歌 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09bf1776-d49a-4d9a-a6fa-def40be46fe0', '章懷太子靖妃挽詞', '章懷太子靖妃挽词', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["彤史佳聲載，青宮懿範留。","形將鸞鏡隱，魂伴鳳笙遊。","送馬嘶殘日，新螢落晚秋。","不知蒿里曙，空見隴雲愁。"]', '["彤史佳声載，青宮懿範留。","形將鸾镜隐，魂伴鳳笙游。","送马嘶殘日，新螢落晚秋。","不知蒿里曙，空见隴云愁。"]', '诗', 'shi', '', NULL, '章懷太子靖妃挽詞 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0eb289a8-73e9-4284-9132-d30b5118ba83', '奉和立春遊苑迎春', '奉和立春游苑迎春', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["東郊暫轉迎春仗，上苑初飛行慶杯。","風射蛟冰千片斷，氣衝魚鑰九關開。","林中覓草纔生蕙，殿裏爭花併是梅。","歌吹銜恩歸路晚，棲烏半下鳳城來。"]', '["东郊暫轉迎春仗，上苑初飞行慶杯。","风射蛟冰千片斷，氣衝鱼鑰九关开。","林中覓草纔生蕙，殿裏爭花併是梅。","歌吹銜恩归路晚，棲烏半下鳳城来。"]', '诗', 'shi', '', NULL, '奉和立春遊苑迎春 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d7195e8-759e-494d-9b4e-3aa59a3693a8', '人日重宴大明宮賜綵縷人勝應制', '人日重宴大明宮賜綵縷人勝應制', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["拂旦雞鳴仙衞陳，憑高龍首帝城春。","千官黼帳杯前壽，百福香匳勝裏人。","山鳥初來猶怯囀，林花未發已偷新。","天文正應韶光轉，設報懸知用此辰。"]', '["拂旦雞鳴仙衞陳，憑高龙首帝城春。","千官黼帳杯前壽，百福香匳勝裏人。","山鸟初来猶怯囀，林花未發已偷新。","天文正應韶光轉，設報懸知用此辰。"]', '诗', 'shi', '', NULL, '人日重宴大明宮賜綵縷人勝應制 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57b7d0ea-19f2-4248-b147-77347054baae', '奉和春初幸太平公主南莊應制', '奉和春初幸太平公主南莊應制', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["主家山第早春歸，御輦春遊繞翠微。","買地鋪金曾作埒，尋河取石舊支機。","雲間樹色千花滿，竹裏泉聲百道飛。","自有神仙鳴鳳曲，併將歌舞報恩暉。"]', '["主家山第早春归，御輦春游繞翠微。","買地鋪金曾作埒，尋河取石旧支機。","云间樹色千花满，竹裏泉声百道飞。","自有神仙鳴鳳曲，併將歌舞報恩暉。"]', '诗', 'shi', '', NULL, '奉和春初幸太平公主南莊應制 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20380cb7-de3d-467b-a111-075dbc0400c0', '奉和春日幸望春宮應制', '奉和春日幸望春宮應制', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["芳郊綠野散春晴，複道離宮煙霧生。","楊柳千條花欲綻，蒲萄百丈蔓初縈。","林香酒氣元相入，鳥囀歌聲各自成。","定是風光牽宿醉，來晨復得幸昆明。"]', '["芳郊綠野散春晴，複道離宮煙霧生。","楊柳千條花欲綻，蒲萄百丈蔓初縈。","林香酒氣元相入，鸟囀歌声各自成。","定是风光牽宿醉，来晨复得幸昆明。"]', '诗', 'shi', '', NULL, '奉和春日幸望春宮應制 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05a58c18-1ae7-4405-9361-e35f7a5bcd3f', '侍宴安樂公主新宅應制', '侍宴安乐公主新宅應制', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["皇家貴主好神仙，別業初開雲漢邊。","山出盡如鳴鳳嶺，池成不讓飲龍川。","妝樓翠幌教春住，舞閣金鋪借日懸。","敬從乘輿來此地，稱觴獻壽樂鈞天。"]', '["皇家貴主好神仙，別業初开云漢邊。","山出尽如鳴鳳嶺，池成不讓饮龙川。","妝楼翠幌教春住，舞閣金鋪借日懸。","敬從乘輿来此地，稱觴獻壽乐鈞天。"]', '诗', 'shi', '', NULL, '侍宴安樂公主新宅應制 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c9876a4-e979-4233-898b-d11f96311f25', '龍池篇', '龙池篇', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["龍池躍龍龍已飛，龍德先天天不違。","池開天漢分黃道，龍向天門入紫微。","邸第樓臺多氣色，君王鳧雁有光輝。","爲報寰中百川水，來朝此地莫東歸。"]', '["龙池躍龙龙已飞，龙德先天天不違。","池开天漢分黄道，龙向天门入紫微。","邸第楼台多氣色，君王鳧雁有光輝。","爲報寰中百川水，来朝此地莫东归。"]', '诗', 'shi', '', NULL, '龍池篇 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4921a827-1bf3-4b5c-90d6-cc124406f5ba', '興慶池侍宴應制', '兴慶池侍宴應制', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["碧水澄潭暎遠空，紫雲香駕御微風。","漢家城闕疑天上，秦地山川似鏡中。","向浦回舟萍已綠，分林蔽殿槿初紅。","古來徒羨橫汾賞，今日宸遊聖藻雄。"]', '["碧水澄潭暎远空，紫云香駕御微风。","漢家城闕疑天上，秦地山川似镜中。","向浦回舟萍已綠，分林蔽殿槿初紅。","古来徒羨橫汾賞，今日宸游聖藻雄。"]', '诗', 'shi', '', NULL, '興慶池侍宴應制 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18a656df-00f4-4000-b36e-2d0e490fbb99', '從幸香山寺應制', '從幸香山寺應制', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["南山奕奕通丹禁，北闕峨峨連翠雲。","嶺上樓臺千地起，城中鐘鼓四天聞。","旃檀曉閣金輿度，鸚鵡晴林采眊分。","願以醍醐參聖酒，還將[衹]苑當秋汾。"]', '["南山奕奕通丹禁，北闕峨峨連翠云。","嶺上楼台千地起，城中鐘鼓四天闻。","旃檀晓閣金輿度，鸚鵡晴林采眊分。","願以醍醐參聖酒，還將[衹]苑當秋汾。"]', '诗', 'shi', '', NULL, '從幸香山寺應制 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25de0765-6846-4da5-b966-ae1bade948e9', '紅樓院應制', '紅楼院應制', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["紅樓疑見白毫光，寺逼宸居福盛唐。","支遁愛山情謾切，曇摩泛海路空長。","經聲夜息聞天語，爐氣晨飄接御香。","誰謂此中難可到，自憐深院得徊翔。"]', '["紅楼疑见白毫光，寺逼宸居福盛唐。","支遁愛山情謾切，曇摩泛海路空长。","經声夜息闻天語，爐氣晨飄接御香。","誰謂此中难可到，自怜深院得徊翔。"]', '诗', 'shi', '', NULL, '紅樓院應制 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7875082b-2898-40df-bfab-681426ed3a03', '再入道場紀事應制', '再入道場紀事應制', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["南方歸去再生天，內殿今年異昔年。","見闢乾坤新定位，看題日月更高懸。","行隨香輦登仙路，坐近爐煙講法筵。","自喜恩深陪侍從，兩朝長在聖人前。"]', '["南方归去再生天，內殿今年異昔年。","见闢乾坤新定位，看題日月更高懸。","行隨香輦登仙路，坐近爐煙講法筵。","自喜恩深陪侍從，兩朝长在聖人前。"]', '诗', 'shi', '', NULL, '再入道場紀事應制 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d249927-ee35-46b1-8c00-05d4b6adadfb', '嵩山石淙侍宴應制', '嵩山石淙侍宴應制', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["金輿旦下綠雲衢，綵殿晴臨碧澗隅。","溪水泠泠雜行漏，山煙片片繞香爐。","仙人六膳調神鼎，玉女三漿捧帝壺。","自惜汾陽紆道駕，無如太室覽真圖。"]', '["金輿旦下綠云衢，綵殿晴臨碧澗隅。","溪水泠泠杂行漏，山煙片片繞香爐。","仙人六膳調神鼎，玉女三漿捧帝壺。","自惜汾陽紆道駕，無如太室覽真圖。"]', '诗', 'shi', '', NULL, '嵩山石淙侍宴應制 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9521e2b-963e-4d90-acf3-d87c2a135071', '古意呈補闕喬知之', '古意呈補闕喬知之', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["盧家少婦鬱金堂，海燕雙棲玳瑁梁。","九月寒砧催木葉，十年征戍憶遼陽。","白狼河北音書斷，丹鳳城南秋夜長。","誰謂含愁獨不見，更教明月照流黃。"]', '["盧家少婦鬱金堂，海燕雙棲玳瑁梁。","九月寒砧催木葉，十年征戍憶遼陽。","白狼河北音书斷，丹鳳城南秋夜长。","誰謂含愁独不见，更教明月照流黄。"]', '诗', 'shi', '', NULL, '古意呈補闕喬知之 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('052d46fe-db9c-42ec-a42a-0ac433f26a65', '遙同杜員外審言過嶺', '遙同杜員外審言過嶺', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["天長地闊嶺頭分，去國離家見白雲。","洛浦風光何所似，崇山瘴癘不堪聞。","南浮漲海人何處？北望衡陽雁幾羣。"]', '["天长地闊嶺头分，去国離家见白云。","洛浦风光何所似，崇山瘴癘不堪闻。","南浮漲海人何处？北望衡陽雁幾羣。"]', '诗', 'shi', '', NULL, '遙同杜員外審言過嶺 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a04655d3-9d60-4544-a046-3c3f0785bcfc', '和上巳連寒食有懷京洛', '和上巳連寒食有懷京洛', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["天津御柳碧遙遙，軒騎相從半下朝。","行樂光輝寒食借，太平歌舞晚春饒。","紅妝樓下東迴輦，青草洲邊南渡橋。","坐見司空掃西第，看君侍從落花朝。"]', '["天津御柳碧遙遙，軒騎相從半下朝。","行乐光輝寒食借，太平歌舞晚春饒。","紅妝楼下东迴輦，青草洲邊南渡橋。","坐见司空掃西第，看君侍從落花朝。"]', '诗', 'shi', '', NULL, '和上巳連寒食有懷京洛 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63e0fa21-7f2a-449f-b5fb-1b20d7ced3a9', '陪幸太平公主南莊詩', '陪幸太平公主南莊诗', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["主第山門起灞川，宸遊風景入初年。","鳳皇樓下交天仗，烏鵲橋頭敞御筵。","往往花間逢綵石，時時竹裏見紅泉。","今朝扈蹕平陽館，不羨乘槎雲漢邊。"]', '["主第山门起灞川，宸游风景入初年。","鳳皇楼下交天仗，烏鵲橋头敞御筵。","往往花间逢綵石，时时竹裏见紅泉。","今朝扈蹕平陽館，不羨乘槎云漢邊。"]', '诗', 'shi', '', NULL, '陪幸太平公主南莊詩 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3253a45-9c78-4b9f-b9ad-a07644697800', '守歲應制', '守歲應制', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["南渡輕冰解渭橋，東方樹色起招搖。","天子迎春取今夜，王公獻壽用明朝。","殿上燈人爭烈火，宮中侲子亂驅妖。","宜將歲酒調神藥，聖祚千春萬國朝。"]', '["南渡轻冰解渭橋，东方樹色起招搖。","天子迎春取今夜，王公獻壽用明朝。","殿上灯人爭烈火，宮中侲子亂驱妖。","宜將歲酒調神藥，聖祚千春万国朝。"]', '诗', 'shi', '', NULL, '守歲應制 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13a09b36-f435-47c6-b751-ebbe59d799d8', '陪幸韋嗣立山莊', '陪幸韋嗣立山莊', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["台階好赤松，別業對青峯。","茆室承三顧，花源接九重。","虹旗縈秀木，鳳輦拂疎筇。","逕直千官擁，溪長萬騎容。","水堂開禹膳，山閣獻堯鍾。","皇鑑清居遠，天文睿獎濃。","巖泉他夕夢，漁釣往年逢。","共榮丞相府，偏降逸人封。"]', '["台階好赤松，別業对青峯。","茆室承三顧，花源接九重。","虹旗縈秀木，鳳輦拂疎筇。","逕直千官擁，溪长万騎容。","水堂开禹膳，山閣獻堯鍾。","皇鑑清居远，天文睿獎濃。","巖泉他夕梦，漁釣往年逢。","共榮丞相府，偏降逸人封。"]', '诗', 'shi', '', NULL, '陪幸韋嗣立山莊 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86060c5d-4655-4bfd-8e5d-35fa45e3b448', '扈從出長安應制', '扈從出长安應制', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["漢宅規模壯，周都景命隆。","西賓讓東主，法駕幸天中。","太史占星應，春官奏日同。","旌門起長樂，帳殿出新豐。","翕習黃山下，紆徐清渭東。","金麾張畫月，珠幰戴松風。","是節嚴陰始，寒郊散野蓬。","薄霜沾上路，殘雪繞離宮。","賜帛矜耆老，褰旒問小童。","復除恩載洽，望秩禮新崇。","臣忝承明召，多慙獻賦雄。"]', '["漢宅規模壯，周都景命隆。","西賓讓东主，法駕幸天中。","太史占星應，春官奏日同。","旌门起长乐，帳殿出新豐。","翕習黄山下，紆徐清渭东。","金麾張畫月，珠幰戴松风。","是節嚴陰始，寒郊散野蓬。","薄霜沾上路，殘雪繞離宮。","賜帛矜耆老，褰旒问小童。","复除恩載洽，望秩禮新崇。","臣忝承明召，多慙獻賦雄。"]', '诗', 'shi', '', NULL, '扈從出長安應制 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bc62fb4-dd3d-40ed-8ee5-11dafbefe8a0', '初冬從幸漢故青門應制', '初冬從幸漢故青门應制', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["漢王建都邑，渭水對青門。","朝市俱東逝，墳陵共北原。","荒涼蕭相闕，蕪沒邵平園。","全盛今何在，英雄難重論。","故基仍嶽立，遺堞尚雲屯。","當極土功壯，安知人力煩。","天遊戒東首，懷昔駐龍軒。","何必金湯固，無如道德藩。","微臣諒多幸，參乘偶殊恩。","預此陳古事，敢奏興亡言。"]', '["漢王建都邑，渭水对青门。","朝市俱东逝，墳陵共北原。","荒涼蕭相闕，蕪沒邵平园。","全盛今何在，英雄难重論。","故基仍嶽立，遺堞尚云屯。","當極土功壯，安知人力煩。","天游戒东首，懷昔駐龙軒。","何必金湯固，無如道德藩。","微臣諒多幸，參乘偶殊恩。","預此陳古事，敢奏兴亡言。"]', '诗', 'shi', '', NULL, '初冬從幸漢故青門應制 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa53e079-7b40-4f59-bffd-3f6b1841afa7', '昆明池侍宴應制', '昆明池侍宴應制', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["武帝伐昆明，穿池習五兵。","水同河漢在，館有豫章名。","我后光天德，垂衣文教成。","黷兵非帝念，勞物豈皇情。","春仗過鯨沼，雲旗出鳳城。","靈魚銜寶躍，仙女廢機迎。","柳拂旌門暗，蘭依帳殿生。","還如流水曲，日晚棹歌清。"]', '["武帝伐昆明，穿池習五兵。","水同河漢在，館有豫章名。","我后光天德，垂衣文教成。","黷兵非帝念，勞物豈皇情。","春仗過鯨沼，云旗出鳳城。","靈鱼銜寶躍，仙女廢機迎。","柳拂旌门暗，蘭依帳殿生。","還如流水曲，日晚棹歌清。"]', '诗', 'shi', '', NULL, '昆明池侍宴應制 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9a36948-1419-49f4-86ab-799bc8b95168', '白蓮花亭侍宴應制', '白蓮花亭侍宴應制', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["九日陪天仗，三秋幸禁林。","霜威變綠樹，雲氣落青岑。","水殿黃花合，山亭絳葉深。","朱旗夾小徑，寶馬駐清潯。","苑吏收寒果，饔人膳野禽。","承歡不覺暝，遙響素秋砧。"]', '["九日陪天仗，三秋幸禁林。","霜威变綠樹，云氣落青岑。","水殿黄花合，山亭絳葉深。","朱旗夾小徑，寶马駐清潯。","苑吏收寒果，饔人膳野禽。","承歡不覺暝，遙响素秋砧。"]', '诗', 'shi', '', NULL, '白蓮花亭侍宴應制 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61592830-5a9b-4356-93e0-793bd3c8138f', '仙萼池亭侍宴應制', '仙萼池亭侍宴應制', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["步輦尋丹嶂，行宮在翠微。","川長看鳥滅，谷轉聽猿稀。","天磴扶階迥，雲泉透戶飛。","閑花開石竹，幽葉吐薔薇。","徑狹難留騎，亭寒欲進衣。","白龜來獻壽，仙吹返彤闈。"]', '["步輦尋丹嶂，行宮在翠微。","川长看鸟滅，谷轉听猿稀。","天磴扶階迥，云泉透戶飞。","闲花开石竹，幽葉吐薔薇。","徑狹难留騎，亭寒欲進衣。","白龟来獻壽，仙吹返彤闈。"]', '诗', 'shi', '', NULL, '仙萼池亭侍宴應制 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d2bcb20-4765-47e9-9d3b-c7c4e6a7d9f4', '奉和晦日駕幸昆明池應制', '奉和晦日駕幸昆明池應制', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["法駕乘春轉，神池象漢廻。","雙星移舊石，孤月隱殘灰。","戰鷁逢時去，恩魚望幸來。","山花緹騎繞，堤柳幔城開。","思逸橫汾唱，歡留宴鎬杯。","微臣雕朽質，羞覩豫章材。"]', '["法駕乘春轉，神池象漢廻。","雙星移旧石，孤月隐殘灰。","戰鷁逢时去，恩鱼望幸来。","山花緹騎繞，堤柳幔城开。","思逸橫汾唱，歡留宴鎬杯。","微臣雕朽質，羞覩豫章材。"]', '诗', 'shi', '', NULL, '奉和晦日駕幸昆明池應制 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bf96549-f3c6-43cb-82b1-a990710e1975', '奉和聖製幸禮部尚書竇希玠宅', '奉和聖製幸禮部尚书竇希玠宅', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["北闕垂旒暇，南宮聽履廻。","天臨翔鳳轉，恩向躍龍開。","蘭氣薰仙帳，榴花引御杯。","水從金穴吐，雲是玉衣來。","池影搖歌席，林香散舞臺。","不知行漏晚，清蹕尚裴徊。"]', '["北闕垂旒暇，南宮听履廻。","天臨翔鳳轉，恩向躍龙开。","蘭氣薰仙帳，榴花引御杯。","水從金穴吐，云是玉衣来。","池影搖歌席，林香散舞台。","不知行漏晚，清蹕尚裴徊。"]', '诗', 'shi', '', NULL, '奉和聖製幸禮部尚書竇希玠宅 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28c616fa-2fab-40c7-b4e1-eec241c762cc', '釣竿篇', '釣竿篇', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["朝日斂紅煙，垂竿向綠川。","人疑天上坐，魚似鏡中懸。","避檝時驚透，猜鉤每誤牽。","湍危不理轄，潭靜欲留船。","釣玉君徒尚，徵金我未賢。","爲看芳餌下，貪得會無筌。"]', '["朝日斂紅煙，垂竿向綠川。","人疑天上坐，鱼似镜中懸。","避檝时驚透，猜鉤每誤牽。","湍危不理轄，潭静欲留船。","釣玉君徒尚，徵金我未賢。","爲看芳餌下，貪得會無筌。"]', '诗', 'shi', '', NULL, '釣竿篇 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbef852a-ec34-4833-8957-d82450693f91', '和戶部岑尚書參迹樞揆', '和戶部岑尚书參迹樞揆', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["大君制六合，良佐參萬機。","大業永開泰，臣道日光輝。","鹽梅和鼎食，家聲衆所歸。","漢章題楚劒，鄭武襲緇衣。","理識當朝遠，文華振古希。","風雲神契合，舟檝道心微。","廟堂喜容與，時物逓芳菲。","御柳垂仙掖，公槐覆禮闈。","昔陪鵷鷺後，今望鵾鵬飛。","徒御清風頌，巴歌聊自揮。"]', '["大君制六合，良佐參万機。","大業永开泰，臣道日光輝。","鹽梅和鼎食，家声衆所归。","漢章題楚劒，鄭武襲緇衣。","理識當朝远，文华振古希。","风云神契合，舟檝道心微。","廟堂喜容與，时物逓芳菲。","御柳垂仙掖，公槐覆禮闈。","昔陪鵷鷺後，今望鵾鵬飞。","徒御清风頌，巴歌聊自揮。"]', '诗', 'shi', '', NULL, '和戶部岑尚書參迹樞揆 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5a05db5-cc5b-484f-9517-0782135c2b3b', '同李舍人冬日集安樂公主山池', '同李舍人冬日集安乐公主山池', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["嘗聞天女貴，家即帝宮連。","亭插宜春果，山衝太液泉。","橋低烏鵲夜，臺起鳳皇年。","故事猶如此，新圖更可憐。","紫巖妝閣透，青嶂妓樓懸。","峰奪香爐巧，池偷明鏡圓。","梅花寒待雪，桂葉晚留煙。","興盡方投轄，金聲還復傳。"]', '["嘗闻天女貴，家即帝宮連。","亭插宜春果，山衝太液泉。","橋低烏鵲夜，台起鳳皇年。","故事猶如此，新圖更可怜。","紫巖妝閣透，青嶂妓楼懸。","峰奪香爐巧，池偷明镜圓。","梅花寒待雪，桂葉晚留煙。","兴尽方投轄，金声還复傳。"]', '诗', 'shi', '', NULL, '同李舍人冬日集安樂公主山池 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8e61a77-dc28-4e92-a954-fbfa49eabdde', '酬蘇員外味道夏晚寓直省中見贈', '酬蘇員外味道夏晚寓直省中见贈', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["並命登仙閣，分曹直禮闈。","大官供宿膳，侍史護朝衣。","卷幔天河入，開窗月露微。","小池殘暑退，高樹早涼歸。","冠劒無時釋，軒車待漏飛。","明朝題漢柱，三署有光輝。"]', '["並命登仙閣，分曹直禮闈。","大官供宿膳，侍史護朝衣。","卷幔天河入，开窗月露微。","小池殘暑退，高樹早涼归。","冠劒無时釋，軒车待漏飞。","明朝題漢柱，三署有光輝。"]', '诗', 'shi', '', NULL, '酬蘇員外味道夏晚寓直省中見贈 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69292dcc-3a7e-4048-badd-aa403d6b35c7', '和韋舍人早朝', '和韋舍人早朝', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["閶闔連雲起，巖廊拂霧開。","玉珂龍影度，珠履雁行來。","長樂宵鐘盡，明光曉奏催。","一經推舊德，五字擢英才。","儼若神仙去，紛從霄漢廻。","千春奉休曆，分禁喜趨陪。"]', '["閶闔連云起，巖廊拂霧开。","玉珂龙影度，珠履雁行来。","长乐宵鐘尽，明光晓奏催。","一經推旧德，五字擢英才。","儼若神仙去，紛從霄漢廻。","千春奉休曆，分禁喜趨陪。"]', '诗', 'shi', '', NULL, '和韋舍人早朝 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4af7c006-1f82-42d4-8792-47f0fb5dda77', '自考功員外授給事中', '自考功員外授給事中', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["南省推丹地，東曹拜瑣闈。","惠移雙管筆，恩降五時衣。","出入宜真選，遭逢每濫飛。","器慙公理拙，才謝子雲微。","案牘遺常禮，朋僚隔等威。","上台行揖讓，中禁動光輝。","旭日千門起，初春八舍歸。","贈蘭聞宿昔，談樹隱芳菲。","何幸鹽梅處，唯憂對問機。","省躬知任重，寧止冒榮非。"]', '["南省推丹地，东曹拜瑣闈。","惠移雙管笔，恩降五时衣。","出入宜真選，遭逢每濫飞。","器慙公理拙，才謝子云微。","案牘遺常禮，朋僚隔等威。","上台行揖讓，中禁动光輝。","旭日千门起，初春八舍归。","贈蘭闻宿昔，談樹隐芳菲。","何幸鹽梅处，唯憂对问機。","省躬知任重，寧止冒榮非。"]', '诗', 'shi', '', NULL, '自考功員外授給事中 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdd45a2c-15e1-4b40-b243-0f127d9e0151', '和元舍人萬頃臨池翫月戲爲新體', '和元舍人万頃臨池翫月戲爲新體', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["春風搖碧樹，秋霧卷丹臺。","復有相宜夕，池清月正開。","玉流含吹動，金魄度雲來。","熠爚光如沸，翩翾景若摧。","半環投積草，碎璧聚流杯。","夜久平無煥，天晴皎未隤。","鏡將池作匣，珠以岸爲胎。","有美司言暇，高興獨悠哉。","揮翰初難擬，飛名豈易陪。","夜光殊在握，了了見沈灰。"]', '["春风搖碧樹，秋霧卷丹台。","复有相宜夕，池清月正开。","玉流含吹动，金魄度云来。","熠爚光如沸，翩翾景若摧。","半环投積草，碎璧聚流杯。","夜久平無煥，天晴皎未隤。","镜將池作匣，珠以岸爲胎。","有美司言暇，高兴独悠哉。","揮翰初难擬，飞名豈易陪。","夜光殊在握，了了见沈灰。"]', '诗', 'shi', '', NULL, '和元舍人萬頃臨池翫月戲爲新體 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57d2e886-c491-487c-aa74-7526a30434a0', '酬楊給事兼見贈臺中', '酬楊給事兼见贈台中', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["子雲推辨博，公理擅詞雄。","始自尚書省，旋聞給事中。","言從溫室祕，籍向瑣闈通。","顧我叨郎署，慙無草奏功。","分曹八舍斷，解袂五時空。","宿昔陪餘論，平生賴擊蒙。","神仙應東掖，雲霧限南宮。","忽枉瓊瑤贈，長歌蘭渚風。"]', '["子云推辨博，公理擅词雄。","始自尚书省，旋闻給事中。","言從溫室祕，籍向瑣闈通。","顧我叨郎署，慙無草奏功。","分曹八舍斷，解袂五时空。","宿昔陪餘論，平生賴擊蒙。","神仙應东掖，云霧限南宮。","忽枉瓊瑤贈，长歌蘭渚风。"]', '诗', 'shi', '', NULL, '酬楊給事兼見贈臺中 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09ce8658-5174-43e6-a693-f58a7ef8dd32', '九真山淨居寺謁無礙上人', '九真山淨居寺謁無礙上人', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["大士生天竺，分身化日南。","人中出煩惱，山下即伽藍。","小澗香爲剎，危峰石作龕。","候禪青鴿乳，窺講白猿參。","藤愛雲間壁，花憐石下潭。","泉行幽供好，林挂浴衣堪。","弟子哀無識，醫王惜未談。","機疑聞不二，蒙昧即朝三。","欲究因緣理，聊寬放棄慙。","超然虎溪夕，雙樹下虛嵐。"]', '["大士生天竺，分身化日南。","人中出煩惱，山下即伽藍。","小澗香爲剎，危峰石作龕。","候禪青鴿乳，窺講白猿參。","藤愛云间壁，花怜石下潭。","泉行幽供好，林挂浴衣堪。","弟子哀無識，醫王惜未談。","機疑闻不二，蒙昧即朝三。","欲究因緣理，聊寬放棄慙。","超然虎溪夕，雙樹下虛嵐。"]', '诗', 'shi', '', NULL, '九真山淨居寺謁無礙上人 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3eaef5d7-9118-435a-ac36-e26540edbcf2', '夜遊', '夜游', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["今夕重門啟，遊春得夜芳。","月華連晝色，燈影雜星光。","南陌青絲騎，東鄰紅粉妝。","管弦遙辨曲，羅綺暗聞香。","人擁行歌路，車攢鬬舞場。","經過猶未已，鐘鼓出長楊。"]', '["今夕重门啟，游春得夜芳。","月华連晝色，灯影杂星光。","南陌青絲騎，东鄰紅粉妝。","管弦遙辨曲，羅綺暗闻香。","人擁行歌路，车攢鬬舞場。","經過猶未已，鐘鼓出长楊。"]', '诗', 'shi', '', NULL, '夜遊 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de11b09a-25f2-4267-b9a9-6334da20f73c', '登瀛州南城樓寄遠', '登瀛州南城楼寄远', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["層城起麗譙，憑覽出重霄。","茲地多形勝，中天宛寂寥。","四榮摩鸛鶴，百拱厲風飆。","北際燕王館，東連秦帝橋。","晴光七郡滿，春色兩河遙。","傲睨非吾土，躊躇適遠囂。","離居欲有贈，春草寄長謠。"]', '["層城起丽譙，憑覽出重霄。","茲地多形勝，中天宛寂寥。","四榮摩鸛鹤，百拱厲风飆。","北際燕王館，东連秦帝橋。","晴光七郡满，春色兩河遙。","傲睨非吾土，躊躇適远囂。","離居欲有贈，春草寄长謠。"]', '诗', 'shi', '', NULL, '登瀛州南城樓寄遠 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('385583d6-9a4d-4e07-baf6-256cb67f49bf', '塞北二首 一', '塞北二首 一', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["虜障天驕起，秦城地脉分。","柏壇飛五將，梅吹動三軍。","鋒刃奔濤色，旌旗焰火文。","朔風吹汗漫，飄礫灑轒輼。","海氣如秋雨，邊烽似夏雲。","二庭無歲月，百戰有功勳。","形影隨魚貫，音書在雁羣。","歸來拜天子，凱樂助南薰。"]', '["虜障天驕起，秦城地脉分。","柏壇飞五將，梅吹动三軍。","鋒刃奔濤色，旌旗焰火文。","朔风吹汗漫，飄礫灑轒輼。","海氣如秋雨，邊烽似夏云。","二庭無歲月，百戰有功勳。","形影隨鱼貫，音书在雁羣。","归来拜天子，凱乐助南薰。"]', '诗', 'shi', '', NULL, '塞北二首 一 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a611c4f0-e97c-4cb1-ab4c-fcd5b4a8a19d', '塞北二首 二', '塞北二首 二', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["胡騎犯邊埃，風從丑上來。","五原烽火急，六郡羽書催。","冰壯飛狐[冷]，霜濃候雁哀。","將軍朝授鉞，戰士夜銜枚。","紫塞金河裏，蔥山鐵勒隈。","蓮花秋劒發，桂葉曉旗開。","秘略三軍動，妖氛百戰摧。","何言投筆去，終作勒銘回。"]', '["胡騎犯邊埃，风從丑上来。","五原烽火急，六郡羽书催。","冰壯飞狐[冷]，霜濃候雁哀。","將軍朝授鉞，戰士夜銜枚。","紫塞金河裏，蔥山鐵勒隈。","蓮花秋劒發，桂葉晓旗开。","秘略三軍动，妖氛百戰摧。","何言投笔去，終作勒銘回。"]', '诗', 'shi', '', NULL, '塞北二首 二 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbce5180-34f2-4d50-9a36-9db07635d349', '李員外秦援宅觀妓', '李員外秦援宅观妓', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["盈盈粉署郎，五日宴春光。","選客虛前館，徵聲徧後堂。","玉釵翠羽飾，羅袖鬱金香。","拂黛隨時廣，挑鬟出意長。","囀歌遙合態，度舞暗成行。","巧落梅庭裏，斜光暎曉妝。"]', '["盈盈粉署郎，五日宴春光。","選客虛前館，徵声徧後堂。","玉釵翠羽飾，羅袖鬱金香。","拂黛隨时廣，挑鬟出意长。","囀歌遙合態，度舞暗成行。","巧落梅庭裏，斜光暎晓妝。"]', '诗', 'shi', '', NULL, '李員外秦援宅觀妓 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afeff31f-dad6-4dd6-b457-4e3ece085554', '送韋商州弼', '送韋商州弼', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["會府應文昌，商山鎮國陽。","聞君監郡史，蹔罷尚書郎。","王事嗟相失，人情貴不忘。","累年同畫省，四海接文場。","點翰芳春色，傳杯明月光。","故交從此去，遙憶紫芝香。"]', '["會府應文昌，商山鎮国陽。","闻君監郡史，蹔罷尚书郎。","王事嗟相失，人情貴不忘。","累年同畫省，四海接文場。","点翰芳春色，傳杯明月光。","故交從此去，遙憶紫芝香。"]', '诗', 'shi', '', NULL, '送韋商州弼 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9e8d5ae-9d08-4440-a38c-76bfbaf6f6ff', '夏日梁王席送張岐州', '夏日梁王席送張岐州', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["秦雞常下雍，周鳳昔鳴岐。","此地推雄撫，惟良寄在斯。","家傳七豹貴，人擅八龍奇。","高傳生光彩，長林歎別離。","天人開祖席，朝寀候征麾。","翠帟當郊敞，彤幨向野披。","芃芃秋麥盛，苒苒夏條垂。","奏計何時入？臺階望羽儀。"]', '["秦雞常下雍，周鳳昔鳴岐。","此地推雄撫，惟良寄在斯。","家傳七豹貴，人擅八龙奇。","高傳生光彩，长林歎別離。","天人开祖席，朝寀候征麾。","翠帟當郊敞，彤幨向野披。","芃芃秋麦盛，苒苒夏條垂。","奏計何时入？台階望羽儀。"]', '诗', 'shi', '', NULL, '夏日梁王席送張岐州 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7584ad7-2866-40d5-84d9-21d3e025dcb3', '夏日都門送司馬員外逸客孫員外佺北征', '夏日都门送司马員外逸客孫員外佺北征', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["二庭追虜騎，六月動周師。","廟略天人授，軍麾相國持。","復言徵二妙，才命重當時。","畫省連征橐，橫門共別詞。","雲迎出塞馬，風卷度河旗。","計日方夷寇，旋聞杕杜詩。"]', '["二庭追虜騎，六月动周師。","廟略天人授，軍麾相国持。","复言徵二妙，才命重當时。","畫省連征橐，橫门共別词。","云迎出塞马，风卷度河旗。","計日方夷寇，旋闻杕杜诗。"]', '诗', 'shi', '', NULL, '夏日都門送司馬員外逸客孫員外佺北征 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb4e691a-d674-4e78-8c42-2ed9d49274f5', '送盧管記仙客北伐', '送盧管記仙客北伐', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["羽檄西北飛，交城日夜圍。","廟堂盛徵選，戎幕生光輝。","雁行度函谷，馬首向金微。","湛湛山川暮，蕭蕭涼氣稀。","餞途予憫默，赴敵子英威。","今日楊朱淚，無將灑鐵衣。"]', '["羽檄西北飞，交城日夜圍。","廟堂盛徵選，戎幕生光輝。","雁行度函谷，马首向金微。","湛湛山川暮，蕭蕭涼氣稀。","餞途予憫默，赴敵子英威。","今日楊朱泪，無將灑鐵衣。"]', '诗', 'shi', '', NULL, '送盧管記仙客北伐 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3a5ebb9-28b5-4a9f-b31f-c0f94b07498d', '移禁司刑', '移禁司刑', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["疇昔參鄉賦，中年忝吏途。","丹脣曾學史，白首不成儒。","天子開昌籙，羣生偶大爐。","散材仍葺廈，弱羽遽[摶]扶。","寵邁乘軒鶴，榮過食稻鳧。","何功遊畫省，何德理黃樞。","弔影慙非據，傾心事遠圖。","盜泉寧止渴，惡木匪投軀。","任直翻多毀，安身遂少徒。","一朝逢糺謬，三省竟無虞。","白簡初心屈，黃紗始望孤。","患平終不怒，持劾每相驅。","埋劒誰當辨，偷金以自誣。","誘言雖委答，流議亦真符。","首夏方憂圄，高秋獨向隅。","嚴城看熠耀，圜戶對蜘蛛。","累餉唯妻子，披冤是友于。","物情牽倚伏，人事限榮枯。","門客心誰在，隣交迹倘無。","撫襟雙涕落，危坐日憂趨。","聖旨垂明德，冤囚豈濫誅。","會希恩免理，終望罪矜愚。","司寇宜哀獄，台庭幸恤辜。","漢皇虛詔上，容有報恩珠。"]', '["疇昔參乡賦，中年忝吏途。","丹脣曾学史，白首不成儒。","天子开昌籙，羣生偶大爐。","散材仍葺廈，弱羽遽[摶]扶。","寵邁乘軒鹤，榮過食稻鳧。","何功游畫省，何德理黄樞。","弔影慙非據，傾心事远圖。","盜泉寧止渴，惡木匪投軀。","任直翻多毀，安身遂少徒。","一朝逢糺謬，三省竟無虞。","白簡初心屈，黄紗始望孤。","患平終不怒，持劾每相驱。","埋劒誰當辨，偷金以自誣。","誘言雖委答，流議亦真符。","首夏方憂圄，高秋独向隅。","嚴城看熠耀，圜戶对蜘蛛。","累餉唯妻子，披冤是友于。","物情牽倚伏，人事限榮枯。","门客心誰在，隣交迹倘無。","撫襟雙涕落，危坐日憂趨。","聖旨垂明德，冤囚豈濫誅。","會希恩免理，終望罪矜愚。","司寇宜哀獄，台庭幸恤辜。","漢皇虛詔上，容有報恩珠。"]', '诗', 'shi', '', NULL, '移禁司刑 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d46c4f3d-5cf0-429c-af46-b233f3495bd1', '入鬼門關', '入鬼门关', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["昔傳瘴江路，今到鬼門關。","土地無人老，流移幾客還。","自從別京洛，頹鬢與衰顏。","夕宿含沙裏，晨行岡路間。","馬危千仞谷，舟險萬重灣。","問我投何地？西南盡百蠻。"]', '["昔傳瘴江路，今到鬼门关。","土地無人老，流移幾客還。","自從別京洛，頹鬢與衰顏。","夕宿含沙裏，晨行岡路间。","马危千仞谷，舟險万重灣。","问我投何地？西南尽百蠻。"]', '诗', 'shi', '', NULL, '入鬼門關 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d694744e-af07-4de8-98c9-2bd1936db3bb', '三日獨坐驩州思憶舊遊', '三日独坐驩州思憶旧游', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["兩京多節物，三日最遨遊。","麗日風徐卷，香塵雨暫收。","紅桃初下地，綠柳半垂溝。","童子成春服，宮人罷射鞲。","禊堂通漢苑，解席繞秦樓。","束皙言談妙，張華史漢遒。","無亭不駐馬，何浦不橫舟。","舞籥千門度，帷屏百道流。","金丸向鳥落，芳餌接魚投。","濯穢憐清淺，迎祥樂獻酬。","靈芻陳欲棄，神藥曝應休。","誰念招魂節，翻爲禦魅囚。","朋從天外盡，心賞日南求。","銅柱威丹徼，朱崖鎮火陬。","炎蒸連曉夕，瘴癘滿冬秋。","西水何時貸？南方詎可留。","無人對爐酒，寧緩去鄉憂。"]', '["兩京多節物，三日最遨游。","丽日风徐卷，香塵雨暫收。","紅桃初下地，綠柳半垂溝。","童子成春服，宮人罷射鞲。","禊堂通漢苑，解席繞秦楼。","束皙言談妙，張华史漢遒。","無亭不駐马，何浦不橫舟。","舞籥千门度，帷屏百道流。","金丸向鸟落，芳餌接鱼投。","濯穢怜清淺，迎祥乐獻酬。","靈芻陳欲棄，神藥曝應休。","誰念招魂節，翻爲禦魅囚。","朋從天外尽，心賞日南求。","銅柱威丹徼，朱崖鎮火陬。","炎蒸連晓夕，瘴癘满冬秋。","西水何时貸？南方詎可留。","無人对爐酒，寧緩去乡憂。"]', '诗', 'shi', '', NULL, '三日獨坐驩州思憶舊遊 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31be9ea6-b3ed-4e25-a5f0-fbe317c8b4a7', '從驩州廨宅移住山間水亭贈蘇使君', '從驩州廨宅移住山间水亭贈蘇使君', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["遇坎即乘流，西南到火洲。","鬼門應苦夜，瘴浦不宜秋。","歲貸胸穿老，朝飛鼻飲頭。","死生離骨肉，榮辱間朋遊。","棄置一身在，平生萬事休。","鷹鸇遭誤逐，豺虎怯真投。","憶昨京華子，傷今邊地囚。","願陪鸚鵡樂，希並鷓鴣留。","日月渝鄉思，煙花換客愁。","幸逢蘇伯玉，回借水亭幽。","山柏張青蓋，江蕉卷綠油。","乘閑無火宅，因放有漁舟。","適越心當是，居夷迹可求。","古來堯禪舜，何必罪驩兜。"]', '["遇坎即乘流，西南到火洲。","鬼门應苦夜，瘴浦不宜秋。","歲貸胸穿老，朝飞鼻饮头。","死生離骨肉，榮辱间朋游。","棄置一身在，平生万事休。","鷹鸇遭誤逐，豺虎怯真投。","憶昨京华子，傷今邊地囚。","願陪鸚鵡乐，希並鷓鴣留。","日月渝乡思，煙花換客愁。","幸逢蘇伯玉，回借水亭幽。","山柏張青蓋，江蕉卷綠油。","乘闲無火宅，因放有漁舟。","適越心當是，居夷迹可求。","古来堯禪舜，何必罪驩兜。"]', '诗', 'shi', '', NULL, '從驩州廨宅移住山間水亭贈蘇使君 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('595db240-dab3-4527-b116-788c8e141313', '赦到不得歸題江上石', '赦到不得归題江上石', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["家住東京裏，身投南海西。","風烟萬里隔，朝夕幾行啼。","聖主謳歌洽，賢臣法令齊。","忽聞銅柱使，走馬報金雞。","棄市沾皇渥，投荒漏紫泥。","魂疲山鶴路，心醉[跕]鳶溪。","天鑒誅元惡，宸慈恤遠黎。","五方思寄刃，萬姓喜然臍。","自幼輸丹懇，何嘗玷白圭。","承言竄遐魅，雪枉間深狴。","墳壠無由謁，京華豈重躋。","炎方誰謂廣，地盡覺天低。","百卉雜殊怪，昆蟲理賴暌。","閉藏元不蟄，搖落反生荑。","瘧瘴因茲苦，窮愁益復迷。","火雲蒸毒霧，陽雨濯陰霓。","周乘安交趾，王恭輯畫題。","少寬窮涸鮒，猶愍觸藩羝。","配宅隣州廨，斑苗接野畦。","山空聞鬬象，江靜見游犀。","翰墨思諸季，裁縫憶老妻。","小兒應離褓，幼女未攀筓。","夢蝶翻無定，蓍龜詎有倪。","誰能竟此曲，曲盡氣酸嘶。"]', '["家住东京裏，身投南海西。","风烟万里隔，朝夕幾行啼。","聖主謳歌洽，賢臣法令齊。","忽闻銅柱使，走马報金雞。","棄市沾皇渥，投荒漏紫泥。","魂疲山鹤路，心醉[跕]鳶溪。","天鑒誅元惡，宸慈恤远黎。","五方思寄刃，万姓喜然臍。","自幼輸丹懇，何嘗玷白圭。","承言竄遐魅，雪枉间深狴。","墳壠無由謁，京华豈重躋。","炎方誰謂廣，地尽覺天低。","百卉杂殊怪，昆蟲理賴暌。","閉藏元不蟄，搖落反生荑。","瘧瘴因茲苦，窮愁益复迷。","火云蒸毒霧，陽雨濯陰霓。","周乘安交趾，王恭輯畫題。","少寬窮涸鮒，猶愍觸藩羝。","配宅隣州廨，斑苗接野畦。","山空闻鬬象，江静见游犀。","翰墨思諸季，裁縫憶老妻。","小兒應離褓，幼女未攀筓。","梦蝶翻無定，蓍龟詎有倪。","誰能竟此曲，曲尽氣酸嘶。"]', '诗', 'shi', '', NULL, '赦到不得歸題江上石 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc4a4c2d-38b3-457e-bdb8-6f3bcb3b63b5', '答魑魅代書寄家人', '答魑魅代书寄家人', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["魑魅來相問，君何失帝鄉。","龍鍾辭北闕，蹭蹬守南荒。","覽鏡憐雙鬢，沾衣惜萬行。","抱愁那去國，將老更垂裳。","影答余他歲，恩私宦洛陽。","三春給事省，五載尚書郎。","黃閤遊鸞署，青縑御史香。","扈巡行太液，陪宴坐明光。","渭北昇高苑，河南祓禊場。","煙花恆獻賦，泉石每稱觴。","暇日從休澣，高車暎道傍。","迎賓就丞相，選士謁昭王。","侍寵言猶得，承歡謂不忘。","一朝貽厚譴，五宅竟同防。","兇豎曾軀策，權豪豈易當。","款顏因侍從，接武在文章。","且懼威非贙，寧知心是狼。","身猶納履誤，情爲覆盆傷。","可歎緣成業，非關行昧藏。","喜逢今改旦，正朔復歸唐。","河讖隨龍馬，天書逐鳳皇。","朝容欣舊則，宸化美初綱。","告善雕旌建，收冤錦斾張。","宰臣更獻納，郡守各明揚。","禮樂移三統，舟車會八方。","雲沙降白遂，秦隴獻燒當。","三赦重天造，千推極國詳。","大招思復楚，于役限維桑。","漲海緣真臘，崇山壓古棠。","雕題飛棟宇，儋耳間衣裳。","伏枕神餘劣，加餐力未強。","空庭遊翡翠，窮巷倚桄榔。","緣體分殊昔，回眸宛異常。","吉兇恆委鄭，年壽會詢唐。","家本傳清白，官移重挂牀。","上京無薄產，故里絕窮莊。","碧玉先時費，蒼頭此自將。","興言歎家口，何處待贏糧？","計吏從都出，傳聞大小康。","降除沾二弟，離拆已三房。","劒外懸銷骨，荆南預斷腸。","音塵黃耳間，夢想白眉良。","復此單栖鶴，銜雛願遠翔。","何堪萬里外，雲海已溟茫。","戚屬甘胡越，聲名任粃糠。","由來休憤命，命也信蒼蒼。","獨坐尋周易，清晨詠老莊。","此中因悟道，無問入猖狂。"]', '["魑魅来相问，君何失帝乡。","龙鍾辞北闕，蹭蹬守南荒。","覽镜怜雙鬢，沾衣惜万行。","抱愁那去国，將老更垂裳。","影答余他歲，恩私宦洛陽。","三春給事省，五載尚书郎。","黄閤游鸾署，青縑御史香。","扈巡行太液，陪宴坐明光。","渭北昇高苑，河南祓禊場。","煙花恆獻賦，泉石每稱觴。","暇日從休澣，高车暎道傍。","迎賓就丞相，選士謁昭王。","侍寵言猶得，承歡謂不忘。","一朝貽厚譴，五宅竟同防。","兇豎曾軀策，權豪豈易當。","款顏因侍從，接武在文章。","且懼威非贙，寧知心是狼。","身猶納履誤，情爲覆盆傷。","可歎緣成業，非关行昧藏。","喜逢今改旦，正朔复归唐。","河讖隨龙马，天书逐鳳皇。","朝容欣旧則，宸化美初綱。","告善雕旌建，收冤錦斾張。","宰臣更獻納，郡守各明揚。","禮乐移三統，舟车會八方。","云沙降白遂，秦隴獻燒當。","三赦重天造，千推極国詳。","大招思复楚，于役限維桑。","漲海緣真臘，崇山壓古棠。","雕題飞棟宇，儋耳间衣裳。","伏枕神餘劣，加餐力未強。","空庭游翡翠，窮巷倚桄榔。","緣體分殊昔，回眸宛異常。","吉兇恆委鄭，年壽會詢唐。","家本傳清白，官移重挂牀。","上京無薄產，故里絕窮莊。","碧玉先时費，蒼头此自將。","兴言歎家口，何处待贏糧？","計吏從都出，傳闻大小康。","降除沾二弟，離拆已三房。","劒外懸銷骨，荆南預斷腸。","音塵黄耳间，梦想白眉良。","复此單栖鹤，銜雛願远翔。","何堪万里外，云海已溟茫。","戚屬甘胡越，声名任粃糠。","由来休憤命，命也信蒼蒼。","独坐尋周易，清晨詠老莊。","此中因悟道，無问入猖狂。"]', '诗', 'shi', '', NULL, '答魑魅代書寄家人 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3cb5c79-1406-41cb-8744-eb77c22ceb77', '度安海入龍編', '度安海入龙編', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["我來交趾郡，南與貫胸連。","四氣分寒少，三光置日偏。","尉佗曾馭國，翁仲久遊泉。","邑屋遺甿在，魚鹽舊產傳。","越人遙捧翟，漢將下看鳶。","北斗崇山挂，南風漲海牽。","別離頻破月，容鬢驟催年。","昆弟推由命，妻孥割付緣。","夢來魂尚擾，愁委疾空纏。","虛道崩城淚，明心不應天。"]', '["我来交趾郡，南與貫胸連。","四氣分寒少，三光置日偏。","尉佗曾馭国，翁仲久游泉。","邑屋遺甿在，鱼鹽旧產傳。","越人遙捧翟，漢將下看鳶。","北斗崇山挂，南风漲海牽。","別離頻破月，容鬢驟催年。","昆弟推由命，妻孥割付緣。","梦来魂尚擾，愁委疾空纏。","虛道崩城泪，明心不應天。"]', '诗', 'shi', '', NULL, '度安海入龍編 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c577ccc9-300b-4231-a774-ef6d4f615558', '從崇山向越常', '從崇山向越常', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["朝發崇山下，暮坐越常陰。","西從杉谷度，北上竹溪深。","竹溪道明水，杉谷古崇岑。","差池將不合，繚繞復相尋。","桂葉藏金嶼，藤花閉石林。","天窗虛的的，雲竇下沈沈。","造化功偏厚，真仙跡每臨。","豈徒探怪異，聊欲緩歸心。"]', '["朝發崇山下，暮坐越常陰。","西從杉谷度，北上竹溪深。","竹溪道明水，杉谷古崇岑。","差池將不合，繚繞复相尋。","桂葉藏金嶼，藤花閉石林。","天窗虛的的，云竇下沈沈。","造化功偏厚，真仙跡每臨。","豈徒探怪異，聊欲緩归心。"]', '诗', 'shi', '', NULL, '從崇山向越常 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0759e3b4-d0d9-448d-8687-3a549bf89a53', '哭蘇眉州崔司業二公', '哭蘇眉州崔司業二公', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["渙汗天中發，伶俜海外旋。","長沙遇太守，問舊幾人全。","國寶亡雙傑，天才喪兩賢。","大名齊弱歲，高德並中年。","禮樂羊叔子，文章王仲宣。","相看尚玄鬢，相次入黃泉。","流放蠻陬闊，鄉關帝里偏。","親朋雲霧擁，生死歲時傳。","崔昔揮宸翰，蘇嘗濟巨川。","絳衣陪下列，黃閤謬差肩。","及此俱冥昧，云誰敘播遷。","隼輿懷舊轍，鱣館想虛筵。","家愛方休杵，皇慈更撤縣。","銘旌西蜀路，騎吹北邙田。","隴樹應秋矣，江帆故杳然。","罷琴明月夜，留劒白雲天。","涕泗湘潭水，淒涼衡嶠煙。","古來修短分，神理竟難筌。"]', '["渙汗天中發，伶俜海外旋。","长沙遇太守，问旧幾人全。","国寶亡雙傑，天才喪兩賢。","大名齊弱歲，高德並中年。","禮乐羊叔子，文章王仲宣。","相看尚玄鬢，相次入黄泉。","流放蠻陬闊，乡关帝里偏。","親朋云霧擁，生死歲时傳。","崔昔揮宸翰，蘇嘗濟巨川。","絳衣陪下列，黄閤謬差肩。","及此俱冥昧，云誰敘播遷。","隼輿懷旧轍，鱣館想虛筵。","家愛方休杵，皇慈更撤縣。","銘旌西蜀路，騎吹北邙田。","隴樹應秋矣，江帆故杳然。","罷琴明月夜，留劒白云天。","涕泗湘潭水，淒涼衡嶠煙。","古来修短分，神理竟难筌。"]', '诗', 'shi', '', NULL, '哭蘇眉州崔司業二公 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('008c5fd9-9ad5-4a28-93cc-6bfd11f05338', '哭道土劉無得', '哭道土劉無得', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["聞有玄都客，成仙不易祈。","蓬萊向清淺，桃杏欲芳菲。","縮地黃泉出，昇天白日飛。","少微星夜落，高掌露朝晞。","吐甲龍應出，銜符鳥自歸。","國人思負局，天子惜被衣。","花月留丹洞，琴笙閣翠微。","嗟來子桑扈，爾獨返於幾。"]', '["闻有玄都客，成仙不易祈。","蓬萊向清淺，桃杏欲芳菲。","縮地黄泉出，昇天白日飞。","少微星夜落，高掌露朝晞。","吐甲龙應出，銜符鸟自归。","国人思負局，天子惜被衣。","花月留丹洞，琴笙閣翠微。","嗟来子桑扈，爾独返於幾。"]', '诗', 'shi', '', NULL, '哭道土劉無得 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b474cf5-b27b-462b-8785-c5a2d84147e1', '寒食', '寒食', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["普天皆滅焰，匝地盡藏煙。","不知何處火？來就客心然。"]', '["普天皆滅焰，匝地尽藏煙。","不知何处火？来就客心然。"]', '诗', 'shi', '', NULL, '寒食 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd74ae2a-94ae-4f9c-a276-a426fe90d49f', '回波詞', '回波词', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["回波爾時佺期，流向嶺外生歸。","身名已蒙齒錄，袍笏未復牙緋。"]', '["回波爾时佺期，流向嶺外生归。","身名已蒙齒錄，袍笏未复牙緋。"]', '诗', 'shi', '', NULL, '回波詞 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c8aa5a5-27a5-4e32-a650-61ace91fdd6c', '上巳日祓禊渭濱應制', '上巳日祓禊渭濱應制', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["寶馬香車清渭濱，紅桃碧柳禊堂春。","皇情尚憶垂竿佐，天祚先呈捧劒人。"]', '["寶马香车清渭濱，紅桃碧柳禊堂春。","皇情尚憶垂竿佐，天祚先呈捧劒人。"]', '诗', 'shi', '', NULL, '上巳日祓禊渭濱應制 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df1c3ef2-b6f5-443d-95aa-b78f7fa51afc', '奉和幸韋嗣立山莊應制', '奉和幸韋嗣立山莊應制', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["東山朝日翠屏開，北闕晴空綵仗來。","喜遇天文七曜動，少微今夜近三台。"]', '["东山朝日翠屏开，北闕晴空綵仗来。","喜遇天文七曜动，少微今夜近三台。"]', '诗', 'shi', '', NULL, '奉和幸韋嗣立山莊應制 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b6ad252-a63c-40c6-bea4-52b2157a4f87', '夜宴安樂公主宅', '夜宴安乐公主宅', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["濯龍門外主家親，鳴鳳樓中天上人。","自有金杯迎甲夜，還將綺席代陽春。"]', '["濯龙门外主家親，鳴鳳楼中天上人。","自有金杯迎甲夜，還將綺席代陽春。"]', '诗', 'shi', '', NULL, '夜宴安樂公主宅 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcaded9d-ce29-4afe-bca4-f4521f85bd71', '苑中遇雪應制', '苑中遇雪應制', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["北闕彤雲掩曙霞，東風吹雪舞仙家。","瓊章定少千人和，銀樹長芳六出花。"]', '["北闕彤云掩曙霞，东风吹雪舞仙家。","瓊章定少千人和，銀樹长芳六出花。"]', '诗', 'shi', '', NULL, '苑中遇雪應制 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb771da6-427d-437a-856a-4a7826c74b1a', '餞唐永昌', '餞唐永昌', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["洛陽舊有神明宰，輦轂由來天地中。","餘邑政成何足貴，因君取則四方同。"]', '["洛陽旧有神明宰，輦轂由来天地中。","餘邑政成何足貴，因君取則四方同。"]', '诗', 'shi', '', NULL, '餞唐永昌 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4002135f-389e-4273-a3f3-979c10422ffc', '獄中聞駕幸長安二首 一', '獄中闻駕幸长安二首 一', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["傳聞聖旨向秦京，誰念羈囚滯洛城。","扈從由來是方朔，爲申冤氣在長平。"]', '["傳闻聖旨向秦京，誰念羈囚滯洛城。","扈從由来是方朔，爲申冤氣在长平。"]', '诗', 'shi', '', NULL, '獄中聞駕幸長安二首 一 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('315cc2e1-f329-425d-a2b0-e3f4994110c1', '獄中聞駕幸長安二首 二', '獄中闻駕幸长安二首 二', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["無事今朝來下獄，誰期十月是橫河。","君看鷹隼俱堪擊，爲報蜘蛛收網羅。"]', '["無事今朝来下獄，誰期十月是橫河。","君看鷹隼俱堪擊，爲報蜘蛛收網羅。"]', '诗', 'shi', '', NULL, '獄中聞駕幸長安二首 二 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5909e17d-a969-44ef-8e09-383f21387492', '邙山', '邙山', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["北邙山上列墳塋，萬古千秋對洛城。","城中日夕歌鐘起，山上唯聞松栢聲。"]', '["北邙山上列墳塋，万古千秋对洛城。","城中日夕歌鐘起，山上唯闻松栢声。"]', '诗', 'shi', '', NULL, '邙山 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1016bc1-1af5-4bf3-862d-98bf3406c2aa', '句', '句', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["周原五稼起，雲海百川歸。","願此零陵燕，長隨征斾飛。"]', '["周原五稼起，云海百川归。","願此零陵燕，长隨征斾飞。"]', '诗', 'shi', '', NULL, '句 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89491143-3bbb-4ad5-8df9-9515ea941015', '陪張燕公登南樓', '陪張燕公登南楼', 'ec28a42d-edcc-4b69-8958-bd2a2cb37382', '唐', '["抑鬱何以歡，陰氛亦登望。","孤島輕霧裏，行舟白波上。","目勞西北雲，心醉東南嶂。","昔日青谿子，胡然此無狀。"]', '["抑鬱何以歡，陰氛亦登望。","孤島轻霧裏，行舟白波上。","目勞西北云，心醉东南嶂。","昔日青谿子，胡然此無狀。"]', '诗', 'shi', '', NULL, '陪張燕公登南樓 趙冬曦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c4020cb-b7e6-42dc-9f05-e153d36a755d', '酬燕公出湖見寄', '酬燕公出湖见寄', 'ec28a42d-edcc-4b69-8958-bd2a2cb37382', '唐', '["綸綍有成命，旌麾不可攀。","湘川朝目斷，荆闕夕波還。","果枉東瞻唱，興言夕放閑。","攜琴仙洞中，置酒㴩湖上。","芳景恣行樂，謫居忽如忘。","聚散本相因，離情自悲悵。","鸞翮非常戢，鵬天會昭曠。","永懷宛洛游，曾是彈冠望。"]', '["綸綍有成命，旌麾不可攀。","湘川朝目斷，荆闕夕波還。","果枉东瞻唱，兴言夕放闲。","携琴仙洞中，置酒㴩湖上。","芳景恣行乐，謫居忽如忘。","聚散本相因，離情自悲悵。","鸾翮非常戢，鵬天會昭曠。","永懷宛洛游，曾是彈冠望。"]', '诗', 'shi', '', NULL, '酬燕公出湖見寄 趙冬曦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad12bb3c-dbe8-4c41-9ebe-da5b313f889e', '奉和張燕公早霽南樓', '奉和張燕公早霽南楼', 'ec28a42d-edcc-4b69-8958-bd2a2cb37382', '唐', '["方曙躋南樓，凭軒肆遐矚。","物華蕩暄氣，春景媚晴旭。","川霽湘山孤，林芳楚郊縟。","列巖重疊翠，遠岸逶迤綠。","風帆摩天垠，魚艇散彎曲。","鴻歸鶴舞送，猨叫鶯聲續。","羣動皆熙熙，噫予獨羈束。","常欽才子意，忌鵩傷踡跼。","雅尚騷人文，懷沙何迫促。","未知二賢意，去矣從所欲。"]', '["方曙躋南楼，凭軒肆遐矚。","物华蕩暄氣，春景媚晴旭。","川霽湘山孤，林芳楚郊縟。","列巖重叠翠，远岸逶迤綠。","风帆摩天垠，鱼艇散彎曲。","鴻归鹤舞送，猨叫鶯声續。","羣动皆熙熙，噫予独羈束。","常欽才子意，忌鵩傷踡跼。","雅尚騷人文，懷沙何迫促。","未知二賢意，去矣從所欲。"]', '诗', 'shi', '', NULL, '奉和張燕公早霽南樓 趙冬曦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f488ad9-8a17-4df1-b00f-fbfee7acfebd', '㴩湖作', '㴩湖作', 'ec28a42d-edcc-4b69-8958-bd2a2cb37382', '唐', '["三湖返入兩山間，畜作㴩湖彎復彎。","暑雨奔流潭正滿，微霜及潦水初還。","水還波卷谿潭涸，綠草芊芊岸嶄岝。","適來飛櫂共迴旋，已復揚鞭恣行樂。","道旁耆老步躚躚，楚言茲事不知年。","試就湖邊披草徑，莫疑東海變桑田。","君訝今時盡陵陸，我看明歲更淪漣。","來今自昔無終始，人事迴環常若是。","應思闕下聲華日，誰謂江潭旅遊子。","初貞正喜固當然，往蹇來譽宜可俟。","盈虛用舍輪輿旋，勿學靈均遠問天。"]', '["三湖返入兩山间，畜作㴩湖彎复彎。","暑雨奔流潭正满，微霜及潦水初還。","水還波卷谿潭涸，綠草芊芊岸嶄岝。","適来飞櫂共迴旋，已复揚鞭恣行乐。","道旁耆老步躚躚，楚言茲事不知年。","試就湖邊披草徑，莫疑东海变桑田。","君訝今时尽陵陸，我看明歲更淪漣。","来今自昔無終始，人事迴环常若是。","應思闕下声华日，誰謂江潭旅游子。","初貞正喜固當然，往蹇来譽宜可俟。","盈虛用舍輪輿旋，勿学靈均远问天。"]', '诗', 'shi', '', NULL, '㴩湖作 趙冬曦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97cffb75-465a-42fd-a6af-7e36e99fa979', '和燕公岳州山城', '和燕公岳州山城', 'ec28a42d-edcc-4b69-8958-bd2a2cb37382', '唐', '["爲吏恩猶舊，投沙惠此蒙。","江邊悠爾處，泗上宛然同。","訪道精言合，論經大義通。","鳴琴有真氣，況已沐清風。"]', '["爲吏恩猶旧，投沙惠此蒙。","江邊悠爾处，泗上宛然同。","訪道精言合，論經大義通。","鳴琴有真氣，況已沐清风。"]', '诗', 'shi', '', NULL, '和燕公岳州山城 趙冬曦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d29893e-e945-4b03-a082-65fb9149ed69', '和尹懋秋夜遊㴩湖二首 一', '和尹懋秋夜游㴩湖二首 一', 'ec28a42d-edcc-4b69-8958-bd2a2cb37382', '唐', '["政理常多暇，方舟此泝洄。","吹笙虛洞荅，舉楫便風催。","山暗雲猶辨，潭幽月稍來。","清谿無數曲，未盡莫先迴。"]', '["政理常多暇，方舟此泝洄。","吹笙虛洞荅，舉楫便风催。","山暗云猶辨，潭幽月稍来。","清谿無數曲，未尽莫先迴。"]', '诗', 'shi', '', NULL, '和尹懋秋夜遊㴩湖二首 一 趙冬曦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56be5791-18a9-4829-9e5b-ced1593803fa', '和尹懋秋夜遊㴩湖二首 二', '和尹懋秋夜游㴩湖二首 二', 'ec28a42d-edcc-4b69-8958-bd2a2cb37382', '唐', '["煙靄夕微蒙，幽灣賞未窮。","艤舟待初月，褰幌招遠風。","鶴聲聒前浦，漁火明暗叢。","東山雲壑意，不謂爾來同。"]', '["煙靄夕微蒙，幽灣賞未窮。","艤舟待初月，褰幌招远风。","鹤声聒前浦，漁火明暗叢。","东山云壑意，不謂爾来同。"]', '诗', 'shi', '', NULL, '和尹懋秋夜遊㴩湖二首 二 趙冬曦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b279486b-e374-46a1-bbf6-4827c2c172cf', '陪燕公遊㴩湖', '陪燕公游㴩湖', 'ec28a42d-edcc-4b69-8958-bd2a2cb37382', '唐', '["江上多山水，招要步馬來。","琴將天籟合，酒共鳥聲催。","巖坐攀紅藥，谿行愛綠苔。","所懷非此地，遊望亦裴回。"]', '["江上多山水，招要步马来。","琴將天籟合，酒共鸟声催。","巖坐攀紅藥，谿行愛綠苔。","所懷非此地，游望亦裴回。"]', '诗', 'shi', '', NULL, '陪燕公遊㴩湖 趙冬曦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ffc70fa-ee83-4148-800a-2eb6203e14d4', '荅張燕公翻著葛巾見呈之作', '荅張燕公翻著葛巾见呈之作', 'ec28a42d-edcc-4b69-8958-bd2a2cb37382', '唐', '["美酒值芳春，醒餘氣益真。","降歡時倒履，乘興偶翻巾。","徐榻思方建，左車理自均。","傲然歌一曲，一醉濯纓人。"]', '["美酒值芳春，醒餘氣益真。","降歡时倒履，乘兴偶翻巾。","徐榻思方建，左车理自均。","傲然歌一曲，一醉濯纓人。"]', '诗', 'shi', '', NULL, '荅張燕公翻著葛巾見呈之作 趙冬曦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82badfaa-a20f-4946-9171-f89b314d8316', '奉荅燕公', '奉荅燕公', 'ec28a42d-edcc-4b69-8958-bd2a2cb37382', '唐', '["語別意淒淒，零陵湘水西。","佳人金谷返，愛子洞庭迷。","舊館逢花發，他山值鳥啼。","江天千里望，誰見綠蘋齊。"]', '["語別意淒淒，零陵湘水西。","佳人金谷返，愛子洞庭迷。","旧館逢花發，他山值鸟啼。","江天千里望，誰见綠蘋齊。"]', '诗', 'shi', '', NULL, '奉荅燕公 趙冬曦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e096f75-70b8-43b3-86e0-ff23b282d155', '奉和聖製同二相已下羣官樂遊園宴', '奉和聖製同二相已下羣官乐游园宴', 'ec28a42d-edcc-4b69-8958-bd2a2cb37382', '唐', '["爽塏三秦地，芳華二月初。","酺承奠璧罷，宴是合錢餘。","柳翠垂堪結，桃紅卷欲舒。","從容會鵷鷺，延曼戲龍魚。","喜氣流雲物，歡聲浹里閭。","聖恩將報厚，請述記言書。"]', '["爽塏三秦地，芳华二月初。","酺承奠璧罷，宴是合錢餘。","柳翠垂堪結，桃紅卷欲舒。","從容會鵷鷺，延曼戲龙鱼。","喜氣流云物，歡声浹里閭。","聖恩將報厚，請述記言书。"]', '诗', 'shi', '', NULL, '奉和聖製同二相已下羣官樂遊園宴 趙冬曦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd656857-3054-4245-a998-e7daa58fc6e5', '奉和聖製荅張說扈從南出雀鼠谷', '奉和聖製荅張说扈從南出雀鼠谷', 'ec28a42d-edcc-4b69-8958-bd2a2cb37382', '唐', '["軒轅應順動，力牧正趨陪。","道合殷爲礪，時行楚有材。","省方西禮設，振旅北京迴。","地理分中壤，天文照上臺。","寒依汾谷去，春入晉郊來。","竊比康衢者，長歌仰大哉。"]', '["軒轅應順动，力牧正趨陪。","道合殷爲礪，时行楚有材。","省方西禮設，振旅北京迴。","地理分中壤，天文照上台。","寒依汾谷去，春入晉郊来。","竊比康衢者，长歌仰大哉。"]', '诗', 'shi', '', NULL, '奉和聖製荅張說扈從南出雀鼠谷 趙冬曦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16c8d29a-1765-4b57-9d0e-6a1755a741a7', '奉和聖製送張說上集賢學士賜宴賦得蓮字', '奉和聖製送張说上集賢学士賜宴賦得蓮字', 'ec28a42d-edcc-4b69-8958-bd2a2cb37382', '唐', '["淺術方觀海，深恩忽見天。","學開丹殿籍，名與石渠賢。","良輔膺休命，微生謬采甄。","春餘仍哢鳥，夏近未舒蓮。","牋札來宸禁，衣冠集詔筵。","史臣知醉德，欲記升中年。"]', '["淺術方观海，深恩忽见天。","学开丹殿籍，名與石渠賢。","良輔膺休命，微生謬采甄。","春餘仍哢鸟，夏近未舒蓮。","牋札来宸禁，衣冠集詔筵。","史臣知醉德，欲記升中年。"]', '诗', 'shi', '', NULL, '奉和聖製送張說上集賢學士賜宴賦得蓮字 趙冬曦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c365dba-2125-4979-b810-c5fca99a154b', '奉荅燕公', '奉荅燕公', 'ec28a42d-edcc-4b69-8958-bd2a2cb37382', '唐', '["誰道零陵守，東過此地遊。","友僚同省閣，昆弟接荆州。","我逐江潭鴈，君隨海上鷗。","屢傷神氣阻，久別鬢毛秋。","疑嶺春應徧，陽臺雨欲收。","主人情未盡，高駕少淹留。"]', '["誰道零陵守，东過此地游。","友僚同省閣，昆弟接荆州。","我逐江潭鴈，君隨海上鷗。","屢傷神氣阻，久別鬢毛秋。","疑嶺春應徧，陽台雨欲收。","主人情未尽，高駕少淹留。"]', '诗', 'shi', '', NULL, '奉荅燕公 趙冬曦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5462333-23d9-4459-b674-5d11858c800c', '陪張燕公行郡竹籬', '陪張燕公行郡竹籬', 'ec28a42d-edcc-4b69-8958-bd2a2cb37382', '唐', '["良臣乃國寶，麾守去承明。","外戶人無閉，浮江獸已行。","隨來晉盜逸，民化蜀風清。","郛郭從彝典，州閭荷德聲。","小人投天涯，流落巴丘城。","所賴中和作，優游鑿與耕。"]', '["良臣乃国寶，麾守去承明。","外戶人無閉，浮江獸已行。","隨来晉盜逸，民化蜀风清。","郛郭從彝典，州閭荷德声。","小人投天涯，流落巴丘城。","所賴中和作，優游鑿與耕。"]', '诗', 'shi', '', NULL, '陪張燕公行郡竹籬 趙冬曦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7b13d1c-1a3a-4851-8491-0e0f98fac97d', '和燕公別㴩湖', '和燕公別㴩湖', 'ec28a42d-edcc-4b69-8958-bd2a2cb37382', '唐', '["南湖美泉石，君子翫幽奇。","灣澳陪臨泛，巖峿共踐窺。","秋風赬桂竦，春景綠楊垂。","郢路委分竹，湘濱擁去麾。","枉帆懷勝賞，留景惜差池。","水木且不棄，情由良可知。"]', '["南湖美泉石，君子翫幽奇。","灣澳陪臨泛，巖峿共踐窺。","秋风赬桂竦，春景綠楊垂。","郢路委分竹，湘濱擁去麾。","枉帆懷勝賞，留景惜差池。","水木且不棄，情由良可知。"]', '诗', 'shi', '', NULL, '和燕公別㴩湖 趙冬曦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8173fbc6-3427-4723-a388-d974fd193c60', '奉酬燕公見歸田賦垂贈之作', '奉酬燕公见归田賦垂贈之作', 'ec28a42d-edcc-4b69-8958-bd2a2cb37382', '唐', '["窮鳥嬰籠綴，孤飛任播遷。","鷦鷯王佐用，復此挫沖天。","楚雲何掩鬱，湘水亦迴邅。","懷哉愧木鴈，忽爾枉蘭荃。","愈疾同枚叔，銷憂比仲宣。","歸途書可畏，弱操石猶堅。","覆載雖云廣，涔陽直塊然。"]', '["窮鸟嬰籠綴，孤飞任播遷。","鷦鷯王佐用，复此挫沖天。","楚云何掩鬱，湘水亦迴邅。","懷哉愧木鴈，忽爾枉蘭荃。","愈疾同枚叔，銷憂比仲宣。","归途书可畏，弱操石猶堅。","覆載雖云廣，涔陽直塊然。"]', '诗', 'shi', '', NULL, '奉酬燕公見歸田賦垂贈之作 趙冬曦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cfa3832-a852-4780-b995-72e10c724b05', '和張燕公耗磨日飲 一', '和張燕公耗磨日饮 一', 'ec28a42d-edcc-4b69-8958-bd2a2cb37382', '唐', '["上月今朝減，流傳耗磨辰。","還將不事事，同醉俗中人。"]', '["上月今朝減，流傳耗磨辰。","還將不事事，同醉俗中人。"]', '诗', 'shi', '', NULL, '和張燕公耗磨日飲 一 趙冬曦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('816b98a8-2757-4645-b931-e2ee9ceffc9a', '和張燕公耗磨日飲 二', '和張燕公耗磨日饮 二', 'ec28a42d-edcc-4b69-8958-bd2a2cb37382', '唐', '["春來半月度，俗忌一朝閑。","不酌他鄉酒，無堪對楚山。"]', '["春来半月度，俗忌一朝闲。","不酌他乡酒，無堪对楚山。"]', '诗', 'shi', '', NULL, '和張燕公耗磨日飲 二 趙冬曦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b07f0f8-43aa-46a2-9169-ead6a5715141', '奉陪張燕公登南樓', '奉陪張燕公登南楼', '0ff716bd-a4e5-425e-b13a-458a28f41eaa', '唐', '["君子每垂眷，江山共流眄。","水遠林外明，巖近霧中見。","終日西北望，何處是京縣。","屢登高春臺，徒使淚如霰。"]', '["君子每垂眷，江山共流眄。","水远林外明，巖近霧中见。","終日西北望，何处是京縣。","屢登高春台，徒使泪如霰。"]', '诗', 'shi', '', NULL, '奉陪張燕公登南樓 尹懋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c86e65c7-7639-401b-a6e6-d02220a9c88b', '秋夜陪張丞相趙侍御游㴩湖二首 一', '秋夜陪張丞相趙侍御游㴩湖二首 一', '0ff716bd-a4e5-425e-b13a-458a28f41eaa', '唐', '["熊軾巴陵地，鷁舟湘水潯。","江山與勢遠，泉石自幽深。","杳靄入天壑，冥茫見道心。","超然無俗事，清宴有空林。"]', '["熊軾巴陵地，鷁舟湘水潯。","江山與勢远，泉石自幽深。","杳靄入天壑，冥茫见道心。","超然無俗事，清宴有空林。"]', '诗', 'shi', '', NULL, '秋夜陪張丞相趙侍御游㴩湖二首 一 尹懋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8f5e043-c0d9-430b-94fd-9f608d05f423', '秋夜陪張丞相趙侍御游㴩湖二首 二', '秋夜陪張丞相趙侍御游㴩湖二首 二', '0ff716bd-a4e5-425e-b13a-458a28f41eaa', '唐', '["江上饒奇山，巑羅雲水間。","風和樹色雜，苔古石文斑。","巴俗將千溠，㴩湖凡幾灣。","嬉遊竟不盡，乘月汎舟還。"]', '["江上饒奇山，巑羅云水间。","风和樹色杂，苔古石文斑。","巴俗將千溠，㴩湖凡幾灣。","嬉游竟不尽，乘月汎舟還。"]', '诗', 'shi', '', NULL, '秋夜陪張丞相趙侍御游㴩湖二首 二 尹懋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e832479a-ea3f-4242-9b05-e298bbcda7fc', '同燕公汎洞庭', '同燕公汎洞庭', '0ff716bd-a4e5-425e-b13a-458a28f41eaa', '唐', '["風光淅淅草中飄，日彩熒熒水上搖。","幸奏瀟湘雲壑意，山旁容與動仙橈。"]', '["风光淅淅草中飄，日彩熒熒水上搖。","幸奏瀟湘云壑意，山旁容與动仙橈。"]', '诗', 'shi', '', NULL, '同燕公汎洞庭 尹懋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a9c5446-7f0e-4e81-8f25-2e3a5f19b7ab', '奉荅燕公', '奉荅燕公', 'ed7e0024-7c4e-49c6-b0d8-f8000f36ed31', '唐', '["郡遠途且艱，宜悲良自得。","胡爲心獨爾，惠好在南國。","亦既清顏披，冏然良願克。","與君蘭時會，羣物如藻飾。","煙景惜歡賞，雲山起翰墨。","接藝奇思微，偶談玄言直。","永日不知倦，逾旬猶謂亟。","如何酌離尊，移櫂巴城側。","浦口勞長望，舟中獨太息。","疾風吹飛帆，倏忽南與北。","目盡不復見，懷哉無終極。","唯當衡峰上，遙辨湖水色。"]', '["郡远途且艱，宜悲良自得。","胡爲心独爾，惠好在南国。","亦既清顏披，冏然良願克。","與君蘭时會，羣物如藻飾。","煙景惜歡賞，云山起翰墨。","接藝奇思微，偶談玄言直。","永日不知倦，逾旬猶謂亟。","如何酌離尊，移櫂巴城側。","浦口勞长望，舟中独太息。","疾风吹飞帆，倏忽南與北。","目尽不复见，懷哉無終極。","唯當衡峰上，遙辨湖水色。"]', '诗', 'shi', '', NULL, '奉荅燕公 王琚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85f57df7-3297-4a4f-b78e-7e8e20ae0b6e', '美女篇', '美女篇', 'ed7e0024-7c4e-49c6-b0d8-f8000f36ed31', '唐', '["東鄰美女實名倡，絕代容華無比方。","濃纖得中非短長，紅素天生誰飾妝。","桂樓椒閣木蘭堂，繡戶雕軒文杏梁。","屈曲屏風繞象牀，萎蕤翠帳綴香囊。","玉臺龍鏡洞徹光，金爐沈煙酷烈芳。","遙聞行佩音鏘鏘，含嬌欲笑出洞房。","二八三五閨心切，褰簾捲幔迎春節。","清歌始發詞怨咽，鳴琴一弄心斷絕。","借問哀怨何所爲，盛年情多心自悲。","須臾破顏倏斂態，一悲一喜倂相宜。","何能見此不注心，惜無媒氏爲傳音。","可憐盈盈直千金，誰家君子爲藁砧。"]', '["东鄰美女實名倡，絕代容华無比方。","濃纖得中非短长，紅素天生誰飾妝。","桂楼椒閣木蘭堂，繡戶雕軒文杏梁。","屈曲屏风繞象牀，萎蕤翠帳綴香囊。","玉台龙镜洞徹光，金爐沈煙酷烈芳。","遙闻行佩音鏘鏘，含嬌欲笑出洞房。","二八三五閨心切，褰簾捲幔迎春節。","清歌始發词怨咽，鳴琴一弄心斷絕。","借问哀怨何所爲，盛年情多心自悲。","須臾破顏倏斂態，一悲一喜倂相宜。","何能见此不注心，惜無媒氏爲傳音。","可怜盈盈直千金，誰家君子爲藁砧。"]', '诗', 'shi', '', NULL, '美女篇 王琚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f54f7fc8-8f1f-407a-81c7-1a1a3507890d', '自荆湖入朝至岳陽奉別張燕公', '自荆湖入朝至岳陽奉別張燕公', 'ed7e0024-7c4e-49c6-b0d8-f8000f36ed31', '唐', '["五載朝天子，三湘逢舊僚。","扁舟方輟櫂，清論遂終朝。","遠樹煙間沒，長江地際遙。","帝城馳夢想，歸帆滿風飆。"]', '["五載朝天子，三湘逢旧僚。","扁舟方輟櫂，清論遂終朝。","远樹煙间沒，长江地際遙。","帝城驰梦想，归帆满风飆。"]', '诗', 'shi', '', NULL, '自荆湖入朝至岳陽奉別張燕公 王琚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76e019f8-3fb8-4fd4-8e91-43ee9648455d', '游㴩湖上寺', '游㴩湖上寺', 'ed7e0024-7c4e-49c6-b0d8-f8000f36ed31', '唐', '["春山臨遠壑，水木自幽清。","夙昔懷微尚，茲焉一放情。","雲間聽弄鳥，煙上摘初英。","地僻方無悶，逾知道思精。"]', '["春山臨远壑，水木自幽清。","夙昔懷微尚，茲焉一放情。","云间听弄鸟，煙上摘初英。","地僻方無悶，逾知道思精。"]', '诗', 'shi', '', NULL, '游㴩湖上寺 王琚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c741285-0d51-406d-b1ce-af12a1c7deb9', '和張燕公湘中九日登高', '和張燕公湘中九日登高', '5b236eec-1c9b-4f08-bad5-591eff6ca91a', '唐', '["重陽初啟節，無射正飛灰。","寂寞風蟬至，連翩霜鴈來。","山棠紅葉下，岸菊紫花開。","今日桓公座，多愧孟嘉才。"]', '["重陽初啟節，無射正飞灰。","寂寞风蟬至，連翩霜鴈来。","山棠紅葉下，岸菊紫花开。","今日桓公座，多愧孟嘉才。"]', '诗', 'shi', '', NULL, '和張燕公湘中九日登高 陰行先 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e35d7274-f338-4c0c-a42e-b1717d4d3e59', '奉別張岳州說二首 一', '奉別張岳州说二首 一', '8114dfbb-6de5-4f49-bad0-d1fa3c132690', '唐', '["長沙辭舊國，洞庭逢故人。","薰蘭敦久要，披霧轉相親。","歲月空嗟老，江山不惜春。","忽聞黃鶴曲，更作白頭新。"]', '["长沙辞旧国，洞庭逢故人。","薰蘭敦久要，披霧轉相親。","歲月空嗟老，江山不惜春。","忽闻黄鹤曲，更作白头新。"]', '诗', 'shi', '', NULL, '奉別張岳州說二首 一 王熊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b479f86-38e9-470b-aa81-2cae585e99aa', '奉別張岳州說二首 二', '奉別張岳州说二首 二', '8114dfbb-6de5-4f49-bad0-d1fa3c132690', '唐', '["平生共風月，倏忽間山川。","不期交淡水，暫得欵忘年。","興逸方罷釣，帆開欲解船。","離心若危斾，朝夕爲君懸。"]', '["平生共风月，倏忽间山川。","不期交淡水，暫得欵忘年。","兴逸方罷釣，帆开欲解船。","離心若危斾，朝夕爲君懸。"]', '诗', 'shi', '', NULL, '奉別張岳州說二首 二 王熊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00e003b2-2fa3-4a7c-acbe-08b6a0b64da7', '入朝別張燕公', '入朝別張燕公', '1585b31f-cfbb-40de-b83b-0ae4d433b444', '唐', '["華容佳山水，之子厭承明。","符竹紆小郡，江湖被德聲。","三年計吏入，路指巴丘城。","鳧舟纔結纜，騶駕已相迎。","別離他鄉酒，委曲故人情。","孤嶼早煙薄，長波晚氣清。","辛勤方遠騖，勝賞屢難幷。","迴瞻洞庭浦，日暮愁雲生。"]', '["华容佳山水，之子厭承明。","符竹紆小郡，江湖被德声。","三年計吏入，路指巴丘城。","鳧舟纔結纜，騶駕已相迎。","別離他乡酒，委曲故人情。","孤嶼早煙薄，长波晚氣清。","辛勤方远騖，勝賞屢难幷。","迴瞻洞庭浦，日暮愁云生。"]', '诗', 'shi', '', NULL, '入朝別張燕公 梁知微 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b11c0a85-b5f4-4f3f-b2b1-37f1246c6347', '桐竹贈張燕公', '桐竹贈張燕公', 'e2632b4b-2239-429d-bf1a-cffb06d3abd2', '唐', '["北竹青桐北，南桐綠竹南。","竹林君早愛，桐樹我初貪。","鳳栖桐不媿，鳳食竹何慙。","棲食更如此，餘非鳳所堪。"]', '["北竹青桐北，南桐綠竹南。","竹林君早愛，桐樹我初貪。","鳳栖桐不媿，鳳食竹何慙。","棲食更如此，餘非鳳所堪。"]', '诗', 'shi', '', NULL, '桐竹贈張燕公 李伯魚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('603c3920-60eb-470b-820b-b6488c18441e', '正朝上左相張燕公', '正朝上左相張燕公', 'b0d288d5-c747-44ef-8f8a-33d54aab99cb', '唐', '["歲去愁終在，春還命不來。","長吁問丞相，東閣幾時開。"]', '["歲去愁終在，春還命不来。","长吁问丞相，东閣幾时开。"]', '诗', 'shi', '', NULL, '正朝上左相張燕公 楊重玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4ae0646-a2ad-4d64-8a65-714e916c4774', '道峽似巫山', '道峽似巫山', 'c8446182-1dea-418b-95bc-e45943638a21', '唐', '["江如曉天靜，石似暮雲張。","征帆一流覽，宛若巫山陽。","楚客思歸路，秦人謫異鄉。","猨鳴孤月夜，再使淚霑裳。"]', '["江如晓天静，石似暮云張。","征帆一流覽，宛若巫山陽。","楚客思归路，秦人謫異乡。","猨鳴孤月夜，再使泪霑裳。"]', '诗', 'shi', '', NULL, '道峽似巫山 朱使欣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de131cd3-20c4-496b-9b97-d52fc86fe6e2', '巫山高', '巫山高', 'c67d16ad-c102-4959-9edd-e677bb9716af', '唐', '["巫山高不極，合沓狀奇新。","暗谷疑風雨，陰崖若鬼神。","月明三峽曉，潮滿九江春。","爲問陽臺客，應知入夢人。"]', '["巫山高不極，合沓狀奇新。","暗谷疑风雨，陰崖若鬼神。","月明三峽晓，潮满九江春。","爲问陽台客，應知入梦人。"]', '诗', 'shi', '', NULL, '巫山高 張循之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('867e0cbb-0c17-4792-aea5-3f40e7b1c2b9', '送泉州李使君之任', '送泉州李使君之任', 'c67d16ad-c102-4959-9edd-e677bb9716af', '唐', '["傍海皆荒服，分符重漢臣。","雲山百越路，市井十洲人。","執玉來朝遠，還珠入貢頻。","連年不見雪，到處即行春。"]', '["傍海皆荒服，分符重漢臣。","云山百越路，市井十洲人。","執玉来朝远，還珠入貢頻。","連年不见雪，到处即行春。"]', '诗', 'shi', '', NULL, '送泉州李使君之任 張循之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33a94fdf-32d2-4fad-b42d-6a7d209381ba', '長門怨', '长门怨', 'c67d16ad-c102-4959-9edd-e677bb9716af', '唐', '["長門落景盡，洞房秋月明。","玉階草露積，金屋網塵生。","妾妬今應改，君恩惜未平。","寄語臨邛客，何時作賦成。"]', '["长门落景尽，洞房秋月明。","玉階草露積，金屋網塵生。","妾妬今應改，君恩惜未平。","寄語臨邛客，何时作賦成。"]', '诗', 'shi', '', NULL, '長門怨 張循之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('488868f6-d037-45bb-86e1-8f89d2688159', '巫山', '巫山', 'c67d16ad-c102-4959-9edd-e677bb9716af', '唐', '["流景一何速，年華不可追。","解佩安所贈，怨咽空自悲。"]', '["流景一何速，年华不可追。","解佩安所贈，怨咽空自悲。"]', '诗', 'shi', '', NULL, '巫山 張循之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64d3d86d-8f57-4485-81a1-3c856ba259e6', '送王汶宰江陰', '送王汶宰江陰', 'c67d16ad-c102-4959-9edd-e677bb9716af', '唐', '["郡北乘流去，花間竟日行。","海魚朝滿市，江鳥夜喧城。","讓酒非關病，援琴不在聲。","應緣五斗米，數日滯淵明。"]', '["郡北乘流去，花间竟日行。","海鱼朝满市，江鸟夜喧城。","讓酒非关病，援琴不在声。","應緣五斗米，數日滯淵明。"]', '诗', 'shi', '', NULL, '送王汶宰江陰 張循之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('652c8519-b075-4ddd-b6ed-af260588d7ec', '婺州留別鄧使君', '婺州留別鄧使君', 'c67d16ad-c102-4959-9edd-e677bb9716af', '唐', '["西掖馳名久，東陽出守時。","江山婺女分，風月隱侯詩。","別恨雙溪急，留歡五馬遲。","迴舟暎沙嶼，未遠剩相思。"]', '["西掖驰名久，东陽出守时。","江山婺女分，风月隐侯诗。","別恨雙溪急，留歡五马遲。","迴舟暎沙嶼，未远剩相思。"]', '诗', 'shi', '', NULL, '婺州留別鄧使君 張循之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('406881a1-3678-4187-a07d-ef4cba5a2b27', '祭汾陰樂章 太和', '祭汾陰乐章 太和', '1bde6696-25d3-479f-ba91-c623f7b16eeb', '唐', '["於穆聖皇，六葉重光。","太原刻頌，后土疏場。","寶鼎呈符，歊雲孕祥。","禮樂備矣，降福穰穰。"]', '["於穆聖皇，六葉重光。","太原刻頌，后土疏場。","寶鼎呈符，歊云孕祥。","禮乐備矣，降福穰穰。"]', '诗', 'shi', '', NULL, '祭汾陰樂章 太和 王晙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88f7cb25-d675-46cc-88f6-6a9e612ddd2b', '大堤曲', '大堤曲', 'db8c386d-e29f-47b9-a015-0fae6b9e00ee', '唐', '["南國多佳人，莫若大堤女。","玉牀翠羽帳，寶袜蓮花距。","魂處自目成，色授開心許。","迢迢不可見，日暮空愁予。"]', '["南国多佳人，莫若大堤女。","玉牀翠羽帳，寶袜蓮花距。","魂处自目成，色授开心許。","迢迢不可见，日暮空愁予。"]', '诗', 'shi', '', NULL, '大堤曲 張柬之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c7d1c00-c6ee-4b78-bbbb-8d58d55dd27c', '東飛伯勞歌', '东飞伯勞歌', 'db8c386d-e29f-47b9-a015-0fae6b9e00ee', '唐', '["青田白鶴丹山鳳，婺女姮娥兩相送。","誰家絕世綺帳前，豔粉紅脂映寶鈿。","窈窕玉堂褰翠幙，參差繡戶懸珠箔。","絕世三五愛紅妝，冶袖長裙蘭麝香。","春去花枝俄易改，可歎年光不相待。"]', '["青田白鹤丹山鳳，婺女姮娥兩相送。","誰家絕世綺帳前，豔粉紅脂映寶鈿。","窈窕玉堂褰翠幙，參差繡戶懸珠箔。","絕世三五愛紅妝，冶袖长裙蘭麝香。","春去花枝俄易改，可歎年光不相待。"]', '诗', 'shi', '', NULL, '東飛伯勞歌 張柬之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80ad2bc3-dd03-48a3-aa9e-3001c0448b40', '出塞', '出塞', 'db8c386d-e29f-47b9-a015-0fae6b9e00ee', '唐', '["俠客重恩光，驄馬飾金裝。","瞥聞傳羽檄，馳突救邊荒。","歙野山川動，囂天旌斾揚。","吳鉤明似月，楚劒利如霜。","電斷衝胡塞，風飛出洛陽。","轉戰磨笄俗，橫行戴斗鄉。","手擒郅支長，面縛谷蠡王。","將軍占太白，小婦怨流黃。","騕褭青絲騎，娉婷紅粉妝。","三春鶯度曲，八月鴈成行。","誰堪坐愁思，羅袖拂空牀。"]', '["俠客重恩光，驄马飾金裝。","瞥闻傳羽檄，驰突救邊荒。","歙野山川动，囂天旌斾揚。","吳鉤明似月，楚劒利如霜。","電斷衝胡塞，风飞出洛陽。","轉戰磨笄俗，橫行戴斗乡。","手擒郅支长，面縛谷蠡王。","將軍占太白，小婦怨流黄。","騕褭青絲騎，娉婷紅粉妝。","三春鶯度曲，八月鴈成行。","誰堪坐愁思，羅袖拂空牀。"]', '诗', 'shi', '', NULL, '出塞 張柬之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31d6ef79-4aec-4e95-aa6e-6ab79a1b45a0', '與國賢良夜歌二首 一', '與国賢良夜歌二首 一', 'db8c386d-e29f-47b9-a015-0fae6b9e00ee', '唐', '["柳臺臨新堰，樓堞相重複。","窈窕鳳皇姝，傾城復傾國。"]', '["柳台臨新堰，楼堞相重複。","窈窕鳳皇姝，傾城复傾国。"]', '诗', 'shi', '', NULL, '與國賢良夜歌二首 一 張柬之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('425fe4c2-d80b-461b-b7ad-4cb8b865400e', '與國賢良夜歌二首 二', '與国賢良夜歌二首 二', 'db8c386d-e29f-47b9-a015-0fae6b9e00ee', '唐', '["杏間花照灼，樓上月裴回。","帶嬌移玉柱，含笑捧金杯。"]', '["杏间花照灼，楼上月裴回。","带嬌移玉柱，含笑捧金杯。"]', '诗', 'shi', '', NULL, '與國賢良夜歌二首 二 張柬之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e31997de-b936-45db-9463-20c0e1a44693', '詠屏風', '詠屏风', 'c052be7c-60d7-4630-8773-a5bdcd187aaf', '唐', '["綺閣雲霞滿，芳林草樹新。","鳥驚疑欲曙，花笑不關春。","山對彈琴客，谿留垂釣人。","請看車馬客，行處有風塵。"]', '["綺閣云霞满，芳林草樹新。","鸟驚疑欲曙，花笑不关春。","山对彈琴客，谿留垂釣人。","請看车马客，行处有风塵。"]', '诗', 'shi', '', NULL, '詠屏風 袁恕己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25de451b-7c61-45d1-8291-061bdfc5e166', '書懷', '书懷', 'ce631db5-673f-43d8-be88-fd746f94fb79', '唐', '["心爲明時盡，君門尚不容。","田園迷徑路，歸去欲何從。"]', '["心爲明时尽，君门尚不容。","田园迷徑路，归去欲何從。"]', '诗', 'shi', '', NULL, '書懷 劉幽求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd116050-1750-4b13-915c-fe37fbe09212', '流所贈張錫', '流所贈張錫', '0505167b-22af-442f-8db9-2ba8135c9c0e', '唐', '["黃葉因風下，甘從洛浦隈。","白雲何所爲，還出帝鄉來。"]', '["黄葉因风下，甘從洛浦隈。","白云何所爲，還出帝乡来。"]', '诗', 'shi', '', NULL, '流所贈張錫 章玄同 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a61f104d-9874-46e5-b674-0262289ea62f', '臨高臺', '臨高台', 'ea2ff3de-d79b-439e-b5d3-2f13a59cb7c0', '唐', '["漢主事[祁]連，良人在高闕。","空臺寂已暮，愁坐變容髪。","汎豔春幌風，裴回秋戶月。","可憐軍書斷，空使流芳歇。"]', '["漢主事[祁]連，良人在高闕。","空台寂已暮，愁坐变容髪。","汎豔春幌风，裴回秋戶月。","可怜軍书斷，空使流芳歇。"]', '诗', 'shi', '', NULL, '臨高臺 王易從 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9079b311-c980-4a27-9232-317b8ac1804d', '初出京邑有懷舊林', '初出京邑有懷旧林', '17c8dded-5633-4a85-b5f4-febde1d1e349', '唐', '["賦生期獨得，素業守微班。","外忝文學知，鴻漸鵷鷺間。","內傾水木趣，築室依近山。","晨趨天日[晏]，夕臥江海閑。","松風生坐隅，仙禽舞亭灣。","曙雲林下客，霽月池上顏。","雖曰坐郊園，靜默非人寰。","時步蒼龍闕，寧異白雲關。","語濟豈時顧，默善忘世攀。","世網余何觸，天涯謫南蠻。","回首思洛陽，喟然悲貞艱。"]', '["賦生期独得，素業守微班。","外忝文学知，鴻漸鵷鷺间。","內傾水木趣，築室依近山。","晨趨天日[晏]，夕臥江海闲。","松风生坐隅，仙禽舞亭灣。","曙云林下客，霽月池上顏。","雖曰坐郊园，静默非人寰。","时步蒼龙闕，寧異白云关。","語濟豈时顧，默善忘世攀。","世網余何觸，天涯謫南蠻。","回首思洛陽，喟然悲貞艱。"]', '诗', 'shi', '', NULL, '初出京邑有懷舊林 盧僎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be632a1d-3ed9-4a6d-84b8-5f8013d380eb', '稍秋曉坐閣遇舟東下揚州既事寄上族父江陽令', '稍秋晓坐閣遇舟东下揚州既事寄上族父江陽令', '17c8dded-5633-4a85-b5f4-febde1d1e349', '唐', '["虎嘯山城晚，猨鳴江樹秋。","紅林架落照，青峽送歸流。","歸流赴淮海，征帆下揚州。","族父江陽令，盛業繼前修。","文掩崔亭伯，德齊陳太丘。","時哉惜未與，千載且爲儔。","憶昔山陽會，長懷東上游。","稱觴阮林下，賦雪謝庭幽。","道濃禮自略，氣舒文轉遒。","高情薄雲漢，酣態坐芳洲。","接席復連軫，出入陪華輈。","獨善與兼濟，語默奉良籌。","歲月歡無已，風雨暗颼颼。","掌憲時持節，爲邦邈海頭。","子人惠雖樹，蒼生望且留。","微躬趨直道，神甸忝清猷。","仙臺適西步，蠻徼忽南浮。","宇內皆安樂，天涯獨遠投。","忠信徒堅仗，神明豈默詶。","觀生海漫漫，稽命天悠悠。","雲昏巴子峽，月遠吳王樓。","懷昔明不寐，悲令歲屬周。","喟無排雲翮，暫得抒離憂。","空灑霑紅淚，萬里逐行舟。"]', '["虎嘯山城晚，猨鳴江樹秋。","紅林架落照，青峽送归流。","归流赴淮海，征帆下揚州。","族父江陽令，盛業繼前修。","文掩崔亭伯，德齊陳太丘。","时哉惜未與，千載且爲儔。","憶昔山陽會，长懷东上游。","稱觴阮林下，賦雪謝庭幽。","道濃禮自略，氣舒文轉遒。","高情薄云漢，酣態坐芳洲。","接席复連軫，出入陪华輈。","独善與兼濟，語默奉良籌。","歲月歡無已，风雨暗颼颼。","掌憲时持節，爲邦邈海头。","子人惠雖樹，蒼生望且留。","微躬趨直道，神甸忝清猷。","仙台適西步，蠻徼忽南浮。","宇內皆安乐，天涯独远投。","忠信徒堅仗，神明豈默詶。","观生海漫漫，稽命天悠悠。","云昏巴子峽，月远吳王楼。","懷昔明不寐，悲令歲屬周。","喟無排云翮，暫得抒離憂。","空灑霑紅泪，万里逐行舟。"]', '诗', 'shi', '', NULL, '稍秋曉坐閣遇舟東下揚州既事寄上族父江陽令 盧僎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('434b1042-0a24-444d-9727-35c3143c8420', '讓帝挽歌詞二首 一', '讓帝挽歌词二首 一', '17c8dded-5633-4a85-b5f4-febde1d1e349', '唐', '["泰伯玄風遠，延州德讓行。","闔棺追大節，樹羽冊鴻名。","地戶迎天仗，皇階失帝兄。","還聞漢明主，遺劒泣東平。"]', '["泰伯玄风远，延州德讓行。","闔棺追大節，樹羽冊鴻名。","地戶迎天仗，皇階失帝兄。","還闻漢明主，遺劒泣东平。"]', '诗', 'shi', '', NULL, '讓帝挽歌詞二首 一 盧僎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66f7f683-f9ff-4a8e-827b-06dd38e6d140', '讓帝挽歌詞二首 二', '讓帝挽歌词二首 二', '17c8dded-5633-4a85-b5f4-febde1d1e349', '唐', '["朝天馳馬絕，冊帝□宮祖。","恍惚陵廟新，蕭條池館古。","萬化一朝空，哀樂此路同。","西園有明月，修竹韻悲風。"]', '["朝天驰马絕，冊帝□宮祖。","恍惚陵廟新，蕭條池館古。","万化一朝空，哀乐此路同。","西园有明月，修竹韻悲风。"]', '诗', 'shi', '', NULL, '讓帝挽歌詞二首 二 盧僎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('194c5bec-15ff-471f-be56-43031e7b0581', '十月梅花書贈', '十月梅花书贈', '17c8dded-5633-4a85-b5f4-febde1d1e349', '唐', '["君不見巴鄉氣候與華別，年年十月梅花發。","上苑今應雪作花，寧知此地花爲雪。","自從遷播落黔巴，三見江上開新花。","故園風花虛洛汭，窮峽凝雪度歲華。","花情縱似河陽好，客心倍傷邊候早。","春候颯驚樓上梅，霜威未落江潭草。","江水侵天去不還，樓花覆簾空坐攀。","一向花前看白髮，幾回夢裏憶紅顏。","紅顏白髮雲泥改，何異桑田移碧海。","却想華年故國時，唯餘一片空心在。","空心弔影向誰陳，雲臺仙閣舊遊人。","儻知巴樹連冬發，應憐南國氣長春。"]', '["君不见巴乡氣候與华別，年年十月梅花發。","上苑今應雪作花，寧知此地花爲雪。","自從遷播落黔巴，三见江上开新花。","故园风花虛洛汭，窮峽凝雪度歲华。","花情縱似河陽好，客心倍傷邊候早。","春候颯驚楼上梅，霜威未落江潭草。","江水侵天去不還，楼花覆簾空坐攀。","一向花前看白髮，幾回梦裏憶紅顏。","紅顏白髮云泥改，何異桑田移碧海。","却想华年故国时，唯餘一片空心在。","空心弔影向誰陳，云台仙閣旧游人。","儻知巴樹連冬發，應怜南国氣长春。"]', '诗', 'shi', '', NULL, '十月梅花書贈 盧僎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52d5b97f-ac02-4d54-a6fa-8c1816acce1b', '歲晚還京臺望城闕成口號先贈交親', '歲晚還京台望城闕成口號先贈交親', '17c8dded-5633-4a85-b5f4-febde1d1e349', '唐', '["紫陌開行樹，朱城出晚霞。","猶憐慣去國，疑是夢還家。","風弱知催柳，林青覺待花。","交親望歸騎，幾處擁年華。"]', '["紫陌开行樹，朱城出晚霞。","猶怜慣去国，疑是梦還家。","风弱知催柳，林青覺待花。","交親望归騎，幾处擁年华。"]', '诗', 'shi', '', NULL, '歲晚還京臺望城闕成口號先贈交親 盧僎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01dcc878-872c-40de-917f-7ccfcb542411', '送蘇八給事出牧徐州用芳韻', '送蘇八給事出牧徐州用芳韻', '17c8dded-5633-4a85-b5f4-febde1d1e349', '唐', '["金鼎屬元方，璅闈連季常。","畏盈聊出守，分命乃維良。","曉騎辭朝遠，春帆向楚常。","賢哉謙自牧，天下詠餘芳。"]', '["金鼎屬元方，璅闈連季常。","畏盈聊出守，分命乃維良。","晓騎辞朝远，春帆向楚常。","賢哉謙自牧，天下詠餘芳。"]', '诗', 'shi', '', NULL, '送蘇八給事出牧徐州用芳韻 盧僎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b4d12bd-9762-4d5e-a1ba-c625cc4099ea', '上幸皇太子新院應制', '上幸皇太子新院應制', '17c8dded-5633-4a85-b5f4-febde1d1e349', '唐', '["佳氣曉蔥蔥，乾行入震宮。","前星移北極，少海被南風。","視膳銅樓下，吹笙玉座中。","訓深家以正，義舉俗爲公。","父子成釗合，君臣禹啓同。","仰天歌聖道，猶愧乏雕蟲。"]', '["佳氣晓蔥蔥，乾行入震宮。","前星移北極，少海被南风。","視膳銅楼下，吹笙玉座中。","訓深家以正，義舉俗爲公。","父子成釗合，君臣禹啓同。","仰天歌聖道，猶愧乏雕蟲。"]', '诗', 'shi', '', NULL, '上幸皇太子新院應制 盧僎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e54f3d9-f8ba-4ff9-a728-37ffe28d3a23', '奉和李令扈從溫泉宮賜遊驪山韋侍郎別業', '奉和李令扈從溫泉宮賜游驪山韋侍郎別業', '17c8dded-5633-4a85-b5f4-febde1d1e349', '唐', '["風后軒皇佐，雲峰謝客居。","承恩來翠嶺，締賞出丹除。","飛蓋松谿寂，清笳玉洞虛。","窺巖詳霧豹，過水略泉魚。","鄉入無何有，時還上古初。","伊臯羞過狹，魏丙服麤疎。","白雪緣情降，青霞落卷舒。","多慚郎署在，輙繼國風餘。"]', '["风后軒皇佐，云峰謝客居。","承恩来翠嶺，締賞出丹除。","飞蓋松谿寂，清笳玉洞虛。","窺巖詳霧豹，過水略泉鱼。","乡入無何有，时還上古初。","伊臯羞過狹，魏丙服麤疎。","白雪緣情降，青霞落卷舒。","多慚郎署在，輙繼国风餘。"]', '诗', 'shi', '', NULL, '奉和李令扈從溫泉宮賜遊驪山韋侍郎別業 盧僎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f345258-084a-43db-99a7-d8dd716b8c7f', '季冬送戶部郎中使黔府選補', '季冬送戶部郎中使黔府選補', '17c8dded-5633-4a85-b5f4-febde1d1e349', '唐', '["握鏡均荒服，分衡得大同。","徵賢一臺上，補吏五谿中。","雨露將天澤，文章播國風。","漢庭睽直諒，楚峽望清通。","馬逐霜鴻漸，帆沿曉月空。","還期鳳池拜，照耀列星宮。"]', '["握镜均荒服，分衡得大同。","徵賢一台上，補吏五谿中。","雨露將天澤，文章播国风。","漢庭睽直諒，楚峽望清通。","马逐霜鴻漸，帆沿晓月空。","還期鳳池拜，照耀列星宮。"]', '诗', 'shi', '', NULL, '季冬送戶部郎中使黔府選補 盧僎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05c58936-42d2-4418-87b3-0e60e3c0b046', '途中口號', '途中口號', '17c8dded-5633-4a85-b5f4-febde1d1e349', '唐', '["抱玉三朝楚，懷書十上秦。","年年洛陽陌，花鳥弄歸人。"]', '["抱玉三朝楚，懷书十上秦。","年年洛陽陌，花鸟弄归人。"]', '诗', 'shi', '', NULL, '途中口號 盧僎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cdad806-1bfb-41de-8adf-a7f5cef159b2', '南望樓', '南望楼', '17c8dded-5633-4a85-b5f4-febde1d1e349', '唐', '["去國三巴遠，登樓萬里春。","傷心江上客，不是故鄉人。"]', '["去国三巴远，登楼万里春。","傷心江上客，不是故乡人。"]', '诗', 'shi', '', NULL, '南望樓 盧僎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7333ddd5-be42-4c44-a660-130a17737f1d', '臨川送別', '臨川送別', '17c8dded-5633-4a85-b5f4-febde1d1e349', '唐', '["秋郊日半隱，野樹煙初映。","風水正蕭條，那堪動離詠。"]', '["秋郊日半隐，野樹煙初映。","风水正蕭條，那堪动離詠。"]', '诗', 'shi', '', NULL, '臨川送別 盧僎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9163650d-ca79-45ae-8349-e804904de22c', '題殿前桂葉', '題殿前桂葉', '17c8dded-5633-4a85-b5f4-febde1d1e349', '唐', '["桂樹生南海，芳香隔楚山。","今朝天上見，疑是月中攀。"]', '["桂樹生南海，芳香隔楚山。","今朝天上见，疑是月中攀。"]', '诗', 'shi', '', NULL, '題殿前桂葉 盧僎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e104cb68-869c-4afb-8af9-69902118d43e', '奉和受圖溫洛應制', '奉和受圖溫洛應制', '81358cfc-4bf6-4b27-971d-ab6a208a44a4', '唐', '["八神扶玉輦，六羽警瑤谿。","戒道伊川北，通津澗水西。","御圖開洛匱，刻石與天齊。","瑞日波中上，仙禽霧裏低。","微臣矯羽翮，抃舞接鸞鷖。"]', '["八神扶玉輦，六羽警瑤谿。","戒道伊川北，通津澗水西。","御圖开洛匱，刻石與天齊。","瑞日波中上，仙禽霧裏低。","微臣矯羽翮，抃舞接鸾鷖。"]', '诗', 'shi', '', NULL, '奉和受圖溫洛應制 牛鳳及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d9bd302-a282-4cad-8692-2340de67b223', '雅琴篇', '雅琴篇', '914d5038-a9c6-40b9-b9e3-86e0dcf70cfc', '唐', '["亭亭嶧陽樹，落落千萬尋。","獨抱出雲節，孤生不作林。","影搖綠波水，彩絢丹霞岑。","直幹思有託，雅志期所任。","匠者果留盼，雕斵爲雅琴。","文以楚山玉，錯以昆吾金。","虬鳳吐奇狀，商徵含清音。","清音雅調感君子，一撫一弄懷知己。","不知鍾期百年餘，還憶朝朝幾千里。","馬卿臺上應蕪沒，阮籍帷前空已矣。","山情水意君不知，拂匣調弦爲誰理。","調弦拂匣倍含情，況復空山秋月明。","隴水悲風已嗚咽，離鵾別鶴更淒清。","將軍塞外多奇操，中散林間有正聲。","正聲諧風雅，欲竟此曲誰知者。","自言幽隱乏先容，不道人物知音寡。","誰能一奏和天地，誰能再撫歡朝野。","朝野歡娛樂未央，車馬駢闐盛彩章。","歲歲汾川事簫鼓，朝朝伊水聽笙簧。","窈窕樓臺臨上路，妖嬈歌舞出平陽。","彈弦本自稱仁祖，吹管由來許季長。","猶憐雅歌淡無味，淥水白雲誰相貴。","還將逸詞賞幽心，不覺繁聲論遠意。","傳聞帝樂奏鈞天，儻冀微躬備五弦。","願持東武宮商韻，長奉南熏億萬年。"]', '["亭亭嶧陽樹，落落千万尋。","独抱出云節，孤生不作林。","影搖綠波水，彩絢丹霞岑。","直幹思有託，雅志期所任。","匠者果留盼，雕斵爲雅琴。","文以楚山玉，錯以昆吾金。","虬鳳吐奇狀，商徵含清音。","清音雅調感君子，一撫一弄懷知己。","不知鍾期百年餘，還憶朝朝幾千里。","马卿台上應蕪沒，阮籍帷前空已矣。","山情水意君不知，拂匣調弦爲誰理。","調弦拂匣倍含情，況复空山秋月明。","隴水悲风已嗚咽，離鵾別鹤更淒清。","將軍塞外多奇操，中散林间有正声。","正声諧风雅，欲竟此曲誰知者。","自言幽隐乏先容，不道人物知音寡。","誰能一奏和天地，誰能再撫歡朝野。","朝野歡娛乐未央，车马駢闐盛彩章。","歲歲汾川事簫鼓，朝朝伊水听笙簧。","窈窕楼台臨上路，妖嬈歌舞出平陽。","彈弦本自稱仁祖，吹管由来許季长。","猶怜雅歌淡無味，淥水白云誰相貴。","還將逸词賞幽心，不覺繁声論远意。","傳闻帝乐奏鈞天，儻冀微躬備五弦。","願持东武宮商韻，长奉南熏億万年。"]', '诗', 'shi', '', NULL, '雅琴篇 司馬逸客 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f772e03-beb9-4e4d-b216-e5df1531e5a5', '三婦豔', '三婦豔', 'fc3beb44-8502-46aa-834b-8f72fab492ef', '唐', '["大婦能調瑟，中婦詠新詩。","小婦獨無事，花庭曳履綦。","上客且安坐，春日正遲遲。"]', '["大婦能調瑟，中婦詠新诗。","小婦独無事，花庭曳履綦。","上客且安坐，春日正遲遲。"]', '诗', 'shi', '', NULL, '三婦豔 王紹宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76089241-9c53-4d9d-9fdb-1bc79448b878', '別離怨', '別離怨', 'f517f7f8-40d6-4c7c-b660-bc47373689d4', '唐', '["蕩子戍遼東，連年信不通。","塵生錦步障，花送玉屏風。","只怨紅顏改，寧辭玉簟空。","繫書春雁足，早晚到雲中。"]', '["蕩子戍遼东，連年信不通。","塵生錦步障，花送玉屏风。","只怨紅顏改，寧辞玉簟空。","繫书春雁足，早晚到云中。"]', '诗', 'shi', '', NULL, '別離怨 鄭遂初 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('658a96c6-4c44-42ec-85c9-607f1b77cda4', '寒食', '寒食', 'a8726603-8da3-46f7-a9cd-8d1af60f8213', '唐', '["普天皆滅焰，匝地盡藏煙。","不知何處火？來就客心然。"]', '["普天皆滅焰，匝地尽藏煙。","不知何处火？来就客心然。"]', '诗', 'shi', '', NULL, '寒食 李崇嗣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8badfc5b-9cd3-42c7-a477-debbac0fa971', '覽鏡', '覽镜', 'a8726603-8da3-46f7-a9cd-8d1af60f8213', '唐', '["歲去紅顏盡，愁來白髮新。","今朝開鏡匣，疑是別逢人。"]', '["歲去紅顏尽，愁来白髮新。","今朝开镜匣，疑是別逢人。"]', '诗', 'shi', '', NULL, '覽鏡 李崇嗣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83c99263-5213-4d60-95fa-785e517702d6', '獨愁', '独愁', 'a8726603-8da3-46f7-a9cd-8d1af60f8213', '唐', '["聞道成都酒，無錢亦可求。","不知將幾斗，銷得此來愁。"]', '["闻道成都酒，無錢亦可求。","不知將幾斗，銷得此来愁。"]', '诗', 'shi', '', NULL, '獨愁 李崇嗣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa7be51f-e588-45a0-87db-e727a54b9d88', '昭君怨三首 一', '昭君怨三首 一', '11c95f86-6a85-4e81-9f65-3460b19b8e7f', '唐', '["漢道方全盛，朝廷足武臣。","何須薄命妾，辛苦事和親。"]', '["漢道方全盛，朝廷足武臣。","何須薄命妾，辛苦事和親。"]', '诗', 'shi', '', NULL, '昭君怨三首 一 東方虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28166616-6856-4889-a620-287ad0ea0981', '昭君怨三首 二', '昭君怨三首 二', '11c95f86-6a85-4e81-9f65-3460b19b8e7f', '唐', '["揜淚辭丹鳳，銜悲向白龍。","單于浪驚喜，無復舊時容。"]', '["揜泪辞丹鳳，銜悲向白龙。","單于浪驚喜，無复旧时容。"]', '诗', 'shi', '', NULL, '昭君怨三首 二 東方虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60ff5387-cca8-4c07-982a-73d9b39bbe55', '昭君怨三首 三', '昭君怨三首 三', '11c95f86-6a85-4e81-9f65-3460b19b8e7f', '唐', '["胡地無花草，春來不似春。","自然衣帶緩，非是爲腰身。"]', '["胡地無花草，春来不似春。","自然衣带緩，非是爲腰身。"]', '诗', 'shi', '', NULL, '昭君怨三首 三 東方虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7ec8c5e-78b9-4400-9627-095cf1c47af8', '春雪', '春雪', '11c95f86-6a85-4e81-9f65-3460b19b8e7f', '唐', '["春雪滿空來，觸處似花開。","不知園裏樹，若箇是真梅。"]', '["春雪满空来，觸处似花开。","不知园裏樹，若箇是真梅。"]', '诗', 'shi', '', NULL, '春雪 東方虬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab3e9d77-64ad-41b0-866f-3b51e0f9387b', '逸人歌贈李山人', '逸人歌贈李山人', '034d361a-a424-4379-8a0f-08e5d1a9b764', '唐', '["上有堯兮下有田，眠松陽兮漱潁流。","其貌古，其心幽，浩歌一曲兮林壑秋。","道險可驚兮人莫用，樂天知命兮守巖洞。","時擊磬兮嗟鳴鳳，吾欲知往古之不可追，自悠悠於凡夢。"]', '["上有堯兮下有田，眠松陽兮漱潁流。","其貌古，其心幽，浩歌一曲兮林壑秋。","道險可驚兮人莫用，乐天知命兮守巖洞。","时擊磬兮嗟鳴鳳，吾欲知往古之不可追，自悠悠於凡梦。"]', '诗', 'shi', '', NULL, '逸人歌贈李山人 張楚金 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc166e53-49a5-42cb-b37e-66716bc68b86', '謫南海過始興廣勝寺果上人房', '謫南海過始兴廣勝寺果上人房', 'def1dfd2-672b-4274-9b0f-d3e4f2a2031d', '唐', '["零落嗟殘命，蕭條託勝因。","方燒三界火，遽洗六情塵。","隔嶺天花發，凌空月殿新。","誰令鄉國夢，終此學分身。"]', '["零落嗟殘命，蕭條託勝因。","方燒三界火，遽洗六情塵。","隔嶺天花發，凌空月殿新。","誰令乡国梦，終此学分身。"]', '诗', 'shi', '', NULL, '謫南海過始興廣勝寺果上人房 房融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b716e76f-6401-4990-b62b-637e59c7fb47', '詠院中藂竹', '詠院中藂竹', 'ed961108-aa21-4121-90e6-0a4a3c98d3ef', '唐', '["擢擢當軒竹，青青重歲寒。","心貞徒見賞，籜小未成竿。"]', '["擢擢當軒竹，青青重歲寒。","心貞徒见賞，籜小未成竿。"]', '诗', 'shi', '', NULL, '詠院中藂竹 呂太一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03bbaefb-d7af-4660-a669-842569a46c2d', '和呂御史詠院中藂竹', '和呂御史詠院中藂竹', 'a278f803-7e2e-4648-b861-05c5d6253828', '唐', '["聞君庭竹詠，幽意歲寒多。","歎息爲冠小，良工將奈何。"]', '["闻君庭竹詠，幽意歲寒多。","歎息爲冠小，良工將奈何。"]', '诗', 'shi', '', NULL, '和呂御史詠院中藂竹 張紘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('921ae33a-5f08-4a8a-bcce-dc4bd7642ae9', '閨怨', '閨怨', 'a278f803-7e2e-4648-b861-05c5d6253828', '唐', '["去年離別雁初歸，今夜裁縫螢已飛。","征客近來音信斷，不知何處寄寒衣。"]', '["去年離別雁初归，今夜裁縫螢已飞。","征客近来音信斷，不知何处寄寒衣。"]', '诗', 'shi', '', NULL, '閨怨 張紘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('235b688d-c7f7-4040-b2a3-91ed11f81bf5', '行路難', '行路难', 'a278f803-7e2e-4648-b861-05c5d6253828', '唐', '["君不見溫家玉鏡臺，提攜抱屋九重來。","君不見相如綠綺琴，一撫一拍鳳凰音。","人生意氣須及早，莫負當年行樂心。","荆王奏曲楚妃歎，曲盡歡終夜將半。","朱樓銀閣正平生，碧草青苔坐蕪漫。","當春對酒不須疑，視日相看能幾時。","春風吹盡燕初至，此時自爲稱君意。","秋露萎草鴻始歸，此時衰暮與君違。","人生翻覆何常定，誰保容顏無是非。"]', '["君不见溫家玉镜台，提携抱屋九重来。","君不见相如綠綺琴，一撫一拍鳳凰音。","人生意氣須及早，莫負當年行乐心。","荆王奏曲楚妃歎，曲尽歡終夜將半。","朱楼銀閣正平生，碧草青苔坐蕪漫。","當春对酒不須疑，視日相看能幾时。","春风吹尽燕初至，此时自爲稱君意。","秋露萎草鴻始归，此时衰暮與君違。","人生翻覆何常定，誰保容顏無是非。"]', '诗', 'shi', '', NULL, '行路難 張紘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6c6047c-179f-4125-8e64-f0d5beb9da3e', '別親朋', '別親朋', '3f718e18-a3c1-4c8d-9d2b-6c4738f31f72', '唐', '["畏途方萬里，生涯近百年。","不知将白首，何處入黄泉。"]', '["畏途方万里，生涯近百年。","不知将白首，何处入黄泉。"]', '诗', 'shi', '', NULL, '別親朋 鄭蜀賓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aef5c658-74d7-447e-b6ee-2035b707df5c', '海上作', '海上作', '78c443b1-2182-4cef-953b-a7f93a37e2dd', '唐', '["曠哉潮汐池，大矣乾坤力。","浩浩去無際，沄沄深不測。","崩騰翕衆流，泱漭環中國。","鱗介錯殊品，氛霞饒詭色。","天波混莫分，島樹遙難識。","漢主探靈怪，秦王恣遊陟。","搜奇大壑東，竦望成山北。","方術徒相誤，蓬萊安可得。","吾君略仙道，至化孚淳默。","驚浪晏窮溟，飛航通絕域。","馬韓底厥貢，龍伯修其職。","粵我遘休明，匪躬期正直。","敢輸鷹隼執，以間豺狼忒。","海路行已殫，輶軒未皇息。","勞歌玄月暮，旅睇滄浪極。","魏闕渺雲端，馳心附歸冀。"]', '["曠哉潮汐池，大矣乾坤力。","浩浩去無際，沄沄深不測。","崩腾翕衆流，泱漭环中国。","鱗介錯殊品，氛霞饒詭色。","天波混莫分，島樹遙难識。","漢主探靈怪，秦王恣游陟。","搜奇大壑东，竦望成山北。","方術徒相誤，蓬萊安可得。","吾君略仙道，至化孚淳默。","驚浪晏窮溟，飞航通絕域。","马韓底厥貢，龙伯修其職。","粵我遘休明，匪躬期正直。","敢輸鷹隼執，以间豺狼忒。","海路行已殫，輶軒未皇息。","勞歌玄月暮，旅睇滄浪極。","魏闕渺云端，驰心附归冀。"]', '诗', 'shi', '', NULL, '海上作 宋務光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b35fe792-9512-408f-a45b-3fb4bcd4f89c', '回波辭', '回波辞', '11b77852-49dc-4a2b-9c82-39cc01c2b85b', '唐', '["回波爾時酒巵，微臣職在箴規。","侍讌既過三爵，喧譁竊恐非儀。"]', '["回波爾时酒巵，微臣職在箴規。","侍讌既過三爵，喧譁竊恐非儀。"]', '诗', 'shi', '', NULL, '回波辭 李景伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3fcece0-91c8-4695-8811-df33ba834138', '秋晚度廢關', '秋晚度廢关', '92c32022-4645-4e50-9f25-33821cf4d610', '唐', '["秦郊平舊險，周德眷遺黎。","始聞清夜柝，俄見落封泥。","物色來無限，津途去不迷。","空亭誰問馬，閑戍但鳴雞。","山月寒彌淨，河風曉更淒。","贈言楊伯起，非復是關西。"]', '["秦郊平旧險，周德眷遺黎。","始闻清夜柝，俄见落封泥。","物色来無限，津途去不迷。","空亭誰问马，闲戍但鳴雞。","山月寒彌淨，河风晓更淒。","贈言楊伯起，非复是关西。"]', '诗', 'shi', '', NULL, '秋晚度廢關 李行言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8802fc47-29ba-4564-a112-a602b5b0ebf0', '上元', '上元', '5658aba3-ff62-462e-b28d-047de240b108', '唐', '["九陌連燈影，千門度月華。","傾城出寶騎，匝路轉香車。","爛熳惟愁曉，周游不問家。","更逢清管發，處處落梅花。"]', '["九陌連灯影，千门度月华。","傾城出寶騎，匝路轉香车。","爛熳惟愁晓，周游不问家。","更逢清管發，处处落梅花。"]', '诗', 'shi', '', NULL, '上元 郭利貞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbe5da24-0d69-450e-bd8a-6ed1210ebc23', '贈皇甫侍御赴都八首 一', '贈皇甫侍御赴都八首 一', '1497e36b-6fa0-4c96-a6af-49d09942f33e', '唐', '["東南之美，生于會稽。","牛斗之氣，蓄于昆溪。","有瑤者玉，連城是齊。","有威者鳳，非梧不棲。"]', '["东南之美，生于會稽。","牛斗之氣，蓄于昆溪。","有瑤者玉，連城是齊。","有威者鳳，非梧不棲。"]', '诗', 'shi', '', NULL, '贈皇甫侍御赴都八首 一 元希聲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56a904d9-d977-44b0-be67-1cce4b11e5bc', '贈皇甫侍御赴都八首 二', '贈皇甫侍御赴都八首 二', '1497e36b-6fa0-4c96-a6af-49d09942f33e', '唐', '["猗嗟衆珍，以況君子。","公侯之胄，必復其始。","利器長材，溫儀峻峙。"]', '["猗嗟衆珍，以況君子。","公侯之胄，必复其始。","利器长材，溫儀峻峙。"]', '诗', 'shi', '', NULL, '贈皇甫侍御赴都八首 二 元希聲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec6f0769-4430-4b8f-9e2e-e767753c0163', '贈皇甫侍御赴都八首 三', '贈皇甫侍御赴都八首 三', '1497e36b-6fa0-4c96-a6af-49d09942f33e', '唐', '["道心惟微，厥用允塞。","德輝不泯，而映邦國。","靜以有神，動而作則。","九臯千里，其聲不忒。"]', '["道心惟微，厥用允塞。","德輝不泯，而映邦国。","静以有神，动而作則。","九臯千里，其声不忒。"]', '诗', 'shi', '', NULL, '贈皇甫侍御赴都八首 三 元希聲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66a25bbb-9840-44c4-b467-9f6fecee4714', '贈皇甫侍御赴都八首 四', '贈皇甫侍御赴都八首 四', '1497e36b-6fa0-4c96-a6af-49d09942f33e', '唐', '["粵在古昔，分官厥初。","刺邪矯枉，非賢勿居。","稜稜直指，烈烈方書。","蒼玉鳴珮，繡衣登車。"]', '["粵在古昔，分官厥初。","刺邪矯枉，非賢勿居。","稜稜直指，烈烈方书。","蒼玉鳴珮，繡衣登车。"]', '诗', 'shi', '', NULL, '贈皇甫侍御赴都八首 四 元希聲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cec5ccb-da28-4892-9a12-1006e3296439', '贈皇甫侍御赴都八首 五', '贈皇甫侍御赴都八首 五', '1497e36b-6fa0-4c96-a6af-49d09942f33e', '唐', '["綽綽夫君，是膺柱下。","準繩有望，名器無假。","寵蓋伯山，氣雄公雅。","立朝正色，俟我能者。"]', '["綽綽夫君，是膺柱下。","準繩有望，名器無假。","寵蓋伯山，氣雄公雅。","立朝正色，俟我能者。"]', '诗', 'shi', '', NULL, '贈皇甫侍御赴都八首 五 元希聲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30769653-572f-4c56-8a3c-b01750734092', '贈皇甫侍御赴都八首 六', '贈皇甫侍御赴都八首 六', '1497e36b-6fa0-4c96-a6af-49d09942f33e', '唐', '["載懷朋情，嘗接閑宴。","好洽昆弟，官聯州縣。","如彼松竹，春榮冬蒨。","柯葉藹然，不渝霜霰。"]', '["載懷朋情，嘗接闲宴。","好洽昆弟，官聯州縣。","如彼松竹，春榮冬蒨。","柯葉藹然，不渝霜霰。"]', '诗', 'shi', '', NULL, '贈皇甫侍御赴都八首 六 元希聲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed24afb2-20d1-4065-b30d-adf31e1adacc', '贈皇甫侍御赴都八首 七', '贈皇甫侍御赴都八首 七', '1497e36b-6fa0-4c96-a6af-49d09942f33e', '唐', '["會合非我，關山坐違。","離鴻曉引，別葉秋飛。","騑驂徐動，尊餞相依。","遠情超忽，岐路光輝。"]', '["會合非我，关山坐違。","離鴻晓引，別葉秋飞。","騑驂徐动，尊餞相依。","远情超忽，岐路光輝。"]', '诗', 'shi', '', NULL, '贈皇甫侍御赴都八首 七 元希聲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8164f00-219f-4711-be9a-2b2706ca7fc9', '贈皇甫侍御赴都八首 八', '贈皇甫侍御赴都八首 八', '1497e36b-6fa0-4c96-a6af-49d09942f33e', '唐', '["金石其心，芝蘭其室。","言語方間，音徽自溢。","肅子風威，嚴子霜質。","贈言歲暮，以保貞吉。"]', '["金石其心，芝蘭其室。","言語方间，音徽自溢。","肅子风威，嚴子霜質。","贈言歲暮，以保貞吉。"]', '诗', 'shi', '', NULL, '贈皇甫侍御赴都八首 八 元希聲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fcae953-211b-470a-968a-4db6e90be6e1', '秋庭夜月有懷', '秋庭夜月有懷', '5ea37191-4445-46f4-b416-b9404cb05492', '唐', '["遊客三江外，單棲百慮違。","山川憶處近，形影夢中歸。","夜月明虛帳，秋風入擣衣。","從來不慣別，況屬鴈南飛。"]', '["游客三江外，單棲百慮違。","山川憶处近，形影梦中归。","夜月明虛帳，秋风入擣衣。","從来不慣別，況屬鴈南飞。"]', '诗', 'shi', '', NULL, '秋庭夜月有懷 李澄之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('295d27fa-3837-4853-b70b-2bfc338af73d', '明月', '明月', 'e1f9b670-6df8-4d8e-ab86-739f79c007cc', '唐', '["三五月華流炯光，可憐懷歸郢路長。","逾江越漢津無梁，遙遙永夜思茫茫。","昭君失寵辭上宮，蛾眉嬋娟臥氈穹。","胡人琵琶彈北風，漢家音信絕南鴻。","昭君此時怨畫工，可憐明月光[朣]朧。","節既秋兮天向寒，沅有漪兮湘有瀾。","沅湘糺合淼漫漫，洛陽才子憶長安。","可憐明月復團團，逐臣戀主心愈恪。","棄妻思君情不薄，已悲芳歲徒淪落。","復恐紅顏坐銷鑠，可憐明月方照灼，向影傾身比葵藿。"]', '["三五月华流炯光，可怜懷归郢路长。","逾江越漢津無梁，遙遙永夜思茫茫。","昭君失寵辞上宮，蛾眉嬋娟臥氈穹。","胡人琵琶彈北风，漢家音信絕南鴻。","昭君此时怨畫工，可怜明月光[朣]朧。","節既秋兮天向寒，沅有漪兮湘有瀾。","沅湘糺合淼漫漫，洛陽才子憶长安。","可怜明月复團團，逐臣戀主心愈恪。","棄妻思君情不薄，已悲芳歲徒淪落。","复恐紅顏坐銷鑠，可怜明月方照灼，向影傾身比葵藿。"]', '诗', 'shi', '', NULL, '明月 李如璧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cc8df3c-e9b4-4a52-80fe-e1b3014da1d8', '嚴陵祠', '嚴陵祠', 'a39f9f47-7a68-47ae-8869-e17163973e24', '唐', '["漢主召子陵，歸宿洛陽殿。","客星今安在，隱迹猶可見。","水石空潺湲，松篁尚蔥蒨。","岸深翠陰合，川迴白雲徧。","幽徑滋蕪沒，荒祠冪霜霰。","垂釣想遺芳，掇蘋羞野薦。","高風激終古，語理忘榮賤。","方騐道可尊，山林情不變。"]', '["漢主召子陵，归宿洛陽殿。","客星今安在，隐迹猶可见。","水石空潺湲，松篁尚蔥蒨。","岸深翠陰合，川迴白云徧。","幽徑滋蕪沒，荒祠冪霜霰。","垂釣想遺芳，掇蘋羞野薦。","高风激終古，語理忘榮賤。","方騐道可尊，山林情不变。"]', '诗', 'shi', '', NULL, '嚴陵祠 洪子輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18678980-d18d-4d54-b981-0193b9476cbd', '度塗山', '度塗山', '8a6a4ab3-9289-42a2-94a5-e18aedd9dee3', '唐', '["小年弄文墨，不識戎旅難。","一朝事鞞鼓，策馬度塗山。","塗山橫地軸，萬里留荒服。","悠悠征斾遠，騑驂一何速。","流月揮金戈，驚風折寒木。","行聞漢飛將，還向臯蘭宿。"]', '["小年弄文墨，不識戎旅难。","一朝事鞞鼓，策马度塗山。","塗山橫地軸，万里留荒服。","悠悠征斾远，騑驂一何速。","流月揮金戈，驚风折寒木。","行闻漢飞將，還向臯蘭宿。"]', '诗', 'shi', '', NULL, '度塗山 寇泚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77065e9d-4ee9-4937-bbad-fe9b901f3c6f', '永泰公主挽歌二首 一', '永泰公主挽歌二首 一', '926a2fe7-1e85-40e1-b32b-f3057f172fce', '唐', '["穠華從婦道，釐降適諸侯。","河漢天孫合，瀟湘帝子遊。","關雎方作訓，鳴鳳自相求。","可歎凌波迹，東川遂不流。"]', '["穠华從婦道，釐降適諸侯。","河漢天孫合，瀟湘帝子游。","关雎方作訓，鳴鳳自相求。","可歎凌波迹，东川遂不流。"]', '诗', 'shi', '', NULL, '永泰公主挽歌二首 一 吳兢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1987a544-cf9e-4090-82b1-0fc90d0e791b', '永泰公主挽歌二首 二', '永泰公主挽歌二首 二', '926a2fe7-1e85-40e1-b32b-f3057f172fce', '唐', '["舜華徂北渚，宸思結南陽。","盩綬哀榮備，游軒寵悼彰。","三川謀遠日，八水宅連岡。","無復秦樓上，吹簫下鳳皇。"]', '["舜华徂北渚，宸思結南陽。","盩綬哀榮備，游軒寵悼彰。","三川謀远日，八水宅連岡。","無复秦楼上，吹簫下鳳皇。"]', '诗', 'shi', '', NULL, '永泰公主挽歌二首 二 吳兢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4bdbf29-64c8-4432-9a3f-d569fb9da794', '妾薄命', '妾薄命', '2d883805-5c5b-4bdf-9122-62fa17ee1f6e', '唐', '["有女妖且麗，裴回湘水湄。","水湄蘭杜芳，採之將寄誰。","瓠犀發皓齒，雙蛾顰翠眉。","紅臉如開蓮，素膚若凝脂。","綽約多逸態，輕盈不自持。","嘗矜絕代色，復恃傾城姿。","子夫前入侍，飛燕復當時。","正悅掌中舞，寧哀團扇詩。","洛川昔云遇，高唐今尚違。","幽閤禽雀噪，閑階草露滋。","流景一何速，年華不可追。","解佩安所贈，怨咽空自悲。"]', '["有女妖且丽，裴回湘水湄。","水湄蘭杜芳，採之將寄誰。","瓠犀發皓齒，雙蛾顰翠眉。","紅臉如开蓮，素膚若凝脂。","綽約多逸態，轻盈不自持。","嘗矜絕代色，复恃傾城姿。","子夫前入侍，飞燕复當时。","正悅掌中舞，寧哀團扇诗。","洛川昔云遇，高唐今尚違。","幽閤禽雀噪，闲階草露滋。","流景一何速，年华不可追。","解佩安所贈，怨咽空自悲。"]', '诗', 'shi', '', NULL, '妾薄命 武平一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbfc238a-d827-4f59-894e-cbd28da2fa65', '奉和登驪山高頂寓目應制', '奉和登驪山高頂寓目應制', '2d883805-5c5b-4bdf-9122-62fa17ee1f6e', '唐', '["鑾輿上碧天，翠帟拖晴煙。","絕崿紆仙徑，層巖敞御筵。","雲披丹鳳闕，日下黑龍川。","更覩南熏奏，流聲入管弦。"]', '["鑾輿上碧天，翠帟拖晴煙。","絕崿紆仙徑，層巖敞御筵。","云披丹鳳闕，日下黑龙川。","更覩南熏奏，流声入管弦。"]', '诗', 'shi', '', NULL, '奉和登驪山高頂寓目應制 武平一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58ab4b4a-7267-4525-8e47-15ba3f8aec41', '幸梨園觀打毬應制', '幸梨园观打毬應制', '2d883805-5c5b-4bdf-9122-62fa17ee1f6e', '唐', '["令節重遨遊，分鑣應綵毬。","驂驔廻上苑，蹀躞繞通溝。","影就紅塵沒，光隨赭汗流。","賞闌清景暮，歌舞樂時休。"]', '["令節重遨游，分鑣應綵毬。","驂驔廻上苑，蹀躞繞通溝。","影就紅塵沒，光隨赭汗流。","賞闌清景暮，歌舞乐时休。"]', '诗', 'shi', '', NULL, '幸梨園觀打毬應制 武平一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6d93978-0137-4de2-ba3d-ed5fbbc61917', '奉和幸白鹿觀應制', '奉和幸白鹿观應制', '2d883805-5c5b-4bdf-9122-62fa17ee1f6e', '唐', '["玉府凌三曜，金壇駐六龍。","綵旒懸倒景，羽蓋偃喬松。","玄圃靈芝秀，華池瑞液濃。","謬因沾舜渥，長願奉堯封。"]', '["玉府凌三曜，金壇駐六龙。","綵旒懸倒景，羽蓋偃喬松。","玄圃靈芝秀，华池瑞液濃。","謬因沾舜渥，长願奉堯封。"]', '诗', 'shi', '', NULL, '奉和幸白鹿觀應制 武平一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09588e17-ec73-4899-b0d7-0761871392d1', '侍宴安樂公主新宅應制', '侍宴安乐公主新宅應制', '2d883805-5c5b-4bdf-9122-62fa17ee1f6e', '唐', '["紫漢秦樓敞，黃山魯館開。","簪裾分上席，歌舞列平臺。","馬既如龍至，人疑學鳳來。","幸茲聯棣萼，何以接鄒枚。"]', '["紫漢秦楼敞，黄山魯館开。","簪裾分上席，歌舞列平台。","马既如龙至，人疑学鳳来。","幸茲聯棣萼，何以接鄒枚。"]', '诗', 'shi', '', NULL, '侍宴安樂公主新宅應制 武平一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfd5a06e-6d3b-4a84-8eae-34a157dc7db8', '送金城公主適西蕃', '送金城公主適西蕃', '2d883805-5c5b-4bdf-9122-62fa17ee1f6e', '唐', '["廣化三邊靜，通煙四海安。","還將膝下愛，特副域中歡。","聖念飛玄藻，仙儀下白蘭。","日斜征蓋沒，歸騎動鳴鸞。"]', '["廣化三邊静，通煙四海安。","還將膝下愛，特副域中歡。","聖念飞玄藻，仙儀下白蘭。","日斜征蓋沒，归騎动鳴鸾。"]', '诗', 'shi', '', NULL, '送金城公主適西蕃 武平一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9252a97b-dd59-42be-93a8-afc66b7edce1', '奉和幸新豐溫泉宮應制', '奉和幸新豐溫泉宮應制', '2d883805-5c5b-4bdf-9122-62fa17ee1f6e', '唐', '["秦王登碣石，周后襲崑崙。","何必在遐遠，方稱萬宇尊。","我皇順時豫，星駕動軒轅。","雄戟交馳道，清笳度國門。","回輿長樂觀，校獵上林園。","行漏移三象，連營總八屯。","旌搖鸚鵡谷，騎轉鳳皇原。","絕壁蒼苔古，靈泉碧溜溫。","參差開水殿，䆗窱敞巖軒。","豐邑模猶在，驪宮迹尚存。","煙松銜翠幄，雪徑遶花源。","侍從推玄草，文章召虎賁。","深仁浹夷夏，洪造溢乾坤。","謬忝王枚列，多慙雨露恩。"]', '["秦王登碣石，周后襲崑崙。","何必在遐远，方稱万宇尊。","我皇順时豫，星駕动軒轅。","雄戟交驰道，清笳度国门。","回輿长乐观，校獵上林园。","行漏移三象，連營總八屯。","旌搖鸚鵡谷，騎轉鳳皇原。","絕壁蒼苔古，靈泉碧溜溫。","參差开水殿，䆗窱敞巖軒。","豐邑模猶在，驪宮迹尚存。","煙松銜翠幄，雪徑遶花源。","侍從推玄草，文章召虎賁。","深仁浹夷夏，洪造溢乾坤。","謬忝王枚列，多慙雨露恩。"]', '诗', 'shi', '', NULL, '奉和幸新豐溫泉宮應制 武平一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('366d110f-3fb7-463c-b21c-860b7b609941', '奉和幸韋嗣立山莊侍宴應制', '奉和幸韋嗣立山莊侍宴應制', '2d883805-5c5b-4bdf-9122-62fa17ee1f6e', '唐', '["三光回斗極，萬騎肅鉤陳。","地若遊汾水，畋疑歷渭濱。","圓塘冰寫鏡，遙樹露成春。","弦奏魚聽曲，機忘鳥狎人。","築巖思感夢，磻石想垂綸。","落景搖紅壁，層陰結翠筠。","素風紛可尚，玄澤藹無垠。","薄暮清笳動，天文煥紫宸。"]', '["三光回斗極，万騎肅鉤陳。","地若游汾水，畋疑歷渭濱。","圓塘冰寫镜，遙樹露成春。","弦奏鱼听曲，機忘鸟狎人。","築巖思感梦，磻石想垂綸。","落景搖紅壁，層陰結翠筠。","素风紛可尚，玄澤藹無垠。","薄暮清笳动，天文煥紫宸。"]', '诗', 'shi', '', NULL, '奉和幸韋嗣立山莊侍宴應制 武平一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10f398e2-d046-469f-af44-51b6c15e569f', '興慶池侍宴應制', '兴慶池侍宴應制', '2d883805-5c5b-4bdf-9122-62fa17ee1f6e', '唐', '["鑾輿羽駕直城隈，帳殿旌門此地開。","皎潔靈潭圖日月，參差畫舸結樓臺。","波搖岸影隨橈轉，風送荷香逐酒來。","願奉聖情歡不極，長遊雲漢幾昭回。"]', '["鑾輿羽駕直城隈，帳殿旌门此地开。","皎潔靈潭圖日月，參差畫舸結楼台。","波搖岸影隨橈轉，风送荷香逐酒来。","願奉聖情歡不極，长游云漢幾昭回。"]', '诗', 'shi', '', NULL, '興慶池侍宴應制 武平一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca642191-74a5-4a73-b1f8-288ea1592018', '奉和立春內出綵花樹應制', '奉和立春內出綵花樹應制', '2d883805-5c5b-4bdf-9122-62fa17ee1f6e', '唐', '["鑾輅青旂下帝臺，東郊上苑望春來。","黃鶯未解林間囀，紅蘂先從殿裏開。","畫閣條風初變柳，銀塘曲水半含苔。","欣逢睿藻光韶律，更促霞觴畏景催。"]', '["鑾輅青旂下帝台，东郊上苑望春来。","黄鶯未解林间囀，紅蘂先從殿裏开。","畫閣條风初变柳，銀塘曲水半含苔。","欣逢睿藻光韶律，更促霞觴畏景催。"]', '诗', 'shi', '', NULL, '奉和立春內出綵花樹應制 武平一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0348db03-dcf5-4e23-ac3c-cbfa186ebae3', '奉和正旦賜宰臣栢葉應制', '奉和正旦賜宰臣栢葉應制', '2d883805-5c5b-4bdf-9122-62fa17ee1f6e', '唐', '["綠葉迎春綠，寒枝歷歲寒。","願持柏葉壽，長奉萬年歡。"]', '["綠葉迎春綠，寒枝歷歲寒。","願持柏葉壽，长奉万年歡。"]', '诗', 'shi', '', NULL, '奉和正旦賜宰臣栢葉應制 武平一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('793b94f3-f7f9-477f-b588-ab464328959c', '遊涇川琴溪', '游涇川琴溪', '2d883805-5c5b-4bdf-9122-62fa17ee1f6e', '唐', '["環潭澄曉色，疊嶂照秋影。","幽致欣所逢，紛慮自茲屏。"]', '["环潭澄晓色，叠嶂照秋影。","幽致欣所逢，紛慮自茲屏。"]', '诗', 'shi', '', NULL, '遊涇川琴溪 武平一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8fe718c-a86b-43c0-9e05-944b70c54c57', '夜宴安樂公主宅', '夜宴安乐公主宅', '2d883805-5c5b-4bdf-9122-62fa17ee1f6e', '唐', '["王孫帝女下仙臺，金牓珠簾入夜開。","遽惜瓊筵歡正洽，唯愁銀箭曉相催。"]', '["王孫帝女下仙台，金牓珠簾入夜开。","遽惜瓊筵歡正洽，唯愁銀箭晓相催。"]', '诗', 'shi', '', NULL, '夜宴安樂公主宅 武平一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d22ae295-a2f3-4641-9508-9cb7dfae6eb4', '奉和聖製幸韋嗣立山莊應制', '奉和聖製幸韋嗣立山莊應制', '2d883805-5c5b-4bdf-9122-62fa17ee1f6e', '唐', '["鳴鑾赫奕下重樓，羽蓋逍遙向一丘。","漢日唯聞白衣寵，唐年更覩赤松遊。"]', '["鳴鑾赫奕下重楼，羽蓋逍遙向一丘。","漢日唯闻白衣寵，唐年更覩赤松游。"]', '诗', 'shi', '', NULL, '奉和聖製幸韋嗣立山莊應制 武平一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a1fe757-85b3-41c7-b7cd-6517e66b6e44', '餞唐永昌', '餞唐永昌', '2d883805-5c5b-4bdf-9122-62fa17ee1f6e', '唐', '["聞君墨綬出丹墀，雙舃飛來佇有期。","寄謝銅街攀柳日，無忘粉署握蘭時。"]', '["闻君墨綬出丹墀，雙舃飞来佇有期。","寄謝銅街攀柳日，無忘粉署握蘭时。"]', '诗', 'shi', '', NULL, '餞唐永昌 武平一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c554a87-f379-4c85-8df2-65a1ae0c04c9', '奉和聖製立春日侍宴內殿出剪綵花應制', '奉和聖製立春日侍宴內殿出剪綵花應制', '53c4275f-d144-47ce-b7e4-00d9814d3a35', '唐', '["剪綵迎初候，攀條故寫真。","花隨紅意發，葉就綠情新。","嫩色驚銜燕，輕香誤採人。","應爲熏風拂，能令芳樹春。"]', '["剪綵迎初候，攀條故寫真。","花隨紅意發，葉就綠情新。","嫩色驚銜燕，轻香誤採人。","應爲熏风拂，能令芳樹春。"]', '诗', 'shi', '', NULL, '奉和聖製立春日侍宴內殿出剪綵花應制 趙彥昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b380fb7e-874f-4ef7-a47f-ab28571b7778', '奉和人日清暉閣宴羣臣遇雪應制', '奉和人日清暉閣宴羣臣遇雪應制', '53c4275f-d144-47ce-b7e4-00d9814d3a35', '唐', '["出震乘東陸，憑高御北辰。","祥雲應早歲，瑞雪候初旬。","庭樹千花發，階蓂七葉新。","幸承今日宴，長奉萬年春。"]', '["出震乘东陸，憑高御北辰。","祥云應早歲，瑞雪候初旬。","庭樹千花發，階蓂七葉新。","幸承今日宴，长奉万年春。"]', '诗', 'shi', '', NULL, '奉和人日清暉閣宴羣臣遇雪應制 趙彥昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('357a9b75-35fa-4e0c-9a10-1d51f84a1e6f', '奉和七夕兩儀殿會宴應制', '奉和七夕兩儀殿會宴應制', '53c4275f-d144-47ce-b7e4-00d9814d3a35', '唐', '["青女三秋節，黃姑七日期。","星橋度玉珮，雲閣掩羅帷。","河氣通仙掖，天文入睿詞。","今宵望靈漢，應得見蛾眉。"]', '["青女三秋節，黄姑七日期。","星橋度玉珮，云閣掩羅帷。","河氣通仙掖，天文入睿词。","今宵望靈漢，應得见蛾眉。"]', '诗', 'shi', '', NULL, '奉和七夕兩儀殿會宴應制 趙彥昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87c44231-ad2f-4024-b056-99e1198bcc46', '奉和九日幸臨渭亭登高應制', '奉和九日幸臨渭亭登高應制', '53c4275f-d144-47ce-b7e4-00d9814d3a35', '唐', '["秋豫凝仙覽，宸遊轉翠華。","呼鷹下鳥路，戲馬出龍沙。","紫菊宜新壽，丹萸辟舊邪。","須陪長久宴，歲歲奉吹花。"]', '["秋豫凝仙覽，宸游轉翠华。","呼鷹下鸟路，戲马出龙沙。","紫菊宜新壽，丹萸辟旧邪。","須陪长久宴，歲歲奉吹花。"]', '诗', 'shi', '', NULL, '奉和九日幸臨渭亭登高應制 趙彥昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9265172e-7267-4e9d-9fa9-f19ba3b5852e', '奉和九月九日登慈恩寺浮屠應制', '奉和九月九日登慈恩寺浮屠應制', '53c4275f-d144-47ce-b7e4-00d9814d3a35', '唐', '["出豫乘秋節，登高陟梵宮。","皇心滿塵界，佛跡現虛空。","日月宜長壽，人天得大通。","喜聞題寶偈，受記莫由同。"]', '["出豫乘秋節，登高陟梵宮。","皇心满塵界，佛跡現虛空。","日月宜长壽，人天得大通。","喜闻題寶偈，受記莫由同。"]', '诗', 'shi', '', NULL, '奉和九月九日登慈恩寺浮屠應制 趙彥昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eebc7824-49f4-4fb9-85b0-a0ce8d938a8e', '安樂公主移入新宅侍宴應制同用開字', '安乐公主移入新宅侍宴應制同用开字', '53c4275f-d144-47ce-b7e4-00d9814d3a35', '唐', '["雲物中京曉，天人外館開。","飛橋象河漢，懸牓學蓬萊。","北闕臨仙檻，南山送壽杯。","一窺輪奐畢，慚恧棟梁材。"]', '["云物中京晓，天人外館开。","飞橋象河漢，懸牓学蓬萊。","北闕臨仙檻，南山送壽杯。","一窺輪奐畢，慚恧棟梁材。"]', '诗', 'shi', '', NULL, '安樂公主移入新宅侍宴應制同用開字 趙彥昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bfb9219-ca68-4f1f-81f9-040420daeff7', '奉和送金城公主適西蕃應制', '奉和送金城公主適西蕃應制', '53c4275f-d144-47ce-b7e4-00d9814d3a35', '唐', '["聖后經綸遠，謀臣計畫多。","受降追漢策，築館許戎和。","俗化烏孫壘，春生積石河。","六龍今出餞，雙鶴願爲歌。"]', '["聖后經綸远，謀臣計畫多。","受降追漢策，築館許戎和。","俗化烏孫壘，春生積石河。","六龙今出餞，雙鹤願爲歌。"]', '诗', 'shi', '', NULL, '奉和送金城公主適西蕃應制 趙彥昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c01af4a8-9d4a-4a41-a3d7-275eac4704a5', '奉和聖製登驪山高頂寓目應制', '奉和聖製登驪山高頂寓目應制', '53c4275f-d144-47ce-b7e4-00d9814d3a35', '唐', '["皇情遍九垓，御輦駐昭回。","路若隨天轉，人疑近日來。","河看大禹鑿，山見巨靈開。","願扈登封駕，常持薦壽杯。"]', '["皇情遍九垓，御輦駐昭回。","路若隨天轉，人疑近日来。","河看大禹鑿，山见巨靈开。","願扈登封駕，常持薦壽杯。"]', '诗', 'shi', '', NULL, '奉和聖製登驪山高頂寓目應制 趙彥昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d178343f-1985-47e9-b36b-4887a7659429', '奉和幸白鹿觀應制', '奉和幸白鹿观應制', '53c4275f-d144-47ce-b7e4-00d9814d3a35', '唐', '["雲驂驅半景，星蹕坐中天。","國誕玄宗聖，家尋碧落仙。","玉杯鸞薦壽，寶算鶴知年。","一覩光華旦，欣承道德篇。"]', '["云驂驱半景，星蹕坐中天。","国誕玄宗聖，家尋碧落仙。","玉杯鸾薦壽，寶算鹤知年。","一覩光华旦，欣承道德篇。"]', '诗', 'shi', '', NULL, '奉和幸白鹿觀應制 趙彥昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6d0c98d-c11f-4124-bcec-00be26f8b5e0', '哭僕射鄂公楊再思', '哭僕射鄂公楊再思', '53c4275f-d144-47ce-b7e4-00d9814d3a35', '唐', '["兩揆光天秩，三朝奉帝熙。","何言集大鳥，忽此喪元龜。","坐歎公槐落，行聞宰樹悲。","壑舟今已去，寧有濟川期。"]', '["兩揆光天秩，三朝奉帝熙。","何言集大鸟，忽此喪元龟。","坐歎公槐落，行闻宰樹悲。","壑舟今已去，寧有濟川期。"]', '诗', 'shi', '', NULL, '哭僕射鄂公楊再思 趙彥昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f3e2276-e5f0-48e4-946e-c0febd9b9e0c', '人日侍讌大明宮應制', '人日侍讌大明宮應制', '53c4275f-d144-47ce-b7e4-00d9814d3a35', '唐', '["寶契無爲屬聖人，琱輿出幸玩芳辰。","平樓半入南山霧，飛閤旁臨東墅春。","夾路穠花千樹發，垂軒弱柳萬條新。","處處風光今日好，年年願奉屬車塵。"]', '["寶契無爲屬聖人，琱輿出幸玩芳辰。","平楼半入南山霧，飞閤旁臨东墅春。","夾路穠花千樹發，垂軒弱柳万條新。","处处风光今日好，年年願奉屬车塵。"]', '诗', 'shi', '', NULL, '人日侍讌大明宮應制 趙彥昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cce85c00-604a-4335-b673-e092dd992665', '奉和初春幸太平公主南莊應制', '奉和初春幸太平公主南莊應制', '53c4275f-d144-47ce-b7e4-00d9814d3a35', '唐', '["主第巖扃駕鵲橋，天門閶闔降鸞鑣。","歷亂旌旗轉雲樹，參差臺榭入煙霄。","林間花雜平陽舞，谷裏鶯和弄玉簫。","已陪沁水追歡日，行奉茅山訪道朝。"]', '["主第巖扃駕鵲橋，天门閶闔降鸾鑣。","歷亂旌旗轉云樹，參差台榭入煙霄。","林间花杂平陽舞，谷裏鶯和弄玉簫。","已陪沁水追歡日，行奉茅山訪道朝。"]', '诗', 'shi', '', NULL, '奉和初春幸太平公主南莊應制 趙彥昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5146d17b-44c9-4631-9a2b-b93c38b7fd77', '奉和幸安樂公主山莊應制', '奉和幸安乐公主山莊應制', '53c4275f-d144-47ce-b7e4-00d9814d3a35', '唐', '["六龍齊軫御朝曦，雙鷁維舟下綠池。","飛觀仰看雲外聳，浮橋直見海中移。","靈泉巧鑿天孫渚，孝筍能抽帝女枝。","幸願一生同草樹，年年歲歲樂於斯。"]', '["六龙齊軫御朝曦，雙鷁維舟下綠池。","飞观仰看云外聳，浮橋直见海中移。","靈泉巧鑿天孫渚，孝筍能抽帝女枝。","幸願一生同草樹，年年歲歲乐於斯。"]', '诗', 'shi', '', NULL, '奉和幸安樂公主山莊應制 趙彥昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94955f70-a6be-494e-9950-d29341591fe8', '奉和幸大薦福寺', '奉和幸大薦福寺', '53c4275f-d144-47ce-b7e4-00d9814d3a35', '唐', '["寶地龍飛後，金身佛現時。","千花開國界，萬善累皇基。","北闕承行幸，西園屬住持。","天衣拂舊石，王舍起新祠。","剎鳳迎琱輦，幡虹駐綵旗。","同沾小雨潤，竊仰大風詩。"]', '["寶地龙飞後，金身佛現时。","千花开国界，万善累皇基。","北闕承行幸，西园屬住持。","天衣拂旧石，王舍起新祠。","剎鳳迎琱輦，幡虹駐綵旗。","同沾小雨潤，竊仰大风诗。"]', '诗', 'shi', '', NULL, '奉和幸大薦福寺 趙彥昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4307bc0-2cc3-4ee8-9b73-6068352937e2', '奉和幸長安故城未央宮應制', '奉和幸长安故城未央宮應制', '53c4275f-d144-47ce-b7e4-00d9814d3a35', '唐', '["夙駕移天蹕，憑軒覽漢都。","寒煙收紫禁，春色繞黃圖。","舊史遺陳迹，前王失霸符。","山河寸土盡，宮觀尺椽無。","崇高惟在德，壯麗豈爲謨。","茨室留皇鑒，熏歌盛有虞。"]', '["夙駕移天蹕，憑軒覽漢都。","寒煙收紫禁，春色繞黄圖。","旧史遺陳迹，前王失霸符。","山河寸土尽，宮观尺椽無。","崇高惟在德，壯丽豈爲謨。","茨室留皇鑒，熏歌盛有虞。"]', '诗', 'shi', '', NULL, '奉和幸長安故城未央宮應制 趙彥昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4493c79f-42a0-4d5b-828b-e872c9d8928e', '奉和幸韋嗣立山莊侍燕應制', '奉和幸韋嗣立山莊侍燕應制', '53c4275f-d144-47ce-b7e4-00d9814d3a35', '唐', '["賢族唯題里，儒門但署鄉。","何如表巖洞，宸翰發輝光。","地在茲山曲，家臨郃水陽。","六龍駐旌罕，四牡耀旂常。","北斗臨台座，東山入廟堂。","天高羽翼近，主聖股肱良。","野竹池亭氣，村花澗谷香。","縱然懷豹隱，空愧躡鵷行。"]', '["賢族唯題里，儒门但署乡。","何如表巖洞，宸翰發輝光。","地在茲山曲，家臨郃水陽。","六龙駐旌罕，四牡耀旂常。","北斗臨台座，东山入廟堂。","天高羽翼近，主聖股肱良。","野竹池亭氣，村花澗谷香。","縱然懷豹隐，空愧躡鵷行。"]', '诗', 'shi', '', NULL, '奉和幸韋嗣立山莊侍燕應制 趙彥昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd70c013-9c45-4ea0-b326-15217c4a82d7', '奉和元日賜羣臣栢葉應制', '奉和元日賜羣臣栢葉應制', '53c4275f-d144-47ce-b7e4-00d9814d3a35', '唐', '["器乏雕梁器，材非構廈材。","但將千歲葉，常奉萬年杯。"]', '["器乏雕梁器，材非構廈材。","但將千歲葉，常奉万年杯。"]', '诗', 'shi', '', NULL, '奉和元日賜羣臣栢葉應制 趙彥昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ea04e5b-c451-4f23-9914-a5dd163bc169', '苑中人日遇雪應制', '苑中人日遇雪應制', '53c4275f-d144-47ce-b7e4-00d9814d3a35', '唐', '["始見青雲干律呂，俄逢瑞雪應陽春。","今日迴看上林樹，梅花柳絮一時新。"]', '["始见青云干律呂，俄逢瑞雪應陽春。","今日迴看上林樹，梅花柳絮一时新。"]', '诗', 'shi', '', NULL, '苑中人日遇雪應制 趙彥昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7ba1af6-b990-4faa-aacd-7bfdce317f98', '奉和聖製幸韋嗣立山莊應制', '奉和聖製幸韋嗣立山莊應制', '53c4275f-d144-47ce-b7e4-00d9814d3a35', '唐', '["廊廟心存巖壑中，鑾輿矚在灞城東。","逍遙自在蒙莊子，漢主徒言河上公。"]', '["廊廟心存巖壑中，鑾輿矚在灞城东。","逍遙自在蒙莊子，漢主徒言河上公。"]', '诗', 'shi', '', NULL, '奉和聖製幸韋嗣立山莊應制 趙彥昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5ab85c8-7f9d-4fd3-87cb-ecf374679ba1', '秋朝木芙蓉', '秋朝木芙蓉', '53c4275f-d144-47ce-b7e4-00d9814d3a35', '唐', '["水面芙蓉秋已衰，繁條偏是著花遲。","平明露滴垂紅臉，似有朝愁暮落時。"]', '["水面芙蓉秋已衰，繁條偏是著花遲。","平明露滴垂紅臉，似有朝愁暮落时。"]', '诗', 'shi', '', NULL, '秋朝木芙蓉 趙彥昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4b40cb2-2a03-47a8-98e8-ce7eec3a275d', '侍宴桃花園詠桃花應制', '侍宴桃花园詠桃花應制', '53c4275f-d144-47ce-b7e4-00d9814d3a35', '唐', '["紅萼競燃春苑曙，粉茸新吐御筵開。","長年願奉西王母，近侍慚無東朔才。"]', '["紅萼競燃春苑曙，粉茸新吐御筵开。","长年願奉西王母，近侍慚無东朔才。"]', '诗', 'shi', '', NULL, '侍宴桃花園詠桃花應制 趙彥昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c261f594-8ad6-41db-a05b-6065cf277a8b', '奉和九日幸臨渭亭登高應制得餘字', '奉和九日幸臨渭亭登高應制得餘字', '80f61c63-0300-4b2c-ad6b-137171ae5925', '唐', '["望幸三秋暮，登高九日初。","朱旗巡漢苑，翠帟俯秦墟。","寵極萸房遍，恩深菊酎餘。","承歡何以荅，萬億奉宸居。"]', '["望幸三秋暮，登高九日初。","朱旗巡漢苑，翠帟俯秦墟。","寵極萸房遍，恩深菊酎餘。","承歡何以荅，万億奉宸居。"]', '诗', 'shi', '', NULL, '奉和九日幸臨渭亭登高應制得餘字 蕭至忠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08860783-d978-4a97-95d5-68860a19fe7d', '奉和九月九日登慈恩寺浮圖應制', '奉和九月九日登慈恩寺浮圖應制', '80f61c63-0300-4b2c-ad6b-137171ae5925', '唐', '["天蹕三乘啓，星輿六轡行。","登高凌寶塔，極目徧王城。","神衞空中遶，仙歌雲外清。","重陽千萬壽，率舞頌昇平。"]', '["天蹕三乘啓，星輿六轡行。","登高凌寶塔，極目徧王城。","神衞空中遶，仙歌云外清。","重陽千万壽，率舞頌昇平。"]', '诗', 'shi', '', NULL, '奉和九月九日登慈恩寺浮圖應制 蕭至忠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71c0f59c-3b6b-4083-9250-e0d99ea57f0f', '奉和幸安樂公主山莊應制', '奉和幸安乐公主山莊應制', '80f61c63-0300-4b2c-ad6b-137171ae5925', '唐', '["西郊窈窕鳳皇臺，北渚平明法駕來。","匝地金聲初度曲，周堂玉溜好傳杯。","灣路分遊畫舟轉，岸門相向碧亭開。","微臣此時承宴樂，髣髴疑從星漢迴。"]', '["西郊窈窕鳳皇台，北渚平明法駕来。","匝地金声初度曲，周堂玉溜好傳杯。","灣路分游畫舟轉，岸门相向碧亭开。","微臣此时承宴乐，髣髴疑從星漢迴。"]', '诗', 'shi', '', NULL, '奉和幸安樂公主山莊應制 蕭至忠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec195244-2805-4a55-acfb-34e3e49660f1', '送張亶赴朔方應制', '送張亶赴朔方應制', '80f61c63-0300-4b2c-ad6b-137171ae5925', '唐', '["命將擇耆年，圖功勝必全。","光輝萬乘餞，威武二庭宣。","中衢橫鼓角，曠野蔽旌旃。","推食天廚至，投醪御酒傳。","涼風過鴈苑，殺氣下雞田。","分閫恩何極，臨岐動睿篇。"]', '["命將擇耆年，圖功勝必全。","光輝万乘餞，威武二庭宣。","中衢橫鼓角，曠野蔽旌旃。","推食天廚至，投醪御酒傳。","涼风過鴈苑，殺氣下雞田。","分閫恩何極，臨岐动睿篇。"]', '诗', 'shi', '', NULL, '送張亶赴朔方應制 蕭至忠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9cc0940-aff6-4989-95d4-b7a780b0dc27', '陪幸長寧公主林亭', '陪幸长寧公主林亭', '80f61c63-0300-4b2c-ad6b-137171ae5925', '唐', '["公主林亭地，清晨降玉輿。","畫橋飛渡水，仙閣逈臨虛。","新晴看蛺蝶，早夏摘芙蕖。","文酒娛遊盛，忻叨侍從餘。"]', '["公主林亭地，清晨降玉輿。","畫橋飞渡水，仙閣逈臨虛。","新晴看蛺蝶，早夏摘芙蕖。","文酒娛游盛，忻叨侍從餘。"]', '诗', 'shi', '', NULL, '陪幸長寧公主林亭 蕭至忠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('620e6a73-5aa9-4c8c-8eed-fe95014860cc', '陪幸五王宅', '陪幸五王宅', '80f61c63-0300-4b2c-ad6b-137171ae5925', '唐', '["北斗樞機任，西京肺腑親。","疇昔王門下，今茲制幸晨。","恩來山水被，聖作管弦新。","遶座薰紅藥，當軒暗綠筠。","摘荷纔早夏，聽鳥尚餘春。","行漏金徒曉，風煙是觀津。"]', '["北斗樞機任，西京肺腑親。","疇昔王门下，今茲制幸晨。","恩来山水被，聖作管弦新。","遶座薰紅藥，當軒暗綠筠。","摘荷纔早夏，听鸟尚餘春。","行漏金徒晓，风煙是观津。"]', '诗', 'shi', '', NULL, '陪幸五王宅 蕭至忠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a138f221-c3fa-4f9c-be94-fb1cdffdf518', '三會寺應制', '三會寺應制', '80f61c63-0300-4b2c-ad6b-137171ae5925', '唐', '["岧嶤倉史臺，敞朗紺園開。","戒旦壺人警，翻霜羽騎來。","下輦登三襲，褰旒望九垓。","林披館陶牓，水浸昆明灰。","網戶飛花綴，幡竿度鳥迴。","豫遊仙唱動，瀟灑初塵埃。"]', '["岧嶤倉史台，敞朗紺园开。","戒旦壺人警，翻霜羽騎来。","下輦登三襲，褰旒望九垓。","林披館陶牓，水浸昆明灰。","網戶飞花綴，幡竿度鸟迴。","豫游仙唱动，瀟灑初塵埃。"]', '诗', 'shi', '', NULL, '三會寺應制 蕭至忠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11eb12b4-9968-40ff-88c2-884a77f91ece', '薦福寺應制', '薦福寺應制', '80f61c63-0300-4b2c-ad6b-137171ae5925', '唐', '["地靈傳景福，天駕儼鉤陳。","佳哉藩邸舊，赫矣梵宮新。","香塔魚山下，禪堂鴈水濱。","珠幡映白日，鏡殿寫青春。","甚懽延故吏，大覺拯生人。","幸承歌頌末，長奉屬車[塵]。"]', '["地靈傳景福，天駕儼鉤陳。","佳哉藩邸旧，赫矣梵宮新。","香塔鱼山下，禪堂鴈水濱。","珠幡映白日，镜殿寫青春。","甚懽延故吏，大覺拯生人。","幸承歌頌末，长奉屬车[塵]。"]', '诗', 'shi', '', NULL, '薦福寺應制 蕭至忠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a39ebbbd-8626-4de4-a582-23146a31e189', '陪遊上苑遇雪', '陪游上苑遇雪', '80f61c63-0300-4b2c-ad6b-137171ae5925', '唐', '["龍驂曉入望春宮，正逢春雪舞春風。","花光倂在天文上，寒氣行銷御酒中。"]', '["龙驂晓入望春宮，正逢春雪舞春风。","花光倂在天文上，寒氣行銷御酒中。"]', '诗', 'shi', '', NULL, '陪遊上苑遇雪 蕭至忠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('257a9f3b-dbdd-458c-9cb2-f5e4361a73f0', '奉和九日幸臨渭亭登高應制得風字', '奉和九日幸臨渭亭登高應制得风字', 'f7ad212a-ee60-4cc9-8fd5-f7fe40537023', '唐', '["重九臨商節，登高出漢宮。","正逢萸實滿，還對菊花叢。","霽雲開就日，仙藻麗秋風。","微臣預在鎬，竊抃遂無窮。"]', '["重九臨商節，登高出漢宮。","正逢萸實满，還对菊花叢。","霽云开就日，仙藻丽秋风。","微臣預在鎬，竊抃遂無窮。"]', '诗', 'shi', '', NULL, '奉和九日幸臨渭亭登高應制得風字 李迥秀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76c68224-117d-4b08-8a6a-1f4fe60998e1', '奉和九月九日登慈恩寺浮圖應制', '奉和九月九日登慈恩寺浮圖應制', 'f7ad212a-ee60-4cc9-8fd5-f7fe40537023', '唐', '["沙界人王塔，金繩梵帝遊。","言從[祇]樹賞，行翫菊叢秋。","御酒調甘露，天花拂綵旒。","堯年將佛日，同此慶時休。"]', '["沙界人王塔，金繩梵帝游。","言從[祇]樹賞，行翫菊叢秋。","御酒調甘露，天花拂綵旒。","堯年將佛日，同此慶时休。"]', '诗', 'shi', '', NULL, '奉和九月九日登慈恩寺浮圖應制 李迥秀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bf34ea6-b786-44e9-975f-8082a33269ee', '奉和幸安樂公主山莊應制', '奉和幸安乐公主山莊應制', 'f7ad212a-ee60-4cc9-8fd5-f7fe40537023', '唐', '["詰旦重門聞警蹕，傳言太主奏山林。","是日迴輿羅萬騎，此時歡喜賜千金。","鷺羽鳳簫參樂曲，荻園竹徑接帷陰。","手舞足蹈方無已，萬年千歲奉薰琴。"]', '["詰旦重门闻警蹕，傳言太主奏山林。","是日迴輿羅万騎，此时歡喜賜千金。","鷺羽鳳簫參乐曲，荻园竹徑接帷陰。","手舞足蹈方無已，万年千歲奉薰琴。"]', '诗', 'shi', '', NULL, '奉和幸安樂公主山莊應制 李迥秀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c72f248e-477c-4b3d-ad72-3bdc3a497e59', '夜宴安樂公主宅', '夜宴安乐公主宅', 'f7ad212a-ee60-4cc9-8fd5-f7fe40537023', '唐', '["金牓岧嶤雲裏開，玉簫參差天際迴。","莫驚側弁還歸路，秖爲平陽歌舞催。"]', '["金牓岧嶤云裏开，玉簫參差天際迴。","莫驚側弁還归路，秖爲平陽歌舞催。"]', '诗', 'shi', '', NULL, '夜宴安樂公主宅 李迥秀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42c48179-a43b-46eb-85cf-e2f712cc81da', '奉和九日幸臨渭亭登高應制得亭字', '奉和九日幸臨渭亭登高應制得亭字', 'dfae7451-7902-4ae4-be6a-d906e17d5722', '唐', '["遠目瞰秦坰，重陽坐灞亭。","既開黃菊酒，還降紫微星。","簫鼓諳仙曲，山河入畫屏。","幸茲陪宴喜，無以效丹青。"]', '["远目瞰秦坰，重陽坐灞亭。","既开黄菊酒，還降紫微星。","簫鼓諳仙曲，山河入畫屏。","幸茲陪宴喜，無以效丹青。"]', '诗', 'shi', '', NULL, '奉和九日幸臨渭亭登高應制得亭字 楊廉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdf666d1-3ed9-4732-8d0f-88d4c9752db8', '奉和九月九日登慈恩寺浮圖應制', '奉和九月九日登慈恩寺浮圖應制', 'dfae7451-7902-4ae4-be6a-d906e17d5722', '唐', '["萬乘臨真境，重陽眺遠空。","慈雲浮鴈塔，定水映龍宮。","寶鐸含飆響，仙輪帶日紅。","天文將瑞色，輝煥滿寰中。"]', '["万乘臨真境，重陽眺远空。","慈云浮鴈塔，定水映龙宮。","寶鐸含飆响，仙輪带日紅。","天文將瑞色，輝煥满寰中。"]', '诗', 'shi', '', NULL, '奉和九月九日登慈恩寺浮圖應制 楊廉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de75bf9f-8d29-41a6-9a03-ce01876f7971', '奉和九日幸臨渭亭登高應制得枝字', '奉和九日幸臨渭亭登高應制得枝字', '65a95d2b-436e-4085-b0a0-ae558042c8d2', '唐', '["重九開秋節，得一動宸儀。","金風飄菊蘂，玉露泫萸枝。","睿覽八紘外，天文七曜披。","臨深應在即，居高豈忘危。"]', '["重九开秋節，得一动宸儀。","金风飄菊蘂，玉露泫萸枝。","睿覽八紘外，天文七曜披。","臨深應在即，居高豈忘危。"]', '诗', 'shi', '', NULL, '奉和九日幸臨渭亭登高應制得枝字 韋安石 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebf3cd84-4a86-408e-be9b-442cc85352fe', '侍宴旋師喜捷應制', '侍宴旋師喜捷應制', '65a95d2b-436e-4085-b0a0-ae558042c8d2', '唐', '["蜂蟻屯夷落，熊羆逐漢飛。","忘軀百戰後，屈指一年歸。","厚眷紓天藻，深慈解御衣。","興酣歌舞出，朝野歎光輝。"]', '["蜂蟻屯夷落，熊羆逐漢飞。","忘軀百戰後，屈指一年归。","厚眷紓天藻，深慈解御衣。","兴酣歌舞出，朝野歎光輝。"]', '诗', 'shi', '', NULL, '侍宴旋師喜捷應制 韋安石 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99fb5e40-b003-4591-8a47-1e160dfa080e', '梁王宅侍宴應制同用風字', '梁王宅侍宴應制同用风字', '65a95d2b-436e-4085-b0a0-ae558042c8d2', '唐', '["梁園開勝景，軒駕動宸衷。","早荷承湛露，脩竹引薰風。","九醞傾鍾石，百獸協絲桐。","小臣陪宴鎬，獻壽奉維嵩。"]', '["梁园开勝景，軒駕动宸衷。","早荷承湛露，脩竹引薰风。","九醞傾鍾石，百獸協絲桐。","小臣陪宴鎬，獻壽奉維嵩。"]', '诗', 'shi', '', NULL, '梁王宅侍宴應制同用風字 韋安石 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1e324d9-e77a-485f-b4b6-5ba070d0b75c', '奉和九日幸臨渭亭登高應制得明字', '奉和九日幸臨渭亭登高應制得明字', 'b7764d70-990f-4feb-a499-3ebf19d2ca2a', '唐', '["鑾輿巡上苑，鳳駕瞰層城。","御座丹烏麗，宸居白鶴驚。","玉旗縈桂葉，金杯汎菊英。","九晨陪聖膳，萬歲奉承明。"]', '["鑾輿巡上苑，鳳駕瞰層城。","御座丹烏丽，宸居白鹤驚。","玉旗縈桂葉，金杯汎菊英。","九晨陪聖膳，万歲奉承明。"]', '诗', 'shi', '', NULL, '奉和九日幸臨渭亭登高應制得明字 竇希玠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9912716c-15ef-4300-91a5-c82b1e452fbe', '奉和九日幸臨渭亭登高應制得臣字', '奉和九日幸臨渭亭登高應制得臣字', '5ab1393e-e957-4aff-a0c5-4e4a5797ea52', '唐', '["九秋光順豫，重節霽良辰。","登高識漢苑，問道侍軒臣。","菊花浮秬鬯，萸房插縉紳。","聖化邊陲謐，長洲鴻雁賓。"]', '["九秋光順豫，重節霽良辰。","登高識漢苑，问道侍軒臣。","菊花浮秬鬯，萸房插縉紳。","聖化邊陲謐，长洲鴻雁賓。"]', '诗', 'shi', '', NULL, '奉和九日幸臨渭亭登高應制得臣字 陸景初 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33c54d66-3d90-41a1-b8fb-dd73e1fd8819', '奉和九日幸臨渭亭登高應制得日字', '奉和九日幸臨渭亭登高應制得日字', 'fb4017e3-5b94-48a3-9c69-ec7f16196445', '唐', '["重陽玉律應，萬乘金輿出。","風起韻虞弦，雲開吐堯日。","菊花浮聖酒，茱香挂衰質。","欲知恩煦多，順動觀秋實。"]', '["重陽玉律應，万乘金輿出。","风起韻虞弦，云开吐堯日。","菊花浮聖酒，茱香挂衰質。","欲知恩煦多，順动观秋實。"]', '诗', 'shi', '', NULL, '奉和九日幸臨渭亭登高應制得日字 鄭南金 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cc7048a-1939-4de7-a928-a1e1986ed218', '奉和九日幸臨渭亭登高應制得直字', '奉和九日幸臨渭亭登高應制得直字', '97693446-ac45-4771-a361-52cbe48d96c2', '唐', '["重陽乘令序，四野開晴色。","日月數初幷，乾坤聖登極。","菊黃迎酒泛，松翠凌霜直。","遊海難爲深，負山徒倦力。"]', '["重陽乘令序，四野开晴色。","日月數初幷，乾坤聖登極。","菊黄迎酒泛，松翠凌霜直。","游海难爲深，負山徒倦力。"]', '诗', 'shi', '', NULL, '奉和九日幸臨渭亭登高應制得直字 李咸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99297825-8deb-454c-90f2-fea3c6f0890c', '奉和九日幸臨渭亭登高應制得花字', '奉和九日幸臨渭亭登高應制得花字', 'baa921db-caa9-4556-9ab9-7801616aa382', '唐', '["九日報仙家，三秋轉歲華。","呼鷹下鳥路，戲馬出龍沙。","簪挂丹萸蘂，杯浮紫菊花。","所願同微物，年年共辟邪。"]', '["九日報仙家，三秋轉歲华。","呼鷹下鸟路，戲马出龙沙。","簪挂丹萸蘂，杯浮紫菊花。","所願同微物，年年共辟邪。"]', '诗', 'shi', '', NULL, '奉和九日幸臨渭亭登高應制得花字 趙彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab6b9019-8e9e-4c78-9b41-8870ad5c9d30', '從宴桃花園詠桃花應制', '從宴桃花园詠桃花應制', 'baa921db-caa9-4556-9ab9-7801616aa382', '唐', '["紅萼競燃春苑曙，䒠茸新吐御筵開。","長年願奉西王讌，近侍慚無東朔才。"]', '["紅萼競燃春苑曙，䒠茸新吐御筵开。","长年願奉西王讌，近侍慚無东朔才。"]', '诗', 'shi', '', NULL, '從宴桃花園詠桃花應制 趙彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6cf7ffe-bf0a-48d5-9e3c-5927cefc4050', '苑中遇雪應制', '苑中遇雪應制', 'baa921db-caa9-4556-9ab9-7801616aa382', '唐', '["千鍾聖酒御筵披，六出祥英亂遶枝。","即此神仙對瓊圃，何煩轍跡向瑤池。"]', '["千鍾聖酒御筵披，六出祥英亂遶枝。","即此神仙对瓊圃，何煩轍跡向瑤池。"]', '诗', 'shi', '', NULL, '苑中遇雪應制 趙彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f25e2481-52d7-4182-af87-4e7b776d33ab', '奉和九日幸臨渭亭登高應制得樽字', '奉和九日幸臨渭亭登高應制得樽字', '36380f40-5379-4fd6-b7ee-0d2dae43c487', '唐', '["御氣三秋節，登高九曲門。","桂筵羅玉俎，菊醴溢芳樽。","遵渚歸鴻度，承雲舞鶴鶱。","微臣濫陪賞，空荷聖明恩。"]', '["御氣三秋節，登高九曲门。","桂筵羅玉俎，菊醴溢芳樽。","遵渚归鴻度，承云舞鹤鶱。","微臣濫陪賞，空荷聖明恩。"]', '诗', 'shi', '', NULL, '奉和九日幸臨渭亭登高應制得樽字 于經野 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71821b86-17b6-41fc-a1cd-6c27242b61ee', '奉和九日幸臨渭亭登高應制得還字', '奉和九日幸臨渭亭登高應制得還字', '4ed8f683-7f3d-40a7-ab93-0b9fc01daca4', '唐', '["時和素秋節，宸豫紫機關。","鶴似聞琴至，人疑宴鎬還。","曠望臨平野，潺湲俯瞑灣。","無因酬大德，空此媿崇班。"]', '["时和素秋節，宸豫紫機关。","鹤似闻琴至，人疑宴鎬還。","曠望臨平野，潺湲俯瞑灣。","無因酬大德，空此媿崇班。"]', '诗', 'shi', '', NULL, '奉和九日幸臨渭亭登高應制得還字 盧懷慎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('525315c3-238f-40cd-9433-be42332174d3', '奉和聖製龍池篇', '奉和聖製龙池篇', '4ed8f683-7f3d-40a7-ab93-0b9fc01daca4', '唐', '["代邸東南龍躍泉，清漪碧浪遠浮天。","樓臺影就波中出，日月光疑鏡裏懸。","雁沼洄流成舜海，龜書薦社應堯年。","大川既濟慙爲楫，報德空思奉細涓。"]', '["代邸东南龙躍泉，清漪碧浪远浮天。","楼台影就波中出，日月光疑镜裏懸。","雁沼洄流成舜海，龟书薦社應堯年。","大川既濟慙爲楫，報德空思奉細涓。"]', '诗', 'shi', '', NULL, '奉和聖製龍池篇 盧懷慎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32bf5259-2813-48cc-b20f-051b1cb271bd', '奉和九月九日登慈恩寺浮圖應制', '奉和九月九日登慈恩寺浮圖應制', 'cd623a9d-6648-4aa0-9904-87b180ab052d', '唐', '["洪慈均動植，至德俯深玄。","出豫從初地，登高適梵天。","白雲飛御藻，慧日暖皇編。","別有秋原藿，長傾雨露緣。"]', '["洪慈均动植，至德俯深玄。","出豫從初地，登高適梵天。","白云飞御藻，慧日暖皇編。","別有秋原藿，长傾雨露緣。"]', '诗', 'shi', '', NULL, '奉和九月九日登慈恩寺浮圖應制 辛替否 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f108d618-8227-4080-aa89-32c2baad96cc', '奉和九月九日登慈恩寺浮圖應制', '奉和九月九日登慈恩寺浮圖應制', 'eeb5dafa-8dc0-496f-a97f-ec8ea60eceb9', '唐', '["玉輦移中禁，珠梯覽四禪。","重階清漢接，飛竇紫霄懸。","綴葉披天藻，吹花散御筵。","無因鑾蹕暇，俱舞鶴林前。"]', '["玉輦移中禁，珠梯覽四禪。","重階清漢接，飞竇紫霄懸。","綴葉披天藻，吹花散御筵。","無因鑾蹕暇，俱舞鹤林前。"]', '诗', 'shi', '', NULL, '奉和九月九日登慈恩寺浮圖應制 王景 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3654c63d-a93d-41b3-aa3b-3b1d7387eb97', '奉和九月九日登慈恩寺浮圖應制', '奉和九月九日登慈恩寺浮圖應制', '600009df-b81a-4ad6-9fae-2fc2691fc2b4', '唐', '["鸚林花塔啟，鳳輦順時遊。","重九昭皇慶，大千揚帝休。","耆闍妙法闡，王舍睿文流。","至德覃無極，小臣歌詎酬。"]', '["鸚林花塔啟，鳳輦順时游。","重九昭皇慶，大千揚帝休。","耆闍妙法闡，王舍睿文流。","至德覃無極，小臣歌詎酬。"]', '诗', 'shi', '', NULL, '奉和九月九日登慈恩寺浮圖應制 畢乾泰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24d59c5b-0a80-4032-8cda-5ee93e109edd', '奉和九月九日登慈恩寺浮圖應制', '奉和九月九日登慈恩寺浮圖應制', '26519f19-a8d4-4e70-a36b-04a3bb3f8539', '唐', '["扈蹕遊玄地，陪仙瞰紫微。","似邁銖衣刼，將同羽化飛。","雕戈秋日麗，寶劒曉霜霏。","獻觴乘菊序，長願奉天暉。"]', '["扈蹕游玄地，陪仙瞰紫微。","似邁銖衣刼，將同羽化飞。","雕戈秋日丽，寶劒晓霜霏。","獻觴乘菊序，长願奉天暉。"]', '诗', 'shi', '', NULL, '奉和九月九日登慈恩寺浮圖應制 麴瞻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d13bfe60-91e1-455f-9f36-68b0612a44aa', '奉和九月九日登慈恩寺浮圖應制', '奉和九月九日登慈恩寺浮圖應制', 'a3fac9db-3273-48e0-9cf7-eff000d27877', '唐', '["淨境重陽節，仙遊萬乘來。","插萸登鷲嶺，把菊坐蜂臺。","十地祥雲合，三天瑞景開。","秋風詞更遠，竊抃樂康哉。"]', '["淨境重陽節，仙游万乘来。","插萸登鷲嶺，把菊坐蜂台。","十地祥云合，三天瑞景开。","秋风词更远，竊抃乐康哉。"]', '诗', 'shi', '', NULL, '奉和九月九日登慈恩寺浮圖應制 樊忱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3797c008-0fb6-45ae-b786-8ce02b1736d0', '奉和九月九日登慈恩寺浮圖應制', '奉和九月九日登慈恩寺浮圖應制', 'f87b18c0-7494-4776-ad30-efee8a0c18d6', '唐', '["應節萸房滿，初寒菊圃新。","龍旗煥辰極，鳳駕儼香闉。","蓮井偏宜夏，梅梁更若春。","一忻陪鴈塔，還似得天身。"]', '["應節萸房满，初寒菊圃新。","龙旗煥辰極，鳳駕儼香闉。","蓮井偏宜夏，梅梁更若春。","一忻陪鴈塔，還似得天身。"]', '诗', 'shi', '', NULL, '奉和九月九日登慈恩寺浮圖應制 孫佺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13941e18-7eb0-4cd3-89b8-f3a5d743e21d', '奉和九月九日登慈恩寺浮圖應制', '奉和九月九日登慈恩寺浮圖應制', 'bc00f3ce-e55c-40e3-891b-fd6d324fd7c8', '唐', '["九月從時豫，三乘爲法開。","中霄日天子，半座寶如來。","摘果珠盤獻，攀萸玉輦迴。","願將塵露點，遙奉光明臺。"]', '["九月從时豫，三乘爲法开。","中霄日天子，半座寶如来。","摘果珠盤獻，攀萸玉輦迴。","願將塵露点，遙奉光明台。"]', '诗', 'shi', '', NULL, '奉和九月九日登慈恩寺浮圖應制 李從遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b72c598-a554-48c3-a7cc-f8da784b50ba', '奉和九月九日登慈恩寺浮圖應制', '奉和九月九日登慈恩寺浮圖應制', 'e0f295db-0537-41ec-a6a7-6cb1dbff54be', '唐', '["出豫乘金節，飛文煥日宮。","萸房開聖酒，杏苑被玄功。","塔向三天迥，禪收八解空。","叨恩奉蘭藉，終愧洽薰風。"]', '["出豫乘金節，飞文煥日宮。","萸房开聖酒，杏苑被玄功。","塔向三天迥，禪收八解空。","叨恩奉蘭藉，終愧洽薰风。"]', '诗', 'shi', '', NULL, '奉和九月九日登慈恩寺浮圖應制 周利用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2bd99a1-8616-4140-858a-00dc5578bfa7', '奉和九月九日登慈恩寺浮圖應制', '奉和九月九日登慈恩寺浮圖應制', '85296fbc-d987-4339-b89c-7835e211781f', '唐', '["飛塔凌霄起，宸遊一届焉。","金壺新泛菊，寶座即披蓮。","就日搖香輦，憑雲出梵天。","祥氛與佳色，相伴雜鑪煙。"]', '["飞塔凌霄起，宸游一届焉。","金壺新泛菊，寶座即披蓮。","就日搖香輦，憑云出梵天。","祥氛與佳色，相伴杂鑪煙。"]', '诗', 'shi', '', NULL, '奉和九月九日登慈恩寺浮圖應制 張景源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b210aee2-7a1c-4780-be4f-a96ba8b1bf22', '奉和九月九日登慈恩寺浮圖應制', '奉和九月九日登慈恩寺浮圖應制', 'af1b6181-1764-4aec-84a7-3e79b27cbf1c', '唐', '["寶地隣丹掖，香臺瞰碧雲。","河山天外出，城闕樹中分。","睿藻蘭英秀，仙杯菊蘂薰。","願將今日樂，長奉聖明君。"]', '["寶地隣丹掖，香台瞰碧云。","河山天外出，城闕樹中分。","睿藻蘭英秀，仙杯菊蘂薰。","願將今日乐，长奉聖明君。"]', '诗', 'shi', '', NULL, '奉和九月九日登慈恩寺浮圖應制 李恆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d5b7326-964e-4402-8d76-241075a9bc6b', '奉和九月九日登慈恩寺浮圖應制', '奉和九月九日登慈恩寺浮圖應制', '7d7d0d5f-a114-4a1f-83f9-4996023c14f9', '唐', '["九秋霜景淨，千門曉望通。","仙遊光御路，瑞塔迥凌空。","菊彩揚堯日，萸香遶舜風。","天文麗辰象，竊抃仰層穹。"]', '["九秋霜景淨，千门晓望通。","仙游光御路，瑞塔迥凌空。","菊彩揚堯日，萸香遶舜风。","天文丽辰象，竊抃仰層穹。"]', '诗', 'shi', '', NULL, '奉和九月九日登慈恩寺浮圖應制 張錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7322f35-3568-45e6-9b17-0db1074ca77a', '晦日宴高文學林亭', '晦日宴高文学林亭', '7d7d0d5f-a114-4a1f-83f9-4996023c14f9', '唐', '["雪盡銅駝路，花照石崇家。","年光開柳色，池影汎雲華。","賞洽情方遠，春歸景未賒。","欲知多暇日，尊酒漬澄霞。"]', '["雪尽銅駝路，花照石崇家。","年光开柳色，池影汎云华。","賞洽情方远，春归景未賒。","欲知多暇日，尊酒漬澄霞。"]', '诗', 'shi', '', NULL, '晦日宴高文學林亭 張錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29243435-70b3-46c9-98f6-abeacdd54eae', '奉和九月九日登慈恩寺浮圖應制', '奉和九月九日登慈恩寺浮圖應制', 'b73e34a2-4996-4dca-b629-340efe31b4c4', '唐', '["瑞塔臨初地，金輿幸上方。","空邊有清淨，覺處無馨香。","雨霽微塵歛，風秋定水涼。","茲辰采仙菊，薦壽慶重陽。"]', '["瑞塔臨初地，金輿幸上方。","空邊有清淨，覺处無馨香。","雨霽微塵歛，风秋定水涼。","茲辰采仙菊，薦壽慶重陽。"]', '诗', 'shi', '', NULL, '奉和九月九日登慈恩寺浮圖應制 解琬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5647fb48-f78b-415b-932c-3d69550c40cb', '晦日宴高氏林亭', '晦日宴高氏林亭', 'b73e34a2-4996-4dca-b629-340efe31b4c4', '唐', '["主第簪裾出，王畿春照華。","山亭一以眺，城闕帶煙霞。","橫堤列錦帳，傍浦駐香車。","歡娛屬晦節，酩酊未還家。"]', '["主第簪裾出，王畿春照华。","山亭一以眺，城闕带煙霞。","橫堤列錦帳，傍浦駐香车。","歡娛屬晦節，酩酊未還家。"]', '诗', 'shi', '', NULL, '晦日宴高氏林亭 解琬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('deb2bdbe-e1da-4551-a66f-017c7a5be413', '侍宴長寧公主東莊應制', '侍宴长寧公主东莊應制', '86e135d6-5da2-49b1-afbf-81ea45ee411e', '唐', '["公門襲漢環，主第稱秦玉。","池架祥鱣序，山吹鳴鳳曲。","拂席蘿薜垂，迴舟芰荷觸。","平陽妙舞處，日暮清歌續。"]', '["公门襲漢环，主第稱秦玉。","池架祥鱣序，山吹鳴鳳曲。","拂席蘿薜垂，迴舟芰荷觸。","平陽妙舞处，日暮清歌續。"]', '诗', 'shi', '', NULL, '侍宴長寧公主東莊應制 鄭愔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d6f3ef1-39a0-4e48-95ea-4d012c92b4fa', '采蓮曲', '采蓮曲', '86e135d6-5da2-49b1-afbf-81ea45ee411e', '唐', '["錦䋏沙棠艦，羅帶石榴帬。","綠潭采荷芰，清江日稍曛。","魚鳥爭唼喋，花葉相芬氳。","不覺芳洲暮，菱歌處處聞。"]', '["錦䋏沙棠艦，羅带石榴帬。","綠潭采荷芰，清江日稍曛。","鱼鸟爭唼喋，花葉相芬氳。","不覺芳洲暮，菱歌处处闻。"]', '诗', 'shi', '', NULL, '采蓮曲 鄭愔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79031f67-be20-4ef3-b01a-60eb5f5ea925', '夜遊曲', '夜游曲', '86e135d6-5da2-49b1-afbf-81ea45ee411e', '唐', '["漢室歡娛盛，魏國文雅遒。","許史多暮宿，應陳從夜遊。","西園讌公子，北里召王侯。","詎似將軍獵，空嗟亭尉留。"]', '["漢室歡娛盛，魏国文雅遒。","許史多暮宿，應陳從夜游。","西园讌公子，北里召王侯。","詎似將軍獵，空嗟亭尉留。"]', '诗', 'shi', '', NULL, '夜遊曲 鄭愔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1cbd3b8-b932-4503-9398-967fafbc301e', '少年行', '少年行', '86e135d6-5da2-49b1-afbf-81ea45ee411e', '唐', '["潁川豪橫客，咸陽輕薄兒。","田竇方貴幸，趙李新相知。","軒蓋終朝集，笙竽此夜吹。","黃金盈篋笥，白日忽西馳。"]', '["潁川豪橫客，咸陽轻薄兒。","田竇方貴幸，趙李新相知。","軒蓋終朝集，笙竽此夜吹。","黄金盈篋笥，白日忽西驰。"]', '诗', 'shi', '', NULL, '少年行 鄭愔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29258541-edd2-4e50-846f-c27aec4b59c9', '中宗降誕日長寧公主滿月侍宴應制', '中宗降誕日长寧公主满月侍宴應制', '86e135d6-5da2-49b1-afbf-81ea45ee411e', '唐', '["春殿猗蘭美，仙階柏樹榮。","地逢芳節應，時覩聖人生。","月滿增祥莢，天長發瑞靈。","南山遙可獻，常願奉皇明。"]', '["春殿猗蘭美，仙階柏樹榮。","地逢芳節應，时覩聖人生。","月满增祥莢，天长發瑞靈。","南山遙可獻，常願奉皇明。"]', '诗', 'shi', '', NULL, '中宗降誕日長寧公主滿月侍宴應制 鄭愔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('877fdbe6-1d4f-42ef-9106-8237f10420ae', '奉和幸上官昭容院獻詩四首 一', '奉和幸上官昭容院獻诗四首 一', '86e135d6-5da2-49b1-afbf-81ea45ee411e', '唐', '["地軸樓居遠，天台闕路賒。","何如遊帝宅，即此對仙家。","座拂金壺電，池搖玉酒霞。","無云秦漢隔，別訪武陵花。"]', '["地軸楼居远，天台闕路賒。","何如游帝宅，即此对仙家。","座拂金壺電，池搖玉酒霞。","無云秦漢隔，別訪武陵花。"]', '诗', 'shi', '', NULL, '奉和幸上官昭容院獻詩四首 一 鄭愔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('218bf439-8fbd-4ddb-b578-ecfb526f3c69', '奉和幸上官昭容院獻詩四首 二', '奉和幸上官昭容院獻诗四首 二', '86e135d6-5da2-49b1-afbf-81ea45ee411e', '唐', '["堯茨姑射近，漢苑建章連。","十五蓂知月，三千桃紀年。","鸞歌隨鳳吹，鶴舞向鵾弦。","更覓瓊妃伴，來過玉女泉。"]', '["堯茨姑射近，漢苑建章連。","十五蓂知月，三千桃紀年。","鸾歌隨鳳吹，鹤舞向鵾弦。","更覓瓊妃伴，来過玉女泉。"]', '诗', 'shi', '', NULL, '奉和幸上官昭容院獻詩四首 二 鄭愔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44ec2fc1-0a4d-485e-bb79-eb05c147025a', '奉和幸上官昭容院獻詩四首 三', '奉和幸上官昭容院獻诗四首 三', '86e135d6-5da2-49b1-afbf-81ea45ee411e', '唐', '["宮掖賢才重，山林高尚難。","不言辭輦地，更有結廬歡。","池棟清溫燠，巖窗起沍寒。","幽亭有仙桂，聖主萬年看。"]', '["宮掖賢才重，山林高尚难。","不言辞輦地，更有結廬歡。","池棟清溫燠，巖窗起沍寒。","幽亭有仙桂，聖主万年看。"]', '诗', 'shi', '', NULL, '奉和幸上官昭容院獻詩四首 三 鄭愔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7e343ae-fa2c-4a4a-9b5e-e0e9550331ff', '奉和幸上官昭容院獻詩四首 四', '奉和幸上官昭容院獻诗四首 四', '86e135d6-5da2-49b1-afbf-81ea45ee411e', '唐', '["槎流天上轉，茅宇禁中開。","河鵲填橋至，山熊避檻來。","庭花采菉蓐，巖石步莓苔。","願奉輿圖泰，長開錦翰裁。"]', '["槎流天上轉，茅宇禁中开。","河鵲填橋至，山熊避檻来。","庭花采菉蓐，巖石步莓苔。","願奉輿圖泰，长开錦翰裁。"]', '诗', 'shi', '', NULL, '奉和幸上官昭容院獻詩四首 四 鄭愔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33e140e0-3364-4e31-b6fe-fc73eb7aa56b', '送金城公主適西蕃應制', '送金城公主適西蕃應制', '86e135d6-5da2-49b1-afbf-81ea45ee411e', '唐', '["下嫁戎庭遠，和親漢禮優。","笳聲出虜塞，簫曲背秦樓。","貴主悲黃鶴，征人怨紫騮。","皇情眷億兆，割念俯懷柔。"]', '["下嫁戎庭远，和親漢禮優。","笳声出虜塞，簫曲背秦楼。","貴主悲黄鹤，征人怨紫騮。","皇情眷億兆，割念俯懷柔。"]', '诗', 'shi', '', NULL, '送金城公主適西蕃應制 鄭愔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('083a696c-89c1-484d-9e86-96a93079f9aa', '奉和幸望春宮送朔方大總管張仁亶', '奉和幸望春宮送朔方大總管張仁亶', '86e135d6-5da2-49b1-afbf-81ea45ee411e', '唐', '["御蹕下都門，軍麾出塞垣。","長楊跨武騎，細柳接戎軒。","睿曲風雲動，邊威鼓吹喧。","坐帷將閫外，俱是報明恩。"]', '["御蹕下都门，軍麾出塞垣。","长楊跨武騎，細柳接戎軒。","睿曲风云动，邊威鼓吹喧。","坐帷將閫外，俱是報明恩。"]', '诗', 'shi', '', NULL, '奉和幸望春宮送朔方大總管張仁亶 鄭愔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d734f531-6626-4892-85b2-b1c9dd67ac85', '奉和九月九日登慈恩寺浮圖應制', '奉和九月九日登慈恩寺浮圖應制', '86e135d6-5da2-49b1-afbf-81ea45ee411e', '唐', '["湧霄開寶塔，倒影駐仙輿。","鴈子乘堂處，龍王起藏初。","秋風聖主曲，佳氣史官書。","願獻重陽壽，承歡萬歲餘。"]', '["湧霄开寶塔，倒影駐仙輿。","鴈子乘堂处，龙王起藏初。","秋风聖主曲，佳氣史官书。","願獻重陽壽，承歡万歲餘。"]', '诗', 'shi', '', NULL, '奉和九月九日登慈恩寺浮圖應制 鄭愔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c9f47d1-81e7-4cf0-bd23-0e8f7e76351f', '銅雀妓', '銅雀妓', '86e135d6-5da2-49b1-afbf-81ea45ee411e', '唐', '["日斜漳浦望，風起鄴臺寒。","玉座平生晚，金尊妓吹闌。","舞餘依帳泣，歌罷向陵看。","蕭索松風暮，愁煙入井闌。"]', '["日斜漳浦望，风起鄴台寒。","玉座平生晚，金尊妓吹闌。","舞餘依帳泣，歌罷向陵看。","蕭索松风暮，愁煙入井闌。"]', '诗', 'shi', '', NULL, '銅雀妓 鄭愔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdda7097-88e0-4e31-8cd1-3a08d472d029', '胡笳曲', '胡笳曲', '86e135d6-5da2-49b1-afbf-81ea45ee411e', '唐', '["漢將留邊朔，遙遙歲序深。","誰堪牧馬思，正是胡笳吟。","曲斷關山月，聲悲雨雪陰。","傳書問蘇武，陵也獨何心。"]', '["漢將留邊朔，遙遙歲序深。","誰堪牧马思，正是胡笳吟。","曲斷关山月，声悲雨雪陰。","傳书问蘇武，陵也独何心。"]', '诗', 'shi', '', NULL, '胡笳曲 鄭愔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de8e32f9-2b0c-48e2-89a6-7ef1db382ee2', '折楊柳', '折楊柳', '86e135d6-5da2-49b1-afbf-81ea45ee411e', '唐', '["青柳映紅顏，黃雲蔽紫關。","忽聞邊使出，枝葉爲君攀。","舞腰愁欲斷，春心望不還。","風花滾成雪，羅綺亂斑斑。"]', '["青柳映紅顏，黄云蔽紫关。","忽闻邊使出，枝葉爲君攀。","舞腰愁欲斷，春心望不還。","风花滾成雪，羅綺亂斑斑。"]', '诗', 'shi', '', NULL, '折楊柳 鄭愔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b84e25ca-6a35-40f4-8ddb-65f9a52d332c', '秋閨', '秋閨', '86e135d6-5da2-49b1-afbf-81ea45ee411e', '唐', '["征客向輪臺，幽閨寂不開。","音書秋鴈斷，機杼夜蛩催。","虛幌風吹葉，閑階露濕苔。","自憐愁思影，常共月裴回。"]', '["征客向輪台，幽閨寂不开。","音书秋鴈斷，機杼夜蛩催。","虛幌风吹葉，闲階露濕苔。","自怜愁思影，常共月裴回。"]', '诗', 'shi', '', NULL, '秋閨 鄭愔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c294f143-f783-4c4c-ba7a-36923e1b3428', '人日重宴大明宮恩賜綵縷人勝應制', '人日重宴大明宮恩賜綵縷人勝應制', '86e135d6-5da2-49b1-afbf-81ea45ee411e', '唐', '["瓊殿含光映早輪，玉鸞嚴蹕望初晨。","池開凍水仙宮麗，樹發寒花禁苑新。","佳氣裴回籠細網，殘霙淅瀝染輕塵。","良時荷澤皆迎勝，窮谷晞陽猶未春。"]', '["瓊殿含光映早輪，玉鸾嚴蹕望初晨。","池开凍水仙宮丽，樹發寒花禁苑新。","佳氣裴回籠細網，殘霙淅瀝染轻塵。","良时荷澤皆迎勝，窮谷晞陽猶未春。"]', '诗', 'shi', '', NULL, '人日重宴大明宮恩賜綵縷人勝應制 鄭愔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d003eb8-81c0-44f2-947e-de5b97164299', '奉和春日幸望春宮', '奉和春日幸望春宮', '86e135d6-5da2-49b1-afbf-81ea45ee411e', '唐', '["晨蹕凌高轉翠旌，春樓望遠背朱城。","忽排花上遊天苑，却坐雲邊看帝京。","百草香心初罥蝶，千林嫩葉始藏鶯。","幸同葵藿傾陽早，願比盤根應候榮。"]', '["晨蹕凌高轉翠旌，春楼望远背朱城。","忽排花上游天苑，却坐云邊看帝京。","百草香心初罥蝶，千林嫩葉始藏鶯。","幸同葵藿傾陽早，願比盤根應候榮。"]', '诗', 'shi', '', NULL, '奉和春日幸望春宮 鄭愔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c5b156d-4240-4564-80cf-05df684b1800', '奉和幸三會寺應制', '奉和幸三會寺應制', '86e135d6-5da2-49b1-afbf-81ea45ee411e', '唐', '["鳥籀遺新閣，龍旂訪古臺。","造書臣頡往，觀跡帝羲來。","睿覽山川匝，宸心宇宙該。","梵音隨駐輦，天步接乘杯。","舊苑經寒露，殘池問劫灰。","散花將捧日，俱喜聖慈開。"]', '["鸟籀遺新閣，龙旂訪古台。","造书臣頡往，观跡帝羲来。","睿覽山川匝，宸心宇宙該。","梵音隨駐輦，天步接乘杯。","旧苑經寒露，殘池问劫灰。","散花將捧日，俱喜聖慈开。"]', '诗', 'shi', '', NULL, '奉和幸三會寺應制 鄭愔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b940d2c-741a-4c49-b80b-a0d02ca62742', '奉和幸大薦福寺', '奉和幸大薦福寺', '86e135d6-5da2-49b1-afbf-81ea45ee411e', '唐', '["舊邸三乘闢，佳辰萬騎留。","蘭圖奉葉偈，芝蓋拂花樓。","國會人王法，宮還天帝遊。","紫雲成寶界，白水作禪流。","鴈塔昌基遠，鸚林睿藻抽。","欣承大風曲，竊預小童謳。"]', '["旧邸三乘闢，佳辰万騎留。","蘭圖奉葉偈，芝蓋拂花楼。","国會人王法，宮還天帝游。","紫云成寶界，白水作禪流。","鴈塔昌基远，鸚林睿藻抽。","欣承大风曲，竊預小童謳。"]', '诗', 'shi', '', NULL, '奉和幸大薦福寺 鄭愔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38dad855-5955-4d1d-8395-07437cabcaba', '同韋舍人早朝', '同韋舍人早朝', '86e135d6-5da2-49b1-afbf-81ea45ee411e', '唐', '["瑞闕龍居峻，宸庭鳳掖深。","才良寄天綍，趨拜侶朝簪。","飛馬看來影，喧車識駐音。","重軒輕霧入，洞戶落花侵。","聞有題新翰，依然想舊林。","同聲慙卞玉，謬此托韋金。"]', '["瑞闕龙居峻，宸庭鳳掖深。","才良寄天綍，趨拜侶朝簪。","飞马看来影，喧车識駐音。","重軒轻霧入，洞戶落花侵。","闻有題新翰，依然想旧林。","同声慙卞玉，謬此托韋金。"]', '诗', 'shi', '', NULL, '同韋舍人早朝 鄭愔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc6163f1-aca1-413b-b6ec-df3dd84394ab', '塞外三首 一', '塞外三首 一', '86e135d6-5da2-49b1-afbf-81ea45ee411e', '唐', '["塞外蕭條望，征人此路賒。","邊聲亂朔馬，秋色引胡笳。","遙嶂侵歸日，長城帶晚霞。","斷蓬飛古戍，連鴈聚寒沙。","海暗雲無葉，山春雪作花。","丈夫期報主，萬里獨辭家。"]', '["塞外蕭條望，征人此路賒。","邊声亂朔马，秋色引胡笳。","遙嶂侵归日，长城带晚霞。","斷蓬飞古戍，連鴈聚寒沙。","海暗云無葉，山春雪作花。","丈夫期報主，万里独辞家。"]', '诗', 'shi', '', NULL, '塞外三首 一 鄭愔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42964d1f-7861-457b-8a4c-ddb01c8e4161', '塞外三首 二', '塞外三首 二', '86e135d6-5da2-49b1-afbf-81ea45ee411e', '唐', '["荒壘三秋夕，窮郊萬里平。","海陰凝獨樹，日氣下連營。","戎斾霜旋重，邊裘夜更輕。","將軍猶轉戰，都尉不成名。","折柳悲春曲，吹笳斷夜聲。","明年漢使返，須築受降城。"]', '["荒壘三秋夕，窮郊万里平。","海陰凝独樹，日氣下連營。","戎斾霜旋重，邊裘夜更轻。","將軍猶轉戰，都尉不成名。","折柳悲春曲，吹笳斷夜声。","明年漢使返，須築受降城。"]', '诗', 'shi', '', NULL, '塞外三首 二 鄭愔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d4726a5-ff78-4354-986f-a7d08e3541bb', '塞外三首 三', '塞外三首 三', '86e135d6-5da2-49b1-afbf-81ea45ee411e', '唐', '["陽鳥南飛夜，陰山北地寒。","漢家征戍客，年歲在樓蘭。","玉塞朔風起，金河秋月團。","邊聲入鼓吹，霜氣下旌竿。","海外歸書斷，天涯旅鬢殘。","子卿猶奉使，常向節旄看。"]', '["陽鸟南飞夜，陰山北地寒。","漢家征戍客，年歲在楼蘭。","玉塞朔风起，金河秋月團。","邊声入鼓吹，霜氣下旌竿。","海外归书斷，天涯旅鬢殘。","子卿猶奉使，常向節旄看。"]', '诗', 'shi', '', NULL, '塞外三首 三 鄭愔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de56b324-ae5c-4da5-a3d0-5a83a12ce7d5', '春怨', '春怨', '86e135d6-5da2-49b1-afbf-81ea45ee411e', '唐', '["春朝物候妍，愁婦鏡臺前。","風吹數蝶亂，露洗百花鮮。","試出褰羅幌，還來著錦筵。","曲中愁夜夜，樓上別年年。","不及隨蕭史，高飛向紫煙。"]', '["春朝物候妍，愁婦镜台前。","风吹數蝶亂，露洗百花鲜。","試出褰羅幌，還来著錦筵。","曲中愁夜夜，楼上別年年。","不及隨蕭史，高飞向紫煙。"]', '诗', 'shi', '', NULL, '春怨 鄭愔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49414dd2-2059-49c2-9852-771dde011ca2', '貶降至汝州廣城驛', '貶降至汝州廣城驛', '86e135d6-5da2-49b1-afbf-81ea45ee411e', '唐', '["近郊憑汝海，遐服指江干。","尚憶趨朝貴，方知失路難。","曙宮平樂遠，秋澤廣城寒。","岸葦新花白，山梨晚葉丹。","鄉關千里暮，歲序四時闌。","函塞雲間別，旋門霧裏看。","夙年追騄驥，暮節仰鵷鸞。","疲駑勞垂耳，騫騰詎矯翰。","將調梅鉉實，不正李園冠。","荆玉終無玷，隨珠忽已彈。","曉裝違鞏洛，夕夢在長安。","北上頻傷阮，西征未學潘。","傾車無共轍，同派有殊瀾。","去去懷知己，何由報一餐。"]', '["近郊憑汝海，遐服指江干。","尚憶趨朝貴，方知失路难。","曙宮平乐远，秋澤廣城寒。","岸葦新花白，山梨晚葉丹。","乡关千里暮，歲序四时闌。","函塞云间別，旋门霧裏看。","夙年追騄驥，暮節仰鵷鸾。","疲駑勞垂耳，騫腾詎矯翰。","將調梅鉉實，不正李园冠。","荆玉終無玷，隨珠忽已彈。","晓裝違鞏洛，夕梦在长安。","北上頻傷阮，西征未学潘。","傾车無共轍，同派有殊瀾。","去去懷知己，何由報一餐。"]', '诗', 'shi', '', NULL, '貶降至汝州廣城驛 鄭愔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01c3c86a-f92b-4ec3-93e5-5251f52137c3', '哭郎著作', '哭郎著作', '86e135d6-5da2-49b1-afbf-81ea45ee411e', '唐', '["詩禮康成學，文章賈誼才。","巳年人得夢，庚日鳥爲災。","書草藏天閣，琴聲入夜臺。","荒階羅駁蘚，虛座網浮埃。","白馬賓徒散，青烏隴隧開。","空憐門下客，懷舊幾遲迴。"]', '["诗禮康成学，文章賈誼才。","巳年人得梦，庚日鸟爲災。","书草藏天閣，琴声入夜台。","荒階羅駁蘚，虛座網浮埃。","白马賓徒散，青烏隴隧开。","空怜门下客，懷旧幾遲迴。"]', '诗', 'shi', '', NULL, '哭郎著作 鄭愔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a499396-f057-4ee3-bb52-07f1677178f1', '詠黃鶯兒', '詠黄鶯兒', '86e135d6-5da2-49b1-afbf-81ea45ee411e', '唐', '["欲囀聲猶澀，將飛羽未調。","高風不借便，何處得遷喬。"]', '["欲囀声猶澀，將飞羽未調。","高风不借便，何处得遷喬。"]', '诗', 'shi', '', NULL, '詠黃鶯兒 鄭愔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d819f0af-85d9-4951-8514-69b9fb3c4d66', '百舌', '百舌', '86e135d6-5da2-49b1-afbf-81ea45ee411e', '唐', '["百舌鳴高樹，弄音無常則。","借問聲何煩，末俗不尚默。"]', '["百舌鳴高樹，弄音無常則。","借问声何煩，末俗不尚默。"]', '诗', 'shi', '', NULL, '百舌 鄭愔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9474b09d-81ac-4734-82e5-2a5afcb30152', '奉和聖製送張說上集賢學士賜宴', '奉和聖製送張说上集賢学士賜宴', '9d405c6f-8159-4ffc-8f85-ed79284c56a5', '唐', '["盛業光書府，徵人盡國英。","絲綸賢得相，羣俊學爲名。","寵命垂天錫，崇恩發睿情。","熏風清禁籞，文殿述皇明。","日霽庭陰出，池曛水氣生。","歡娛此無限，詩酒自相迎。"]', '["盛業光书府，徵人尽国英。","絲綸賢得相，羣俊学爲名。","寵命垂天錫，崇恩發睿情。","熏风清禁籞，文殿述皇明。","日霽庭陰出，池曛水氣生。","歡娛此無限，诗酒自相迎。"]', '诗', 'shi', '', NULL, '奉和聖製送張說上集賢學士賜宴 源乾曜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30873668-ceda-45c4-b3cd-7a48303bea39', '奉和御製乾曜與張說宋璟同日上官命宴都堂賜詩', '奉和御製乾曜與張说宋璟同日上官命宴都堂賜诗', '9d405c6f-8159-4ffc-8f85-ed79284c56a5', '唐', '["睿作超千古，湛恩育萬人。","遞遷俱荷澤，同拜忽爲鄰。","道合徽音暢，芳辰景命新。","鼓鐘崇享禮，鵷鷺集朝倫。","竊位思官謗，凋容謝木春。","慙多無以敘，拙備實難陳。","進綬懷三少，承光盡百身。","自當歸第日，何幸列宮臣。"]', '["睿作超千古，湛恩育万人。","遞遷俱荷澤，同拜忽爲鄰。","道合徽音暢，芳辰景命新。","鼓鐘崇享禮，鵷鷺集朝倫。","竊位思官謗，凋容謝木春。","慙多無以敘，拙備實难陳。","進綬懷三少，承光尽百身。","自當归第日，何幸列宮臣。"]', '诗', 'shi', '', NULL, '奉和御製乾曜與張說宋璟同日上官命宴都堂賜詩 源乾曜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2e49f26-7311-4e3e-8dbc-6dacb8baf4cb', '奉和聖製送張尚書巡邊', '奉和聖製送張尚书巡邊', '9d405c6f-8159-4ffc-8f85-ed79284c56a5', '唐', '["匈奴邇河朔，漢地須戎旅。","天子擇英才，朝端出監撫。","流星下閶闔，寶鉞專公輔。","禮物生光輝，宸章備恩詡。","有征視矛戟，制勝唯樽俎。","彼美何壯哉，桓桓擅斯舉。","聲華振臺閣，功德標文武。","奉國知命輕，忘家以身許。","安人在勤恤，保大殫襟俯。","此外無異言，同情報明主。"]', '["匈奴邇河朔，漢地須戎旅。","天子擇英才，朝端出監撫。","流星下閶闔，寶鉞專公輔。","禮物生光輝，宸章備恩詡。","有征視矛戟，制勝唯樽俎。","彼美何壯哉，桓桓擅斯舉。","声华振台閣，功德標文武。","奉国知命轻，忘家以身許。","安人在勤恤，保大殫襟俯。","此外無異言，同情報明主。"]', '诗', 'shi', '', NULL, '奉和聖製送張尚書巡邊 源乾曜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2caf55bd-0b7a-475d-bfb6-d415d09bf010', '禪社首樂章', '禪社首乐章', '9d405c6f-8159-4ffc-8f85-ed79284c56a5', '唐', '["靈具醉，杳熙熙。","靈將往，眇禗禗。","願明德，吐正詞。","爛遺光，流禎祺。"]', '["靈具醉，杳熙熙。","靈將往，眇禗禗。","願明德，吐正词。","爛遺光，流禎祺。"]', '诗', 'shi', '', NULL, '禪社首樂章 源乾曜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8448c1b4-de72-4f28-8380-5f7ec03343aa', '奉和聖製送張說赴集賢院學士賜宴賦得虛字', '奉和聖製送張说赴集賢院学士賜宴賦得虛字', 'ec72e864-2de4-43d6-bcca-d90c758c4325', '唐', '["崇文德化洽，新殿集賢初。","庸菲參高選，首濫承明廬。","殊私光輔弼，榮送列簪裾。","座引中廚饌，杯錫上尊餘。","翠葉濃丹苑，晴空卷碧虛。","忝同文史地，願草登封書。"]', '["崇文德化洽，新殿集賢初。","庸菲參高選，首濫承明廬。","殊私光輔弼，榮送列簪裾。","座引中廚饌，杯錫上尊餘。","翠葉濃丹苑，晴空卷碧虛。","忝同文史地，願草登封书。"]', '诗', 'shi', '', NULL, '奉和聖製送張說赴集賢院學士賜宴賦得虛字 徐堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1e5c890-7ac5-4d56-a827-7a0f53a8423c', '奉和聖製送張說巡邊', '奉和聖製送張说巡邊', 'ec72e864-2de4-43d6-bcca-d90c758c4325', '唐', '["至德撫遐荒，神兵赴朔方。","帝思元帥重，爰擇股肱良。","累相承安世，深籌協子房。","寄崇專斧鉞，禮備設壇場。","鼙鼓喧雷電，戈劒凜風霜。","四騑將戒道，十乘啓先行。","聖錫加恆數，天文耀寵光。","出郊開帳飲，寅餞盛離章。","雨濯梅林潤，風清麥野涼。","燕山應勒頌，麟閣佇名揚。"]', '["至德撫遐荒，神兵赴朔方。","帝思元帥重，爰擇股肱良。","累相承安世，深籌協子房。","寄崇專斧鉞，禮備設壇場。","鼙鼓喧雷電，戈劒凜风霜。","四騑將戒道，十乘啓先行。","聖錫加恆數，天文耀寵光。","出郊开帳饮，寅餞盛離章。","雨濯梅林潤，风清麦野涼。","燕山應勒頌，麟閣佇名揚。"]', '诗', 'shi', '', NULL, '奉和聖製送張說巡邊 徐堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bba12cb-1ae4-41a5-9703-c386c8886cee', '奉和送金城公主適西蕃應制', '奉和送金城公主適西蕃應制', 'ec72e864-2de4-43d6-bcca-d90c758c4325', '唐', '["星漢下天孫，車服降殊蕃。","匣中詞易切，馬上曲虛繁。","關塞移朱帳，風塵暗錦軒。","簫聲去日遠，萬里望河源。"]', '["星漢下天孫，车服降殊蕃。","匣中词易切，马上曲虛繁。","关塞移朱帳，风塵暗錦軒。","簫声去日远，万里望河源。"]', '诗', 'shi', '', NULL, '奉和送金城公主適西蕃應制 徐堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb7d5cc0-b4b6-49fa-95d0-a9d67836aa5b', '餞許州宋司馬赴任', '餞許州宋司马赴任', 'ec72e864-2de4-43d6-bcca-d90c758c4325', '唐', '["舊許星車轉，神京祖帳開。","斷煙傷別望，零雨送離杯。","辭燕依空遶，賓鴻入聽哀。","分襟與秋氣，日夕共悲哉。"]', '["旧許星车轉，神京祖帳开。","斷煙傷別望，零雨送離杯。","辞燕依空遶，賓鴻入听哀。","分襟與秋氣，日夕共悲哉。"]', '诗', 'shi', '', NULL, '餞許州宋司馬赴任 徐堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a9c7cf3-39a4-48f7-8636-27915ed0004e', '餞唐永昌', '餞唐永昌', 'ec72e864-2de4-43d6-bcca-d90c758c4325', '唐', '["郎官出宰赴伊瀍，征傳駸駸灞水前。","此時悵望新豐道，握手相看共黯然。"]', '["郎官出宰赴伊瀍，征傳駸駸灞水前。","此时悵望新豐道，握手相看共黯然。"]', '诗', 'shi', '', NULL, '餞唐永昌 徐堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d8e345e-97e3-452c-8771-b5409d20dbae', '送考功武員外學士使嵩山置舍利塔歌', '送考功武員外学士使嵩山置舍利塔歌', 'ec72e864-2de4-43d6-bcca-d90c758c4325', '唐', '["伊川別騎，灞岸分筵。","對三春之花月，覽千里之風煙。","望青山兮分地，見白雲兮在天。","寄愁心於樽酒，愴離緒於清弦。","共握手而相顧，各銜悽而黯然。"]', '["伊川別騎，灞岸分筵。","对三春之花月，覽千里之风煙。","望青山兮分地，见白云兮在天。","寄愁心於樽酒，愴離緒於清弦。","共握手而相顧，各銜悽而黯然。"]', '诗', 'shi', '', NULL, '送考功武員外學士使嵩山置舍利塔歌 徐堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('605462fe-3bcc-4503-a9ef-22ae16636dd2', '櫂歌行', '櫂歌行', 'ec72e864-2de4-43d6-bcca-d90c758c4325', '唐', '["櫂女飾銀鉤，新妝下翠樓。","霜絲青桂檝，蘭栧紫霞舟。","水落金陵曙，風起洞庭秋。","扣舷過曲浦，飛帆越回流。","影入桃花浪，香飄杜若洲。","洲長殊未返，蕭散雲霞晚。","日下大江平，煙生歸岸遠。","岸遠聞潮波，爭途遊戲多。","因聲趙津女，來聽採菱歌。"]', '["櫂女飾銀鉤，新妝下翠楼。","霜絲青桂檝，蘭栧紫霞舟。","水落金陵曙，风起洞庭秋。","扣舷過曲浦，飞帆越回流。","影入桃花浪，香飄杜若洲。","洲长殊未返，蕭散云霞晚。","日下大江平，煙生归岸远。","岸远闻潮波，爭途游戲多。","因声趙津女，来听採菱歌。"]', '诗', 'shi', '', NULL, '櫂歌行 徐堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55d63d1d-9f85-40fc-9933-42120e54757d', '送武進鄭明府', '送武進鄭明府', 'ec72e864-2de4-43d6-bcca-d90c758c4325', '唐', '["絃歌試宰日，城闕賞心違。","北謝蒼龍去，南隨黃鵠飛。","夏雲海中出，吳山江上微。","甿謠豈云遠，從此慶緇衣。"]', '["絃歌試宰日，城闕賞心違。","北謝蒼龙去，南隨黄鵠飞。","夏云海中出，吳山江上微。","甿謠豈云远，從此慶緇衣。"]', '诗', 'shi', '', NULL, '送武進鄭明府 徐堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da39b136-8fb0-493e-a1a5-4223bca03afc', '儀坤廟樂章', '儀坤廟乐章', 'ec72e864-2de4-43d6-bcca-d90c758c4325', '唐', '["於穆清廟，肅雍嚴祀。","合福受釐，介以繁祉。"]', '["於穆清廟，肅雍嚴祀。","合福受釐，介以繁祉。"]', '诗', 'shi', '', NULL, '儀坤廟樂章 徐堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2ee20f6-53b2-4743-836e-518ab9abe749', '祭汾陰樂章', '祭汾陰乐章', 'ea8de934-8013-48e1-a3a9-c819b39d3769', '唐', '["方丘既膳，嘉饗載謐。","齋敬畢誠，陶匏貴質。","秀畢豐薦，芳俎盈實。","永永福流，其升如日。"]', '["方丘既膳，嘉饗載謐。","斋敬畢誠，陶匏貴質。","秀畢豐薦，芳俎盈實。","永永福流，其升如日。"]', '诗', 'shi', '', NULL, '祭汾陰樂章 源光裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96575e78-6563-4419-8738-89a08b43f83f', '奉和聖製送張說上集賢學士賜宴', '奉和聖製送張说上集賢学士賜宴', '7c1a6d26-fd4a-4470-a50a-f2fd295b1c4e', '唐', '["碩儒延鳳沼，金馬被鴻私。","饌玉趨丹禁，牋花降紫墀。","銜恩傾旨酒，鼓舞詠康時。","暫覯羣書緝，逾昭盛業丕。","接筵欣有命，搦管媿無詞。","自驚一何幸，太陽還及葵。"]', '["碩儒延鳳沼，金马被鴻私。","饌玉趨丹禁，牋花降紫墀。","銜恩傾旨酒，鼓舞詠康时。","暫覯羣书緝，逾昭盛業丕。","接筵欣有命，搦管媿無词。","自驚一何幸，太陽還及葵。"]', '诗', 'shi', '', NULL, '奉和聖製送張說上集賢學士賜宴 李元紘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10c1ed8b-a04a-4842-991e-2cf9b13209be', '綠墀怨', '綠墀怨', '7c1a6d26-fd4a-4470-a50a-f2fd295b1c4e', '唐', '["征馬噪金珂，嫖姚向北河。","綠苔行跡少，紅粉淚痕多。","寶屋粘花絮，銀箏覆網羅。","別君如昨日，青海雁頻過。"]', '["征马噪金珂，嫖姚向北河。","綠苔行跡少，紅粉泪痕多。","寶屋粘花絮，銀箏覆網羅。","別君如昨日，青海雁頻過。"]', '诗', 'shi', '', NULL, '綠墀怨 李元紘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('124122ce-045f-48ca-808e-3dc8775246a8', '相思怨', '相思怨', '7c1a6d26-fd4a-4470-a50a-f2fd295b1c4e', '唐', '["望月思氛氳，朱衾嬾更熏。","春生翡翠帳，花點石榴裠。","燕語時驚妾，鶯啼轉憶君。","交河一萬里，仍隔數重雲。"]', '["望月思氛氳，朱衾嬾更熏。","春生翡翠帳，花点石榴裠。","燕語时驚妾，鶯啼轉憶君。","交河一万里，仍隔數重云。"]', '诗', 'shi', '', NULL, '相思怨 李元紘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92f7144c-b226-40e5-a28b-ae7789ab8c0c', '奉和聖製送張說上集賢學士賜宴', '奉和聖製送張说上集賢学士賜宴', 'bd515213-db07-4069-bf0b-72c72a7d6cba', '唐', '["問道圖書盛，尊儒禮教興。","石渠因學廣，金殿爲賢昇。","日月恩光照，風雲寵命膺。","謀謨言可範，舟檝事斯憑。","宴喜明時洽，光輝湛露凝。","大哉堯作主，天下頌歌稱。"]', '["问道圖书盛，尊儒禮教兴。","石渠因学廣，金殿爲賢昇。","日月恩光照，风云寵命膺。","謀謨言可範，舟檝事斯憑。","宴喜明时洽，光輝湛露凝。","大哉堯作主，天下頌歌稱。"]', '诗', 'shi', '', NULL, '奉和聖製送張說上集賢學士賜宴 裴漼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8999600e-5b3f-44a0-9c15-a8b309a2f3c0', '奉和御製旋師喜捷', '奉和御製旋師喜捷', 'bd515213-db07-4069-bf0b-72c72a7d6cba', '唐', '["殊類驕無長，王師示有征。","中軍纔受律，妖寇已亡精。","斬虜還遮塞，綏降更築城。","從來攻必克，天策振奇兵。"]', '["殊類驕無长，王師示有征。","中軍纔受律，妖寇已亡精。","斬虜還遮塞，綏降更築城。","從来攻必克，天策振奇兵。"]', '诗', 'shi', '', NULL, '奉和御製旋師喜捷 裴漼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4391aa73-8756-404c-937f-e99263585e26', '奉和御製平胡', '奉和御製平胡', 'bd515213-db07-4069-bf0b-72c72a7d6cba', '唐', '["玄漠聖恩通，由來書軌同。","忽聞窺月滿，相聚寇雲中。","廟略占黃氣，神兵出絳宮。","將軍行逐虜，使者亦和戎。","一舉轒輼滅，再麾沙漠空。","直將威禁暴，非用武爲雄。","飲至明軍禮，醻勳錫武功。","干戈還載戢，文德在唐風。"]', '["玄漠聖恩通，由来书軌同。","忽闻窺月满，相聚寇云中。","廟略占黄氣，神兵出絳宮。","將軍行逐虜，使者亦和戎。","一舉轒輼滅，再麾沙漠空。","直將威禁暴，非用武爲雄。","饮至明軍禮，醻勳錫武功。","干戈還載戢，文德在唐风。"]', '诗', 'shi', '', NULL, '奉和御製平胡 裴漼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee5bd665-80a6-43ef-b098-dc72dd829139', '奉和聖製龍池篇', '奉和聖製龙池篇', 'bd515213-db07-4069-bf0b-72c72a7d6cba', '唐', '["乾坤啓聖吐龍泉，泉水年年勝一年。","始看魚躍方成海，即覩飛龍利在天。","洲渚遙將銀漢接，樓臺直與紫微連。","休氣榮光恆不散，懸知此地是神仙。"]', '["乾坤啓聖吐龙泉，泉水年年勝一年。","始看鱼躍方成海，即覩飞龙利在天。","洲渚遙將銀漢接，楼台直與紫微連。","休氣榮光恆不散，懸知此地是神仙。"]', '诗', 'shi', '', NULL, '奉和聖製龍池篇 裴漼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4595908c-a166-442c-ac0a-afee0f0defdd', '奉和聖製送張說上集賢學士賜宴', '奉和聖製送張说上集賢学士賜宴', '42ef1263-e991-4160-b296-d4b709d490fe', '唐', '["圖書應明主，策府宴嘉賓。","台曜臨東壁，乾光自北辰。","網羅窮象繫，述作究天人。","聖酒千鍾洽，仙廚百味陳。","成山徒可仰，涉海詎知津。","幸逢文教盛，還覩頌聲新。"]', '["圖书應明主，策府宴嘉賓。","台曜臨东壁，乾光自北辰。","網羅窮象繫，述作究天人。","聖酒千鍾洽，仙廚百味陳。","成山徒可仰，涉海詎知津。","幸逢文教盛，還覩頌声新。"]', '诗', 'shi', '', NULL, '奉和聖製送張說上集賢學士賜宴 劉昇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d53059c-8668-4c0d-a0cb-5bcbe08248de', '奉和聖製送張說上集賢學士賜宴', '奉和聖製送張说上集賢学士賜宴', 'b65b7f7c-ebec-4ccb-997b-bcd40e59bc45', '唐', '["帝曰簡才能，旌賢在股肱。","文章體一變，禮樂道逾弘。","芸閣英華入，賓門鵷鷺登。","恩筵過所望，聖澤實超恆。","夏葉開紅藥，餘花發紫藤。","微臣亦何幸，叨此預文朋。"]', '["帝曰簡才能，旌賢在股肱。","文章體一变，禮乐道逾弘。","芸閣英华入，賓门鵷鷺登。","恩筵過所望，聖澤實超恆。","夏葉开紅藥，餘花發紫藤。","微臣亦何幸，叨此預文朋。"]', '诗', 'shi', '', NULL, '奉和聖製送張說上集賢學士賜宴 蕭嵩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a48b1b7-3c37-4c8a-9a7e-faa8df549996', '奉和御製左丞相說右丞相璟太子少傅乾曜同日上官命宴都堂賜詩', '奉和御製左丞相说右丞相璟太子少傅乾曜同日上官命宴都堂賜诗', 'b65b7f7c-ebec-4ccb-997b-bcd40e59bc45', '唐', '["審官思共理，多士屬惟唐。","歷選台庭舊，來熙帝業昌。","入朝師百辟，論道協三光。","垂拱咨元老，親賢輔少陽。","登庸崇禮送，寵德耀宸章。","御酒飛觴洽，仙闈雅樂張。","荷恩思有報，陳力媿無良。","願罄公忠節，同心奉我皇。"]', '["審官思共理，多士屬惟唐。","歷選台庭旧，来熙帝業昌。","入朝師百辟，論道協三光。","垂拱咨元老，親賢輔少陽。","登庸崇禮送，寵德耀宸章。","御酒飞觴洽，仙闈雅乐張。","荷恩思有報，陳力媿無良。","願罄公忠節，同心奉我皇。"]', '诗', 'shi', '', NULL, '奉和御製左丞相說右丞相璟太子少傅乾曜同日上官命宴都堂賜詩 蕭嵩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5071e7f-1a10-4fba-9b62-3279fecfdcd1', '奉和聖製送張說上集賢學士賜宴', '奉和聖製送張说上集賢学士賜宴', '06356582-aa31-44c0-aa10-1e323263c925', '唐', '["廣庭臨璧沼，多士侍金閨。","英宰文儒叶，明君日月齊。","集賢光首拜，改殿發新題。","早夏初移律，餘花尚拂溪。","壺觴接雲上，經術引關西。","聖德鴻名遠，將陪玉檢泥。"]', '["廣庭臨璧沼，多士侍金閨。","英宰文儒叶，明君日月齊。","集賢光首拜，改殿發新題。","早夏初移律，餘花尚拂溪。","壺觴接云上，經術引关西。","聖德鴻名远，將陪玉檢泥。"]', '诗', 'shi', '', NULL, '奉和聖製送張說上集賢學士賜宴 韋抗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c5b6a30-130d-4f9a-9e85-c3e5bc9522be', '奉和聖製送張說上集賢學士賜宴', '奉和聖製送張说上集賢学士賜宴', 'ebd2868a-aadd-44f2-af5e-141a99ec4b48', '唐', '["偃武堯風接，崇文漢道恢。","集賢更內殿，清選自中台。","佐命留侯業，詞華博物才。","天廚千品降，御酒百壺催。","鵷鷺方成列，神仙喜暫陪。","復欣同拜首，叨此頌良哉。"]', '["偃武堯风接，崇文漢道恢。","集賢更內殿，清選自中台。","佐命留侯業，词华博物才。","天廚千品降，御酒百壺催。","鵷鷺方成列，神仙喜暫陪。","复欣同拜首，叨此頌良哉。"]', '诗', 'shi', '', NULL, '奉和聖製送張說上集賢學士賜宴 李暠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b115a49-2dcc-445a-96c2-4e9129d8a72f', '奉和聖製送張說上集賢學士賜宴', '奉和聖製送張说上集賢学士賜宴', 'b8a5479a-4ee8-4d5d-bcb8-ebe86adb295f', '唐', '["修文中禁啓，改字令名加。","台座徵人傑，書坊應國華。","賦詩開廣宴，賜酒酌流霞。","雲散明金闕，池開照玉沙。","掖垣留宿鳥，溫樹落餘花。","謬此天光及，銜恩醉日斜。"]', '["修文中禁啓，改字令名加。","台座徵人傑，书坊應国华。","賦诗开廣宴，賜酒酌流霞。","云散明金闕，池开照玉沙。","掖垣留宿鸟，溫樹落餘花。","謬此天光及，銜恩醉日斜。"]', '诗', 'shi', '', NULL, '奉和聖製送張說上集賢學士賜宴 韋述 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13cbd4e0-e3f8-41a9-bf75-39f175bf6c34', '晚渡伊水', '晚渡伊水', 'b8a5479a-4ee8-4d5d-bcb8-ebe86adb295f', '唐', '["悠悠涉伊水，伊水清見石。","是時春向深，兩岸草如積。","迢遰望洲嶼，逶迤亙津陌。","新樹落疎紅，遙原上深碧。","回瞻洛陽苑，遽有長山隔。","煙霧猶辨家，風塵已爲客。","登陟多異趣，往來見行役。","雲起早已昏，鳥飛日將夕。","光陰逝不借，超然慕疇昔。","遠游亦何爲？歸來存竹帛。"]', '["悠悠涉伊水，伊水清见石。","是时春向深，兩岸草如積。","迢遰望洲嶼，逶迤亙津陌。","新樹落疎紅，遙原上深碧。","回瞻洛陽苑，遽有长山隔。","煙霧猶辨家，风塵已爲客。","登陟多異趣，往来见行役。","云起早已昏，鸟飞日將夕。","光陰逝不借，超然慕疇昔。","远游亦何爲？归来存竹帛。"]', '诗', 'shi', '', NULL, '晚渡伊水 韋述 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b88ea4a-692e-4d91-9bc3-c6e89d65d6ca', '春日山莊', '春日山莊', 'b8a5479a-4ee8-4d5d-bcb8-ebe86adb295f', '唐', '["初歲開韶月，田家喜載陽。","晚晴搖水態，遲景蕩山光。","浦淨漁舟遠，花飛樵路香。","自然成野趣，都使俗情忘。"]', '["初歲开韶月，田家喜載陽。","晚晴搖水態，遲景蕩山光。","浦淨漁舟远，花飞樵路香。","自然成野趣，都使俗情忘。"]', '诗', 'shi', '', NULL, '春日山莊 韋述 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90f239b1-7810-42cb-a91a-6aff697f6696', '廣陵送別宋員外佐越鄭舍人還京', '廣陵送別宋員外佐越鄭舍人還京', 'b8a5479a-4ee8-4d5d-bcb8-ebe86adb295f', '唐', '["朱紱臨秦望，皇華赴洛橋。","文章南渡越，書奏北歸朝。","樹入江雲盡，城銜海月遙。","秋風將客思，川上晚蕭蕭。"]', '["朱紱臨秦望，皇华赴洛橋。","文章南渡越，书奏北归朝。","樹入江云尽，城銜海月遙。","秋风將客思，川上晚蕭蕭。"]', '诗', 'shi', '', NULL, '廣陵送別宋員外佐越鄭舍人還京 韋述 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e62bcd28-f094-44e7-89a6-3ada42c24b9e', '奉和聖製送張說上集賢學士賜宴', '奉和聖製送張说上集賢学士賜宴', '1f45fe51-fc3f-4caa-8fa7-d7ac64e2103f', '唐', '["聖主崇文教，層霄降德音。","尊賢澤既厚，式宴寵逾深。","復有夔龍相，良哉簡帝心。","得人惟邁昔，多士諒推今。","書殿榮光滿，儒門喜氣臨。","顧惟誠濫吹，徒此接衣簪。"]', '["聖主崇文教，層霄降德音。","尊賢澤既厚，式宴寵逾深。","复有夔龙相，良哉簡帝心。","得人惟邁昔，多士諒推今。","书殿榮光满，儒门喜氣臨。","顧惟誠濫吹，徒此接衣簪。"]', '诗', 'shi', '', NULL, '奉和聖製送張說上集賢學士賜宴 陸堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9e4128d-2ed0-4356-917c-ca2e67d4a0bb', '句 千秋節應制', '句 千秋節應制', '1f45fe51-fc3f-4caa-8fa7-d7ac64e2103f', '唐', '["風移覃土宇，雲上浹羣臣。"]', '["风移覃土宇，云上浹羣臣。"]', '诗', 'shi', '', NULL, '句 千秋節應制 陸堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('337e560d-f0eb-489f-8b80-4ecca434391a', '奉和聖製送張說上集賢學士賜宴', '奉和聖製送張说上集賢学士賜宴', '33aa283f-809b-44b1-b3ff-b9f6a1a57527', '唐', '["聖主崇文化，鏘鏘得盛才。","相因歸夢立，殿以集賢開。","象繫微言闡，詩書至道該。","堯尊承帝澤，禹膳自天來。","禮洽歡逾長，風恬暑更迴。","國朝將舜頌，同是一康哉。"]', '["聖主崇文化，鏘鏘得盛才。","相因归梦立，殿以集賢开。","象繫微言闡，诗书至道該。","堯尊承帝澤，禹膳自天来。","禮洽歡逾长，风恬暑更迴。","国朝將舜頌，同是一康哉。"]', '诗', 'shi', '', NULL, '奉和聖製送張說上集賢學士賜宴 程行諶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e9a6235-fc3f-40c9-b123-6d9e5f7560d8', '奉和聖製送張說上集賢學士賜宴', '奉和聖製送張说上集賢学士賜宴', 'db761d18-62f9-4639-bd36-b7c54f2dafc8', '唐', '["講習延東觀，趨陪盛北宮。","惟師恢帝則，敷教叶天工。","宣室恩嘗異，金華禮更崇。","洞門清永日，華綬接微風。","萐降堯廚翠，榴開舜酒紅。","文思光萬宇，高議待升中。"]', '["講習延东观，趨陪盛北宮。","惟師恢帝則，敷教叶天工。","宣室恩嘗異，金华禮更崇。","洞门清永日，华綬接微风。","萐降堯廚翠，榴开舜酒紅。","文思光万宇，高議待升中。"]', '诗', 'shi', '', NULL, '奉和聖製送張說上集賢學士賜宴 褚秀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06fa004f-d3f2-49ec-9721-24c48152cc37', '奉和御製左丞相說右丞相璟太子少傅乾曜同日上官命都堂賜詩', '奉和御製左丞相说右丞相璟太子少傅乾曜同日上官命都堂賜诗', 'b3357a20-8c48-436b-8db5-eedf18836583', '唐', '["樂賢聞往誥，褒德偶茲辰。","端揆升元老，師謀擇累仁。","紫庭崇讓畢，粉署禮容陳。","既荷恩榮舊，俱承寵命新。","天文懸瑞色，聖酒汎華茵。","雜遝喧簫鼓，歡娛洽搢紳。","掖垣招近侍，虛薄[廁]清塵。","共保堅貞節，常期雨露均。"]', '["乐賢闻往誥，褒德偶茲辰。","端揆升元老，師謀擇累仁。","紫庭崇讓畢，粉署禮容陳。","既荷恩榮旧，俱承寵命新。","天文懸瑞色，聖酒汎华茵。","杂遝喧簫鼓，歡娛洽搢紳。","掖垣招近侍，虛薄[廁]清塵。","共保堅貞節，常期雨露均。"]', '诗', 'shi', '', NULL, '奉和御製左丞相說右丞相璟太子少傅乾曜同日上官命都堂賜詩 裴光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82368b5a-e0a0-4758-96d3-09bc84096ca9', '奉和聖製左丞相說右丞相璟太子少傅乾曜同日上官命宴都堂賜詩', '奉和聖製左丞相说右丞相璟太子少傅乾曜同日上官命宴都堂賜诗', 'd9e5d9f8-b4ae-4980-88e8-422a616172c1', '唐', '["申甫生周日，宣慈舉舜年。","何如偶昌運，比德邁前賢。","寵獲元良密，榮瞻端揆遷。","職優三事老，位在百僚先。","北極迴宸渥，南宮飾御筵。","飛文瑤札降，賜酒玉杯傳。","謬列台衡重，俱承雨露偏。","誓將同竭力，相與效塵涓。"]', '["申甫生周日，宣慈舉舜年。","何如偶昌運，比德邁前賢。","寵獲元良密，榮瞻端揆遷。","職優三事老，位在百僚先。","北極迴宸渥，南宮飾御筵。","飞文瑤札降，賜酒玉杯傳。","謬列台衡重，俱承雨露偏。","誓將同竭力，相與效塵涓。"]', '诗', 'shi', '', NULL, '奉和聖製左丞相說右丞相璟太子少傅乾曜同日上官命宴都堂賜詩 宇文融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ce86466-e25b-435e-b4f0-af476ada09cb', '奉和聖製同二相已下羣官樂游園宴', '奉和聖製同二相已下羣官乐游园宴', 'bb81887f-7000-41fd-ab62-16191dccb7bc', '唐', '["五日酺纔畢，千年樂未央。","復承天所賜，終宴國之陽。","地勝春逾好，恩深樂更張。","落花飛廣座，垂柳拂行觴。","庶尹陪三史，諸侯具萬方。","酒酣同抃躍，歌舞詠時康。"]', '["五日酺纔畢，千年乐未央。","复承天所賜，終宴国之陽。","地勝春逾好，恩深乐更張。","落花飞廣座，垂柳拂行觴。","庶尹陪三史，諸侯具万方。","酒酣同抃躍，歌舞詠时康。"]', '诗', 'shi', '', NULL, '奉和聖製同二相已下羣官樂游園宴 崔沔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73fcfbdf-bb02-4490-a7bf-5ed9819a3ac2', '奉和聖製同二相已下羣臣樂游園宴', '奉和聖製同二相已下羣臣乐游园宴', 'e5915362-f833-44f1-a182-6dedc1cb2623', '唐', '["春日照長安，皇恩寵庶官。","合錢承罷宴，賜帛復追歡。","供帳憑高列，城池入迥寬。","花催相國醉，鳥和樂人彈。","北闕雲中見，南山樹杪看。","樂游宜締賞，舞詠惜將闌。"]', '["春日照长安，皇恩寵庶官。","合錢承罷宴，賜帛复追歡。","供帳憑高列，城池入迥寬。","花催相国醉，鸟和乐人彈。","北闕云中见，南山樹杪看。","乐游宜締賞，舞詠惜將闌。"]', '诗', 'shi', '', NULL, '奉和聖製同二相已下羣臣樂游園宴 崔尚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d5936ea-0964-4f20-9aeb-b629964cd727', '奉和聖製同二相以下羣官樂游園宴', '奉和聖製同二相以下羣官乐游园宴', 'd00ba6cc-2267-469b-af31-f00225e83ff3', '唐', '["五酺終宴集，三錫又歡娛。","仙阜崇高異，神州眺覽殊。","南山臨皓雪，北闕對明珠。","廣座鵷鴻滿，昌庭駟馬趨。","綺羅含草樹，絲竹吐郊衢。","銜杯不能罷，歌舞樂唐虞。"]', '["五酺終宴集，三錫又歡娛。","仙阜崇高異，神州眺覽殊。","南山臨皓雪，北闕对明珠。","廣座鵷鴻满，昌庭駟马趨。","綺羅含草樹，絲竹吐郊衢。","銜杯不能罷，歌舞乐唐虞。"]', '诗', 'shi', '', NULL, '奉和聖製同二相以下羣官樂游園宴 胡皓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb0f5fb9-dd8e-45a6-99f1-725eeccee708', '奉和聖製送張尚書巡邊', '奉和聖製送張尚书巡邊', 'd00ba6cc-2267-469b-af31-f00225e83ff3', '唐', '["燕公爲漢將，武德奉文思。","利用經戎莽，英圖叶聖詒。","塞沙制長策，窮石卷搖旗。","萬里要相賀，三邊又在茲。","稜威方逐逐，談笑坐怡怡。","寵餞紛郊道，充廚竭御司。","嘗醪企行邁，聽樂罷漣洏。","衮旒垂翰墨，纓蕤迭賦詩。","金山無積阻，玉樹有華滋。","請迨炎風暮，歸旌候此時。"]', '["燕公爲漢將，武德奉文思。","利用經戎莽，英圖叶聖詒。","塞沙制长策，窮石卷搖旗。","万里要相賀，三邊又在茲。","稜威方逐逐，談笑坐怡怡。","寵餞紛郊道，充廚竭御司。","嘗醪企行邁，听乐罷漣洏。","衮旒垂翰墨，纓蕤迭賦诗。","金山無積阻，玉樹有华滋。","請迨炎风暮，归旌候此时。"]', '诗', 'shi', '', NULL, '奉和聖製送張尚書巡邊 胡皓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0603e48a-3ed6-465a-ab42-6a89e8d198dd', '和宋之問寒食題臨江驛', '和宋之问寒食題臨江驛', 'd00ba6cc-2267-469b-af31-f00225e83ff3', '唐', '["聞道山陰會，仍爲火忌辰。","途中甘棄日，江上苦傷春。","流水飜催淚，寒灰更伴人。","丹心終不改，白髮爲誰新。"]', '["闻道山陰會，仍爲火忌辰。","途中甘棄日，江上苦傷春。","流水飜催泪，寒灰更伴人。","丹心終不改，白髮爲誰新。"]', '诗', 'shi', '', NULL, '和宋之問寒食題臨江驛 胡皓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75d52b0f-5f08-493c-ad13-74e8ca3a2a95', '出峽', '出峽', 'd00ba6cc-2267-469b-af31-f00225e83ff3', '唐', '["巴東三峽盡，曠望九江開。","楚塞雲中出，荆門水上來。","魚龍潛嘯雨，鳧雁動成雷。","南國秋風晚，客思幾悠哉。"]', '["巴东三峽尽，曠望九江开。","楚塞云中出，荆门水上来。","鱼龙潛嘯雨，鳧雁动成雷。","南国秋风晚，客思幾悠哉。"]', '诗', 'shi', '', NULL, '出峽 胡皓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f6f6922-932e-45ff-a88b-48f40d12fa5b', '同蔡孚起居詠鸚鵡', '同蔡孚起居詠鸚鵡', 'd00ba6cc-2267-469b-af31-f00225e83ff3', '唐', '["鸚鵡殊姿致，鸞皇得比肩。","常尋金殿裏，每話玉階前。","賈誼才方達，揚雄老未遷。","能言既有地，何惜爲聞天。"]', '["鸚鵡殊姿致，鸾皇得比肩。","常尋金殿裏，每話玉階前。","賈誼才方達，揚雄老未遷。","能言既有地，何惜爲闻天。"]', '诗', 'shi', '', NULL, '同蔡孚起居詠鸚鵡 胡皓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9fabab9-0c8d-42d4-bed2-1cb0ffd1305c', '大漠行', '大漠行', 'd00ba6cc-2267-469b-af31-f00225e83ff3', '唐', '["單于犯薊堧，虜騎略蕭邊。","南山木葉飛下地，北海蓬根亂上天。","科斗連營太原道，魚麗合陣武威川。","三軍遙倚伏，萬里相馳逐。","旌斾悠悠靜潮源，鼙鼓喧喧動盧谷。","窮徼出幽陵，吁嗟倦寢興。","馬蹄凍溜石，胡毳煖生冰。","雲沙泱漭天光閉，河塞陰沈海色凝。","崆峒北國誰能託，蕭索邊心常不樂。","近見行人畏白龍，遙聞公主愁黃鶴。","陽春半，岐路間，瑤臺苑，玉門關。","百花芳樹紅將歇，二月蘭臯綠未還。","陣雲不散魚龍水，雨雪猶飛鴻鵠山。","山嶂緜連那可極，路遠辛勤夢顏色。","北堂萱草不寄來，東園桃李長相憶。","漢將紛紜攻戰盈，胡寇蕭條幽朔清。","韓昌拜節偏知送，鄭吉驅旌坐見迎。","火絕煙沈左西極，谷靜山空右北平。","但得將軍能百勝，不須天子築長城。"]', '["單于犯薊堧，虜騎略蕭邊。","南山木葉飞下地，北海蓬根亂上天。","科斗連營太原道，鱼丽合陣武威川。","三軍遙倚伏，万里相驰逐。","旌斾悠悠静潮源，鼙鼓喧喧动盧谷。","窮徼出幽陵，吁嗟倦寢兴。","马蹄凍溜石，胡毳煖生冰。","云沙泱漭天光閉，河塞陰沈海色凝。","崆峒北国誰能託，蕭索邊心常不乐。","近见行人畏白龙，遙闻公主愁黄鹤。","陽春半，岐路间，瑤台苑，玉门关。","百花芳樹紅將歇，二月蘭臯綠未還。","陣云不散鱼龙水，雨雪猶飞鴻鵠山。","山嶂緜連那可極，路远辛勤梦顏色。","北堂萱草不寄来，东园桃李长相憶。","漢將紛紜攻戰盈，胡寇蕭條幽朔清。","韓昌拜節偏知送，鄭吉驱旌坐见迎。","火絕煙沈左西極，谷静山空右北平。","但得將軍能百勝，不須天子築长城。"]', '诗', 'shi', '', NULL, '大漠行 胡皓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('850a485d-6f69-44ea-96bf-a507f8aa1fbb', '朝退', '朝退', '7d9a3246-dbbb-4c6f-8d99-ea53bf87cd40', '唐', '["朱門長不閉，親友恣相過。","年今將半百，不樂復如何。"]', '["朱门长不閉，親友恣相過。","年今將半百，不乐复如何。"]', '诗', 'shi', '', NULL, '朝退 李適之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cc2e99a-ef51-4c6c-a86c-beb89f8c9b81', '罷相作', '罷相作', '7d9a3246-dbbb-4c6f-8d99-ea53bf87cd40', '唐', '["避賢初罷相，樂聖且銜杯。","爲問門前客，今朝幾箇來。"]', '["避賢初罷相，乐聖且銜杯。","爲问门前客，今朝幾箇来。"]', '诗', 'shi', '', NULL, '罷相作 李適之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14631ff0-8fb9-4d70-b3d7-ca2d31eaecba', '題漢州西湖', '題漢州西湖', '8ad6b322-9358-4974-8f5a-ac71fc345837', '唐', '["高流纏峻隅，城下緬丘墟。","決渠信浩蕩，潭島成江湖。","結宇依迴渚，水中信可居。","三伏氣不蒸，四達暑自徂。","同人千里駕，鄰國五馬車。","月出共登舟，風生隨所如。","舉麾指極浦，欲極更盤紆。","繚繞各殊致，夜盡情有餘。","遭亂意不開，即理還暫祛。","安得長晤語，使我憂更除。"]', '["高流纏峻隅，城下緬丘墟。","決渠信浩蕩，潭島成江湖。","結宇依迴渚，水中信可居。","三伏氣不蒸，四達暑自徂。","同人千里駕，鄰国五马车。","月出共登舟，风生隨所如。","舉麾指極浦，欲極更盤紆。","繚繞各殊致，夜尽情有餘。","遭亂意不开，即理還暫祛。","安得长晤語，使我憂更除。"]', '诗', 'shi', '', NULL, '題漢州西湖 房琯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('126eccee-4aa4-47d4-b207-0d3c36a7ec51', '詠方圓動靜', '詠方圓动静', '43d47387-1ee6-4533-8ef9-68284e4e68fb', '唐', '["方如行義，圓如用智。","動如逞才，靜如遂意。"]', '["方如行義，圓如用智。","动如逞才，静如遂意。"]', '诗', 'shi', '', NULL, '詠方圓動靜 李泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a85c8e21-b706-4511-aaa4-39447568a11b', '長歌行', '长歌行', '43d47387-1ee6-4533-8ef9-68284e4e68fb', '唐', '["天覆吾，地載吾，天地生吾有意無。","不然絕粒昇天衢，不然鳴珂遊帝都。","焉能不貴復不去，空作昂藏一丈夫。","一丈夫兮一丈夫，千生氣志是良圖。","請君看取百年事，業就扁舟泛五湖。"]', '["天覆吾，地載吾，天地生吾有意無。","不然絕粒昇天衢，不然鳴珂游帝都。","焉能不貴复不去，空作昂藏一丈夫。","一丈夫兮一丈夫，千生氣志是良圖。","請君看取百年事，業就扁舟泛五湖。"]', '诗', 'shi', '', NULL, '長歌行 李泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b7402d5-8836-4962-9e46-ce0d04fa3c53', '奉和聖製中和節曲江宴百僚', '奉和聖製中和節曲江宴百僚', '43d47387-1ee6-4533-8ef9-68284e4e68fb', '唐', '["風俗時有變，中和節惟新。","軒車雙闕下，宴會曲江濱。","金石何鏗鏘，簪纓亦紛綸。","皇恩降自天，品物感知春。","慈恩匝寰瀛，歌詠同君臣。"]', '["风俗时有变，中和節惟新。","軒车雙闕下，宴會曲江濱。","金石何鏗鏘，簪纓亦紛綸。","皇恩降自天，品物感知春。","慈恩匝寰瀛，歌詠同君臣。"]', '诗', 'shi', '', NULL, '奉和聖製中和節曲江宴百僚 李泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ee1065e-adba-4eda-bec9-2b69c95bab2c', '奉和聖製重陽賜會聊示所懷', '奉和聖製重陽賜會聊示所懷', '43d47387-1ee6-4533-8ef9-68284e4e68fb', '唐', '["大唐造昌運，品物荷時成。","乘秋逢令節，錫宴歡羣情。","俯臨秦山川，高會漢公卿。","未追赤松子，且泛黃菊英。","賡歌聖人作，海內同休明。"]', '["大唐造昌運，品物荷时成。","乘秋逢令節，錫宴歡羣情。","俯臨秦山川，高會漢公卿。","未追赤松子，且泛黄菊英。","賡歌聖人作，海內同休明。"]', '诗', 'shi', '', NULL, '奉和聖製重陽賜會聊示所懷 李泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('733cf267-5516-4f52-8110-518c913fe478', '句', '句', '43d47387-1ee6-4533-8ef9-68284e4e68fb', '唐', '["青青東門柳，歲晏復憔悴。","良弓摧折久，誰識是龍韜。","旋沫翻成碧玉池，添酥散出琉璃眼。"]', '["青青东门柳，歲晏复憔悴。","良弓摧折久，誰識是龙韜。","旋沫翻成碧玉池，添酥散出琉璃眼。"]', '诗', 'shi', '', NULL, '句 李泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79a24c06-2170-401e-ab36-9e7760b2b2a5', '享太廟樂章 廣運舞', '享太廟乐章 廣運舞', '9964896f-2064-49e0-bca2-0d49d61a7a2a', '唐', '["於赫皇祖，昭明有融。","惟文之德，惟武之功。","河海靜謐，車書混同。","虔恭孝饗，穆穆玄風。"]', '["於赫皇祖，昭明有融。","惟文之德，惟武之功。","河海静謐，车书混同。","虔恭孝饗，穆穆玄风。"]', '诗', 'shi', '', NULL, '享太廟樂章 廣運舞 郭子儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d22864e-294b-442e-a53d-b381cfc59f81', '享太廟樂章 保大舞', '享太廟乐章 保大舞', '9964896f-2064-49e0-bca2-0d49d61a7a2a', '唐', '["於穆文考，聖神昭彰。","簫勺羣慝，含光遠方。","萬物茂遂，九夷賓王。","愔愔雲韶，德音不忘。"]', '["於穆文考，聖神昭彰。","簫勺羣慝，含光远方。","万物茂遂，九夷賓王。","愔愔云韶，德音不忘。"]', '诗', 'shi', '', NULL, '享太廟樂章 保大舞 郭子儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a73c2e95-76f7-41c9-ae8f-6853bf0bf1a2', '百子池', '百子池', 'af4a9f45-7a26-46c0-9d96-584c77d443c6', '唐', '["舊聞百子漢家池，漢家淥水今逶迤。","宮女厭鏡笑窺池，身前影後不相見。"]', '["旧闻百子漢家池，漢家淥水今逶迤。","宮女厭镜笑窺池，身前影後不相见。"]', '诗', 'shi', '', NULL, '百子池 張諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72d603a6-a1b8-4629-9d88-7fe380b38b3d', '東封山下宴羣臣', '东封山下宴羣臣', 'af4a9f45-7a26-46c0-9d96-584c77d443c6', '唐', '["萬里扈封巒，羣公遇此歡。","幔城連夜靜，霜仗滿空寒。","輦路宵煙合，旌門曉月殘。","明朝陪聖主，山下禮圓壇。"]', '["万里扈封巒，羣公遇此歡。","幔城連夜静，霜仗满空寒。","輦路宵煙合，旌门晓月殘。","明朝陪聖主，山下禮圓壇。"]', '诗', 'shi', '', NULL, '東封山下宴羣臣 張諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('760c54f2-b48b-4e5f-8a4b-771629364989', '三日岐王宅', '三日岐王宅', 'af4a9f45-7a26-46c0-9d96-584c77d443c6', '唐', '["玉女貴妃生，嫛婗始發聲。","金盆浴未了，綳子繡初成。","翡翠雕芳縟，真珠帖小纓。","何時學健步？鬬取落花輕。"]', '["玉女貴妃生，嫛婗始發声。","金盆浴未了，綳子繡初成。","翡翠雕芳縟，真珠帖小纓。","何时学健步？鬬取落花轻。"]', '诗', 'shi', '', NULL, '三日岐王宅 張諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c97842eb-4af6-42a8-b1a1-5539bde31aa5', '滿月', '满月', 'af4a9f45-7a26-46c0-9d96-584c77d443c6', '唐', '["社金流茂祉，庭玉表奇才。","竹似因談植，蘭疑入夢栽。","烏將八子去，鳳逐九雛來。","今夜明珠色，當隨滿月開。"]', '["社金流茂祉，庭玉表奇才。","竹似因談植，蘭疑入梦栽。","烏將八子去，鳳逐九雛来。","今夜明珠色，當隨满月开。"]', '诗', 'shi', '', NULL, '滿月 張諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eda88b0f-c62a-45ef-84f5-f60e86a5bc28', '岐王山亭', '岐王山亭', 'af4a9f45-7a26-46c0-9d96-584c77d443c6', '唐', '["王家傍綠池，春色正相宜。","豈有樓臺好，兼看草樹奇。","石榴天上葉，椰子日南枝。","出入千門裏，年年樂未移。"]', '["王家傍綠池，春色正相宜。","豈有楼台好，兼看草樹奇。","石榴天上葉，椰子日南枝。","出入千门裏，年年乐未移。"]', '诗', 'shi', '', NULL, '岐王山亭 張諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('738332fd-e464-47c5-854a-3c8907c0420e', '岐王席上詠美人', '岐王席上詠美人', 'af4a9f45-7a26-46c0-9d96-584c77d443c6', '唐', '["半額畫雙蛾，盈盈燭下歌。","玉杯寒意少，金屋夜情多。","香豔王分帖，裙嬌敕賜羅。","平陽莫相妬，喚出不如他。"]', '["半額畫雙蛾，盈盈燭下歌。","玉杯寒意少，金屋夜情多。","香豔王分帖，裙嬌敕賜羅。","平陽莫相妬，喚出不如他。"]', '诗', 'shi', '', NULL, '岐王席上詠美人 張諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f49af9d0-bd59-4ea7-b187-d2e680706d33', '還京', '還京', 'af4a9f45-7a26-46c0-9d96-584c77d443c6', '唐', '["朱紱臨秦望，皇華赴洛橋。","文章南渡越，書奏北歸朝。","樹入江雲盡，城銜海月遙。","秋風將客思，川上晚蕭蕭。"]', '["朱紱臨秦望，皇华赴洛橋。","文章南渡越，书奏北归朝。","樹入江云尽，城銜海月遙。","秋风將客思，川上晚蕭蕭。"]', '诗', 'shi', '', NULL, '還京 張諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9b88e5e-5909-4b37-9c3d-8a5c3641f396', '贈吏部孫員外濟', '贈吏部孫員外濟', 'af4a9f45-7a26-46c0-9d96-584c77d443c6', '唐', '["天子愛賢才，星郎入拜來。","明光朝半下，建禮直初迴。","名帶含香發，文隨綺幕開。","披雲自有鏡，從此照仙臺。"]', '["天子愛賢才，星郎入拜来。","明光朝半下，建禮直初迴。","名带含香發，文隨綺幕开。","披云自有镜，從此照仙台。"]', '诗', 'shi', '', NULL, '贈吏部孫員外濟 張諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9eeda00-1160-4028-a848-1a0b83017c80', '送李著作倅杭州', '送李著作倅杭州', 'af4a9f45-7a26-46c0-9d96-584c77d443c6', '唐', '["輟史空三署，題輿佐一方。","祖筵開霽景，征陌直朝光。","水陸風煙隔，秦吳道路長。","佇聞敷善政，邦國詠惟康。"]', '["輟史空三署，題輿佐一方。","祖筵开霽景，征陌直朝光。","水陸风煙隔，秦吳道路长。","佇闻敷善政，邦国詠惟康。"]', '诗', 'shi', '', NULL, '送李著作倅杭州 張諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('394fd898-f9e3-4e52-be36-ce140b3f5992', '九日', '九日', 'af4a9f45-7a26-46c0-9d96-584c77d443c6', '唐', '["秋來林下不知春，一種佳遊事也均。","絳葉從朝飛著夜，黃花開日未成旬。","將曛陌樹頻驚鳥，半醉歸途數問人。","城遠登高倂九日，茱萸凡作幾年新。"]', '["秋来林下不知春，一種佳游事也均。","絳葉從朝飞著夜，黄花开日未成旬。","將曛陌樹頻驚鸟，半醉归途數问人。","城远登高倂九日，茱萸凡作幾年新。"]', '诗', 'shi', '', NULL, '九日 張諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c869f274-e9ed-452a-b3b6-fa246a95be0d', '延平門高齋亭子應岐王教', '延平门高斋亭子應岐王教', 'af4a9f45-7a26-46c0-9d96-584c77d443c6', '唐', '["花源藥嶼鳳城西，翠幕紗窗鶯亂啼。","昨夜蒲萄初上架，今朝楊柳半垂堤。","片片仙雲來渡水，雙雙燕子共銜泥。","請語東風催後騎，倂將歌舞向前谿。"]', '["花源藥嶼鳳城西，翠幕紗窗鶯亂啼。","昨夜蒲萄初上架，今朝楊柳半垂堤。","片片仙云来渡水，雙雙燕子共銜泥。","請語东风催後騎，倂將歌舞向前谿。"]', '诗', 'shi', '', NULL, '延平門高齋亭子應岐王教 張諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98f11149-ee2c-4a9f-b909-cdadce36d2fa', '九日宴', '九日宴', 'af4a9f45-7a26-46c0-9d96-584c77d443c6', '唐', '["秋葉風吹黃颯颯，晴雲日照白鱗鱗。","歸來得問茱萸女，今日登高醉幾人。"]', '["秋葉风吹黄颯颯，晴云日照白鱗鱗。","归来得问茱萸女，今日登高醉幾人。"]', '诗', 'shi', '', NULL, '九日宴 張諤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d108c7f-8c11-48b0-98d0-315baf79b9e6', '從軍', '從軍', 'e27ba75c-892f-4d48-afc8-11a55d9f6866', '唐', '["朔風吹寒塞，胡沙千萬里。","陣雲出岱山，孤月生海水。","決勝方求敵，銜恩本輕死。","蕭蕭牧馬鳴，中夜拔劒起。"]', '["朔风吹寒塞，胡沙千万里。","陣云出岱山，孤月生海水。","決勝方求敵，銜恩本轻死。","蕭蕭牧马鳴，中夜拔劒起。"]', '诗', 'shi', '', NULL, '從軍 劉庭琦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f234307-50b8-4f01-8dfe-fba9acd9cc7a', '奉和聖製瑞雪篇', '奉和聖製瑞雪篇', 'e27ba75c-892f-4d48-afc8-11a55d9f6866', '唐', '["紫宸飛雪曉裴回，層閣重門雪照開。","九衢皛耀浮埃盡，千品差池贄帛來。","何處田中非種玉，誰家院裏不生梅？","埋雲翳景無窮已，因風落地吹還起。","先過翡翠寶房中，轉入鴛鴦金殿裏。","美人含笑出聯翩，豔逸相輕鬬容止。","羅衣點著渾是花，玉手摶來半成水。","奕奕紛紛何所如，頓憶楊園二月初。","羞同班女高秋扇，欲照明王乙夜書。","姑射山中符聖壽，芙蓉闕下降神車。","願隨睿澤流無限，長報豐年貴有餘。"]', '["紫宸飞雪晓裴回，層閣重门雪照开。","九衢皛耀浮埃尽，千品差池贄帛来。","何处田中非種玉，誰家院裏不生梅？","埋云翳景無窮已，因风落地吹還起。","先過翡翠寶房中，轉入鴛鴦金殿裏。","美人含笑出聯翩，豔逸相轻鬬容止。","羅衣点著渾是花，玉手摶来半成水。","奕奕紛紛何所如，頓憶楊园二月初。","羞同班女高秋扇，欲照明王乙夜书。","姑射山中符聖壽，芙蓉闕下降神车。","願隨睿澤流無限，长報豐年貴有餘。"]', '诗', 'shi', '', NULL, '奉和聖製瑞雪篇 劉庭琦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('476908f1-15ce-4d83-a8b8-178a866d9f39', '詠木槿樹題武進文明府廳', '詠木槿樹題武進文明府廳', 'e27ba75c-892f-4d48-afc8-11a55d9f6866', '唐', '["物情良可見，人事不勝悲。","莫恃朝榮好，君看暮落時。"]', '["物情良可见，人事不勝悲。","莫恃朝榮好，君看暮落时。"]', '诗', 'shi', '', NULL, '詠木槿樹題武進文明府廳 劉庭琦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('409480c8-adcb-41b6-bd7b-33693b76b64a', '銅雀臺', '銅雀台', 'e27ba75c-892f-4d48-afc8-11a55d9f6866', '唐', '["銅臺宮觀委灰塵，魏主園林漳水濱。","即今西望猶堪思，況復當時歌舞人。"]', '["銅台宮观委灰塵，魏主园林漳水濱。","即今西望猶堪思，況复當时歌舞人。"]', '诗', 'shi', '', NULL, '銅雀臺 劉庭琦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('097b2ef7-d98e-4ece-afdf-d271139ec20e', '失白鷹', '失白鷹', '123c49af-6825-4594-a2f4-f0492acb0720', '唐', '["白錦文章亂，丹霄羽翮齊。","雲中呼暫下，雪裏放還迷。","梁苑驚池鶩，陳倉拂野雞。"]', '["白錦文章亂，丹霄羽翮齊。","云中呼暫下，雪裏放還迷。","梁苑驚池鶩，陳倉拂野雞。"]', '诗', 'shi', '', NULL, '失白鷹 鄭繇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0486e63b-397b-448f-ad85-88e59a524ced', '經慈澗題', '經慈澗題', '123c49af-6825-4594-a2f4-f0492acb0720', '唐', '["岸與恩同廣，波將慈共深。","涓涓勞日夜，長似下流心。"]', '["岸與恩同廣，波將慈共深。","涓涓勞日夜，长似下流心。"]', '诗', 'shi', '', NULL, '經慈澗題 鄭繇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39a1c0f9-bf83-443e-b84e-62c7e7fd6fa2', '奉和御製平胡', '奉和御製平胡', '7295782d-8e11-4ef1-909a-fcdc2015fdfa', '唐', '["南牧正紛紛，長河起塞氛。","玉符徵選士，金鉞拜將軍。","疊鼓搖邊吹，連旌暗朔雲。","祅星乘夜落，害氣入朝分。","始見幽烽警，俄看烈火焚。","功成奏凱樂，戰罷策歸勳。","盛德陳清廟，神謨屬大君。","叨榮逢偃羽，率舞詠時文。"]', '["南牧正紛紛，长河起塞氛。","玉符徵選士，金鉞拜將軍。","叠鼓搖邊吹，連旌暗朔云。","祅星乘夜落，害氣入朝分。","始见幽烽警，俄看烈火焚。","功成奏凱乐，戰罷策归勳。","盛德陳清廟，神謨屬大君。","叨榮逢偃羽，率舞詠时文。"]', '诗', 'shi', '', NULL, '奉和御製平胡 韓休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4c506d3-0f24-44ae-96a8-65e68849a0be', '奉和聖製送張說巡邊', '奉和聖製送張说巡邊', '7295782d-8e11-4ef1-909a-fcdc2015fdfa', '唐', '["一德光台象，三軍掌夏卿。","來威申廟略，出總叶師貞。","受鉞辭金殿，憑軒去鼎城。","曙光搖組甲，疎吹繞雲旌。","左律方先凱，中鼙即訓兵。","定功彰武事，陳頌紀天聲。","祖宴初留賞，宸章更寵行。","車徒零雨送，林野夕陰生。","路極河流遠，川長朔氣平。","南轅遲返斾，歸奏謁承明。"]', '["一德光台象，三軍掌夏卿。","来威申廟略，出總叶師貞。","受鉞辞金殿，憑軒去鼎城。","曙光搖組甲，疎吹繞云旌。","左律方先凱，中鼙即訓兵。","定功彰武事，陳頌紀天声。","祖宴初留賞，宸章更寵行。","车徒零雨送，林野夕陰生。","路極河流远，川长朔氣平。","南轅遲返斾，归奏謁承明。"]', '诗', 'shi', '', NULL, '奉和聖製送張說巡邊 韓休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('335c8817-702f-479e-ac93-3e5a24681f49', '祭汾陰樂章', '祭汾陰乐章', '7295782d-8e11-4ef1-909a-fcdc2015fdfa', '唐', '["於穆濬哲，維清緝熙。","肅事昭配，永言孝思。","滌濯靜嘉，馨香在茲。","神之聽之，用受福釐。"]', '["於穆濬哲，維清緝熙。","肅事昭配，永言孝思。","滌濯静嘉，馨香在茲。","神之听之，用受福釐。"]', '诗', 'shi', '', NULL, '祭汾陰樂章 韓休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('feb96a9b-0a04-4a7f-9944-a3f641aaf9f0', '徵君宅', '徵君宅', 'a85e9e64-21d4-4d54-a3a7-0b20ecee9eae', '唐', '["徵君昔嘉遯，抗跡遺俗塵。","了心悟有物，乘化遊無垠。","道喪歷千載，復存潁陽真。","上虞佳山水，晚歲耽隱淪。","內史既解綬，支公亦相親。","儒道匪遠理，意勝聊自欣。","洄沿南谿夕，流浪東山春。","石壁踐丹景，金潭冒綠蘋。","探鍊備海嶠，賞心寓情人。","奈何靈仙骨，鍬翮瑤池津。","寥寥虛白宇，夙剏招提因。","家風緬多尚，玄德謝無鄰。","謬陪金門彥，矯跡侍紫宸。","皇恩竟已矣，遺烈庶不泯。"]', '["徵君昔嘉遯，抗跡遺俗塵。","了心悟有物，乘化游無垠。","道喪歷千載，复存潁陽真。","上虞佳山水，晚歲耽隐淪。","內史既解綬，支公亦相親。","儒道匪远理，意勝聊自欣。","洄沿南谿夕，流浪东山春。","石壁踐丹景，金潭冒綠蘋。","探鍊備海嶠，賞心寓情人。","奈何靈仙骨，鍬翮瑤池津。","寥寥虛白宇，夙剏招提因。","家风緬多尚，玄德謝無鄰。","謬陪金门彥，矯跡侍紫宸。","皇恩竟已矣，遺烈庶不泯。"]', '诗', 'shi', '', NULL, '徵君宅 許景先 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdef87c4-ea2c-4314-a05c-c2a3a2020d5b', '折柳篇', '折柳篇', 'a85e9e64-21d4-4d54-a3a7-0b20ecee9eae', '唐', '["春色東來度渭橋，青門垂柳百千條。","長楊西連建章路，漢家林苑紛無數。","縈花始遍合歡枝，遊絲半罥相思樹。","春樓初日照南隅，柔條垂綠掃金鋪。","寶釵新梳倭墮髻，錦帶交垂連理襦。","自憐柳塞淹戎幕，銀燭長啼愁夢著。","芳樹朝催玉管新，春風夜染羅衣薄。","城頭楊柳已如絲，今年花落去年時。","折芳遠寄相思曲，爲惜容華難再持。"]', '["春色东来度渭橋，青门垂柳百千條。","长楊西連建章路，漢家林苑紛無數。","縈花始遍合歡枝，游絲半罥相思樹。","春楼初日照南隅，柔條垂綠掃金鋪。","寶釵新梳倭墮髻，錦带交垂連理襦。","自怜柳塞淹戎幕，銀燭长啼愁梦著。","芳樹朝催玉管新，春风夜染羅衣薄。","城头楊柳已如絲，今年花落去年时。","折芳远寄相思曲，爲惜容华难再持。"]', '诗', 'shi', '', NULL, '折柳篇 許景先 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05f82d30-58ac-461b-bc36-ec76ce48811d', '奉和御製春臺望', '奉和御製春台望', 'a85e9e64-21d4-4d54-a3a7-0b20ecee9eae', '唐', '["睿德在青陽，高居視中縣。","秦城連鳳闕，漢寢疏龍殿。","文物照光輝，郊畿鬱葱蒨。","千門望成錦，八水明如練。","複道曉光披，宸遊出禁移。","瑞氣朝浮五雲閣，祥光夜吐萬年枝。","蘭葉負龜初薦祉，桐花集鳳更來儀。","秦漢生人凋力役，阿房甘泉構雲碧。","汾祠雍畤望通天，玉堂宣室坐長年。","鼓鐘西接咸陽觀，苑囿南通鄠杜田。","明主卑宮誡前失，輔德欽賢政惟一。","昆蟲不夭在春蒐，稼穡常艱重農術。","邦家已荷聖謨新，猶聞儉陋惜中人。","豫奉北辰齊七政，長歌東武抃千春。"]', '["睿德在青陽，高居視中縣。","秦城連鳳闕，漢寢疏龙殿。","文物照光輝，郊畿鬱葱蒨。","千门望成錦，八水明如練。","複道晓光披，宸游出禁移。","瑞氣朝浮五云閣，祥光夜吐万年枝。","蘭葉負龟初薦祉，桐花集鳳更来儀。","秦漢生人凋力役，阿房甘泉構云碧。","汾祠雍畤望通天，玉堂宣室坐长年。","鼓鐘西接咸陽观，苑囿南通鄠杜田。","明主卑宮誡前失，輔德欽賢政惟一。","昆蟲不夭在春蒐，稼穡常艱重農術。","邦家已荷聖謨新，猶闻儉陋惜中人。","豫奉北辰齊七政，长歌东武抃千春。"]', '诗', 'shi', '', NULL, '奉和御製春臺望 許景先 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cee76afb-0fad-4e36-b901-da622b03df46', '陽春怨', '陽春怨', 'a85e9e64-21d4-4d54-a3a7-0b20ecee9eae', '唐', '["紅樹曉鶯蹄，春風暖翠閨。","雕籠熏繡被，珠履踏金堤。","芍藥花初吐，菖蒲葉正齊。","藁砧當此日，行役向遼西。"]', '["紅樹晓鶯蹄，春风暖翠閨。","雕籠熏繡被，珠履踏金堤。","芍藥花初吐，菖蒲葉正齊。","藁砧當此日，行役向遼西。"]', '诗', 'shi', '', NULL, '陽春怨 許景先 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c23c5496-030a-4a54-8d35-948712d74756', '奉和聖製送張尚書巡邊', '奉和聖製送張尚书巡邊', 'a85e9e64-21d4-4d54-a3a7-0b20ecee9eae', '唐', '["文武承邦式，風雲感國禎。","王師親賦政，廟略久論兵。","漢主知三傑，周官統六卿。","四方分閫受，千里坐謀成。","介胄辭前殿，壺觴宿左營。","賞延頒賜重，宸贈出車榮。","龍武三軍氣，魚鈴五校名。","郊雲駐旌羽，邊吹引金鉦。","訓旅方稱德，安人更克貞。","佇看銘石罷，同聽凱歌聲。"]', '["文武承邦式，风云感国禎。","王師親賦政，廟略久論兵。","漢主知三傑，周官統六卿。","四方分閫受，千里坐謀成。","介胄辞前殿，壺觴宿左營。","賞延頒賜重，宸贈出车榮。","龙武三軍氣，鱼鈴五校名。","郊云駐旌羽，邊吹引金鉦。","訓旅方稱德，安人更克貞。","佇看銘石罷，同听凱歌声。"]', '诗', 'shi', '', NULL, '奉和聖製送張尚書巡邊 許景先 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a13f9919-7528-4a5d-8347-c7a862412b89', '詠史', '詠史', '27193e94-e3e2-419c-adb9-3510b82835da', '唐', '["高潔非養正，盛名亦險艱。","偉哉謝安石，攜妓入東山。","雲巖響金奏，空水灧朱顏。","蘭露滋香澤，松風鳴珮環。","歌聲入空盡，舞影到池閑。","杳眇同天上，繁華非代間。","卷舒混名跡，縱誕無憂患。","何必蘇門子，冥然閉清關。"]', '["高潔非養正，盛名亦險艱。","偉哉謝安石，携妓入东山。","云巖响金奏，空水灧朱顏。","蘭露滋香澤，松风鳴珮环。","歌声入空尽，舞影到池闲。","杳眇同天上，繁华非代间。","卷舒混名跡，縱誕無憂患。","何必蘇门子，冥然閉清关。"]', '诗', 'shi', '', NULL, '詠史 王丘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3218fe9c-8dc4-460d-9bba-89b3c6a107b7', '奉和聖製荅張說扈從南出鼠雀谷之作', '奉和聖製荅張说扈從南出鼠雀谷之作', '27193e94-e3e2-419c-adb9-3510b82835da', '唐', '["襟帶三秦接，旂常萬乘過。","陽原淑氣早，陰谷沍寒多。","花縟前茅仗，霜嚴後殿戈。","代雲開晉嶺，江雁入汾河。","北土分堯俗，南風動舜歌。","一聞天樂唱，恭逐萬人和。"]', '["襟带三秦接，旂常万乘過。","陽原淑氣早，陰谷沍寒多。","花縟前茅仗，霜嚴後殿戈。","代云开晉嶺，江雁入汾河。","北土分堯俗，南风动舜歌。","一闻天乐唱，恭逐万人和。"]', '诗', 'shi', '', NULL, '奉和聖製荅張說扈從南出鼠雀谷之作 王丘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06dc81a5-672a-45e7-a824-bbbcfdfacfd2', '奉和聖製送張尚書巡邊', '奉和聖製送張尚书巡邊', '27193e94-e3e2-419c-adb9-3510b82835da', '唐', '["德業蘊時宗，幽符夢象通。","台司計祈父，師律總元戎。","出入敷能政，謀猷體至公。","贈行光睿什，宴別感宸衷。","文炳高天曜，恩垂湛露融。","建牙之塞表，鳴鼓接雲中。","策密鬼神祕，威成劍騎雄。","朔門正炎月，兵氣已秋風。","肅殺從此始，方知胡運窮。"]', '["德業蘊时宗，幽符梦象通。","台司計祈父，師律總元戎。","出入敷能政，謀猷體至公。","贈行光睿什，宴別感宸衷。","文炳高天曜，恩垂湛露融。","建牙之塞表，鳴鼓接云中。","策密鬼神祕，威成劍騎雄。","朔门正炎月，兵氣已秋风。","肅殺從此始，方知胡運窮。"]', '诗', 'shi', '', NULL, '奉和聖製送張尚書巡邊 王丘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86096050-5a25-46a4-8412-ce6fdde8995f', '過賈六', '過賈六', '394e26a1-3ca6-4b91-b5e2-32a0d646ac6f', '唐', '["主人病且閑，客來情彌適。","一酌復一笑，不知日將夕。","昨來屬歡游，於今盡成昔。","努力持所趣，空名定何益。"]', '["主人病且闲，客来情彌適。","一酌复一笑，不知日將夕。","昨来屬歡游，於今尽成昔。","努力持所趣，空名定何益。"]', '诗', 'shi', '', NULL, '過賈六 蘇晉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('000ede98-9759-43b7-adb0-4471d95e6bac', '奉和聖製送張說巡邊', '奉和聖製送張说巡邊', '394e26a1-3ca6-4b91-b5e2-32a0d646ac6f', '唐', '["方漢比周年，興王合在宣。","亟聞降虜拜，復覩出師篇。","祈父萬邦式，英猷三略傳。","算車申夏政，茇舍啓戎田。","嚴問盟胡苑，軍容濟洛川。","皇情悵關斾，詔餞列郊筵。","路接禁園草，池分御井蓮。","離聲軫去角，居念斷歸蟬。","三捷豈云爾，七擒良信然。","具僚誠寄望，奏凱秋風前。"]', '["方漢比周年，兴王合在宣。","亟闻降虜拜，复覩出師篇。","祈父万邦式，英猷三略傳。","算车申夏政，茇舍啓戎田。","嚴问盟胡苑，軍容濟洛川。","皇情悵关斾，詔餞列郊筵。","路接禁园草，池分御井蓮。","離声軫去角，居念斷归蟬。","三捷豈云爾，七擒良信然。","具僚誠寄望，奏凱秋风前。"]', '诗', 'shi', '', NULL, '奉和聖製送張說巡邊 蘇晉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97839a51-808c-4d21-a951-c8eb863457d4', '奉和聖製送張說巡邊', '奉和聖製送張说巡邊', '045e67cb-4235-46b5-8056-9f9295b34064', '唐', '["供帳何煌煌，公其撫朔方。","羣僚咸餞酌，明主降離章。","關塞重門下，郊岐禁苑傍。","練兵宜雨洗，臥鼓候風涼。","炎景寧云憚，神謀肅所將。","旌搖天月迥，騎入塞雲長。","赫赫皇威振，油油聖澤滂。","非惟按車甲，兼以正封疆。","叱詫陰山道，澄清翰海陽。","虜垣行決勝，台座佇爲光。"]', '["供帳何煌煌，公其撫朔方。","羣僚咸餞酌，明主降離章。","关塞重门下，郊岐禁苑傍。","練兵宜雨洗，臥鼓候风涼。","炎景寧云憚，神謀肅所將。","旌搖天月迥，騎入塞云长。","赫赫皇威振，油油聖澤滂。","非惟按车甲，兼以正封疆。","叱詫陰山道，澄清翰海陽。","虜垣行決勝，台座佇爲光。"]', '诗', 'shi', '', NULL, '奉和聖製送張說巡邊 崔禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa5e6f28-7fd0-41cb-8eb1-5b07a33c2556', '恩敕尚書省僚宴昆明池應制', '恩敕尚书省僚宴昆明池應制', '59f3cb34-cce1-4618-b2b4-de9f8eb4fc4c', '唐', '["靈沼初開漢，神池舊浴堯。","昔人徒習武，明代此聞韶。","地脈山川勝，天恩雨露饒。","時光牽利舸，春淑覆柔條。","芳醞酲千日，華牋落九霄。","幸承歡賚重，不覺醉歸遙。"]', '["靈沼初开漢，神池旧浴堯。","昔人徒習武，明代此闻韶。","地脈山川勝，天恩雨露饒。","时光牽利舸，春淑覆柔條。","芳醞酲千日，华牋落九霄。","幸承歡賚重，不覺醉归遙。"]', '诗', 'shi', '', NULL, '恩敕尚書省僚宴昆明池應制 張嘉貞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('485cc25b-4678-498b-b388-08d60e9c535b', '奉和早登太行山中言志應制', '奉和早登太行山中言志應制', '59f3cb34-cce1-4618-b2b4-de9f8eb4fc4c', '唐', '["明發扈山巔，飛龍高在天。","山南平對鞏，山北遠通燕。","瞻彼岡巒峻，憑茲士馬妍。","九圻行若砥，萬谷輾如川。","羅網開三面，閭閻問百年。","澤將春雪比，文共曉星連。","徯后逢今聖，登台謝曩賢。","唯餘事君節，不讓古人先。"]', '["明發扈山巔，飞龙高在天。","山南平对鞏，山北远通燕。","瞻彼岡巒峻，憑茲士马妍。","九圻行若砥，万谷輾如川。","羅網开三面，閭閻问百年。","澤將春雪比，文共晓星連。","徯后逢今聖，登台謝曩賢。","唯餘事君節，不讓古人先。"]', '诗', 'shi', '', NULL, '奉和早登太行山中言志應制 張嘉貞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cc7ee29-39ed-4e57-bd60-d4910a93be0e', '奉和聖製送張說巡邊', '奉和聖製送張说巡邊', '59f3cb34-cce1-4618-b2b4-de9f8eb4fc4c', '唐', '["天錫我宗盟，元戎付夏卿。","多才兼將相，必勇獨橫行。","經緯稱人傑，文章作代英。","山川看是陣，草木想爲兵。","不待河冰合，猶防塞月明。","有謀當繫醜，無戰且綏氓。","閫外傳三略，雲中冀一平。","感恩同義激，悵別屢魂驚。","直視前旌掣，遙聞後騎鳴。","還期方定日，復此出郊迎。"]', '["天錫我宗盟，元戎付夏卿。","多才兼將相，必勇独橫行。","經緯稱人傑，文章作代英。","山川看是陣，草木想爲兵。","不待河冰合，猶防塞月明。","有謀當繫醜，無戰且綏氓。","閫外傳三略，云中冀一平。","感恩同義激，悵別屢魂驚。","直視前旌掣，遙闻後騎鳴。","還期方定日，复此出郊迎。"]', '诗', 'shi', '', NULL, '奉和聖製送張說巡邊 張嘉貞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5505a7aa-ed04-4a77-840b-c8966d315802', '句', '句', '59f3cb34-cce1-4618-b2b4-de9f8eb4fc4c', '唐', '["河魚未上凍，江蟄已聞雷。"]', '["河鱼未上凍，江蟄已闻雷。"]', '诗', 'shi', '', NULL, '句 張嘉貞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('502f3a7b-a236-49e1-adab-ecb2994c9772', '奉和聖製送張說巡邊', '奉和聖製送張说巡邊', '1e8f1e33-674e-418a-b3de-0d384def500b', '唐', '["上將發文昌，中軍靜朔方。","占星引旌節，擇日拜壇場。","禮樂臨軒送，威聲出塞揚。","安邊俟帷幄，制勝在巖廊。","作鼓將軍氣，投醪壯士觴。","戒途遵六月，離贈動三光。","槐路清梅暑，蘅臯起麥涼。","時文仰雄伯，耀武震遐荒。","衽席知無戰，兵戈示不忘。","佇聞歌杕杜，凱入繫名王。"]', '["上將發文昌，中軍静朔方。","占星引旌節，擇日拜壇場。","禮乐臨軒送，威声出塞揚。","安邊俟帷幄，制勝在巖廊。","作鼓將軍氣，投醪壯士觴。","戒途遵六月，離贈动三光。","槐路清梅暑，蘅臯起麦涼。","时文仰雄伯，耀武震遐荒。","衽席知無戰，兵戈示不忘。","佇闻歌杕杜，凱入繫名王。"]', '诗', 'shi', '', NULL, '奉和聖製送張說巡邊 盧從愿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7022466-a984-4926-a64b-be9acb8d8b16', '祭汾陰樂章', '祭汾陰乐章', '1e8f1e33-674e-418a-b3de-0d384def500b', '唐', '["坤元載物，陽樂發生。","播植資始，品彙咸亨。","列俎棊布，方壇砥平。","神歆禋祀，后德惟明。"]', '["坤元載物，陽乐發生。","播植資始，品彙咸亨。","列俎棊布，方壇砥平。","神歆禋祀，后德惟明。"]', '诗', 'shi', '', NULL, '祭汾陰樂章 盧從愿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7e52b7f-b4c8-4c4d-abf9-4ce444fe421d', '長門怨', '长门怨', 'a401176c-92fa-4cbb-bfb6-3b739195901a', '唐', '["早知君愛歇，本自無縈妒。","誰使恩情深，今來反相誤。","愁眠羅帳曉，泣坐金閨暮。","獨有夢中魂，猶言意如故。"]', '["早知君愛歇，本自無縈妒。","誰使恩情深，今来反相誤。","愁眠羅帳晓，泣坐金閨暮。","独有梦中魂，猶言意如故。"]', '诗', 'shi', '', NULL, '長門怨 袁暉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af25d93d-733d-42f0-894b-9b917792da5d', '銅雀妓', '銅雀妓', 'a401176c-92fa-4cbb-bfb6-3b739195901a', '唐', '["君愛本相饒，從來似舞腰。","那堪攀玉座，腸斷望陵朝。","怨著情無主，哀凝曲不調。","況臨松日暮，悲吹坐蕭蕭。"]', '["君愛本相饒，從来似舞腰。","那堪攀玉座，腸斷望陵朝。","怨著情無主，哀凝曲不調。","況臨松日暮，悲吹坐蕭蕭。"]', '诗', 'shi', '', NULL, '銅雀妓 袁暉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bea50743-fb46-4fc0-94c0-0e8fc05f5294', '正月閨情', '正月閨情', 'a401176c-92fa-4cbb-bfb6-3b739195901a', '唐', '["正月金閨裏，微風繡戶間。","曉魂憐別夢，春思逼啼顏。","遶砌梅堪折，當軒樹未攀。","歲華庭北上，何日度陽關。"]', '["正月金閨裏，微风繡戶间。","晓魂怜別梦，春思逼啼顏。","遶砌梅堪折，當軒樹未攀。","歲华庭北上，何日度陽关。"]', '诗', 'shi', '', NULL, '正月閨情 袁暉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4649aec3-077d-499c-bdcf-19ffeb68887d', '二月閨情', '二月閨情', 'a401176c-92fa-4cbb-bfb6-3b739195901a', '唐', '["二月韶光好，春風香氣多。","園中花巧笑，林裏鳥能歌。","有恨離琴瑟，無情著綺羅。","更聽春燕語，妾亦不如他。"]', '["二月韶光好，春风香氣多。","园中花巧笑，林裏鸟能歌。","有恨離琴瑟，無情著綺羅。","更听春燕語，妾亦不如他。"]', '诗', 'shi', '', NULL, '二月閨情 袁暉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79cc2e51-0605-4acd-bcbd-989f29961253', '三月閨情', '三月閨情', 'a401176c-92fa-4cbb-bfb6-3b739195901a', '唐', '["三月春將盡，空房妾獨居。","蛾眉愁自結，鬢髪沒情梳。","□□□□□，□□□□□。","□□□□□，□□□□□。"]', '["三月春將尽，空房妾独居。","蛾眉愁自結，鬢髪沒情梳。","□□□□□，□□□□□。","□□□□□，□□□□□。"]', '诗', 'shi', '', NULL, '三月閨情 袁暉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f08eb28-640f-4fd7-87f3-bfa5d6c426b3', '七月閨情', '七月閨情', 'a401176c-92fa-4cbb-bfb6-3b739195901a', '唐', '["七月坐涼宵，金波滿麗譙。","容華芳意改，枕席怨情饒。","錦字沾愁淚，羅裙緩細腰。","不如銀漢女，歲歲鵲成橋。"]', '["七月坐涼宵，金波满丽譙。","容华芳意改，枕席怨情饒。","錦字沾愁泪，羅裙緩細腰。","不如銀漢女，歲歲鵲成橋。"]', '诗', 'shi', '', NULL, '七月閨情 袁暉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29b67fd8-ac8b-4e91-909e-b92ef44c66d1', '奉和聖製荅張說扈從南出雀鼠谷之作', '奉和聖製荅張说扈從南出雀鼠谷之作', 'a401176c-92fa-4cbb-bfb6-3b739195901a', '唐', '["魏國山河險，周王警蹕迴。","九旗雲際出，萬騎谷中來。","石路行將盡，煙郊望忽開。","賞矜垂柳報，春畏落花催。","興逸橫汾什，恩褒作頌才。","小臣瞻日月，延首詠康哉。"]', '["魏国山河險，周王警蹕迴。","九旗云際出，万騎谷中来。","石路行將尽，煙郊望忽开。","賞矜垂柳報，春畏落花催。","兴逸橫汾什，恩褒作頌才。","小臣瞻日月，延首詠康哉。"]', '诗', 'shi', '', NULL, '奉和聖製荅張說扈從南出雀鼠谷之作 袁暉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6100a4a9-5b27-4888-a917-ae59cb31c027', '奉和聖製送張尚書巡邊', '奉和聖製送張尚书巡邊', 'a401176c-92fa-4cbb-bfb6-3b739195901a', '唐', '["出師宣九命，分閫用三台。","始應幕中畫，言從天上來。","丹青不獨任，韜略遂雙該。","坐見威稜洽，彌彰事業恢。","旌旗曉雲送，鞞鼓朔風催。","虜氣消殘月，邊聲韻落梅。","羽書雄北地，龍漠寢南垓。","寵戰黃金盡，輸誠白日迴。","離章宸翰發，祖讌國門開。","欲識恩華盛，平生文武材。"]', '["出師宣九命，分閫用三台。","始應幕中畫，言從天上来。","丹青不独任，韜略遂雙該。","坐见威稜洽，彌彰事業恢。","旌旗晓云送，鞞鼓朔风催。","虜氣消殘月，邊声韻落梅。","羽书雄北地，龙漠寢南垓。","寵戰黄金尽，輸誠白日迴。","離章宸翰發，祖讌国门开。","欲識恩华盛，平生文武材。"]', '诗', 'shi', '', NULL, '奉和聖製送張尚書巡邊 袁暉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c08da636-312a-412a-a664-5f36076e2030', '奉和聖製荅張說扈從南出雀鼠谷', '奉和聖製荅張说扈從南出雀鼠谷', '22d7aa9e-0f65-492d-a8ac-bc58f327b02f', '唐', '["省俗恩將遍，巡方路稍迴。","寒隨汾谷盡，春逐晉郊來。","雲騎傳行漏，煙旄引從臺。","惠風初應律，和氣正調梅。","雅頌通宸詠，天文接曙台。","灞陵桃李色，應待日華開。"]', '["省俗恩將遍，巡方路稍迴。","寒隨汾谷尽，春逐晉郊来。","云騎傳行漏，煙旄引從台。","惠风初應律，和氣正調梅。","雅頌通宸詠，天文接曙台。","灞陵桃李色，應待日华开。"]', '诗', 'shi', '', NULL, '奉和聖製荅張說扈從南出雀鼠谷 王光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1b1a72d-b466-4bf3-bb80-8f3c6de9cc49', '奉和聖製送張說巡邊', '奉和聖製送張说巡邊', '22d7aa9e-0f65-492d-a8ac-bc58f327b02f', '唐', '["賢相德符充，朝推文武雄。","海波先若鏡，關草豫從風。","鉞助將軍勇，威成天子功。","瓊章九霄發，錫宴五衢通。","玉輾龍盤帶，金裝鳳勒驄。","虎貔紛儗儗，河洛振熊熊。","戈劍千霜白，旌旗萬火紅。","示刑夷夏變，流惠鬼方同。","寇息軍容偃，塵銷朔野空。","用師敷禮樂，非是爲獯戎。"]', '["賢相德符充，朝推文武雄。","海波先若镜，关草豫從风。","鉞助將軍勇，威成天子功。","瓊章九霄發，錫宴五衢通。","玉輾龙盤带，金裝鳳勒驄。","虎貔紛儗儗，河洛振熊熊。","戈劍千霜白，旌旗万火紅。","示刑夷夏变，流惠鬼方同。","寇息軍容偃，塵銷朔野空。","用師敷禮乐，非是爲獯戎。"]', '诗', 'shi', '', NULL, '奉和聖製送張說巡邊 王光庭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('868fbddc-f0b1-4cd9-b915-017aab829bd6', '奉和聖製送張說巡邊', '奉和聖製送張说巡邊', '45762450-e174-4a96-90ab-d018cc07f9a6', '唐', '["聖德膺三統，皇恩被八埏。","大明均照物，小醜未寧邊。","國相台衡重，元戎廟略宣。","紫泥方受命，黃石乃推賢。","問辠陰山下，安人屬國前。","度關行照月，乘障坐消煙。","北闕紆宸藻，南橋列祖筵。","耀威當夏日，殺氣指秋天。","鞞鼓黿鼉振，旌旗鳥獸懸。","由來詞翰手，今見勒燕然。"]', '["聖德膺三統，皇恩被八埏。","大明均照物，小醜未寧邊。","国相台衡重，元戎廟略宣。","紫泥方受命，黄石乃推賢。","问辠陰山下，安人屬国前。","度关行照月，乘障坐消煙。","北闕紆宸藻，南橋列祖筵。","耀威當夏日，殺氣指秋天。","鞞鼓黿鼉振，旌旗鸟獸懸。","由来词翰手，今见勒燕然。"]', '诗', 'shi', '', NULL, '奉和聖製送張說巡邊 徐知仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bb20764-fe77-441e-babf-dfd3e73503a4', '奉和勅賜公主鏡', '奉和勅賜公主镜', '5b683dae-3c12-4365-a1dc-cdbb11fcc6ff', '唐', '["令節頒龍鏡，仙輝下鳳臺。","含靈萬象入，寫照百花開。","色與皇明散，光隨聖澤來。","妍媸冰鑑裏，從此愧非才。"]', '["令節頒龙镜，仙輝下鳳台。","含靈万象入，寫照百花开。","色與皇明散，光隨聖澤来。","妍媸冰鑑裏，從此愧非才。"]', '诗', 'shi', '', NULL, '奉和勅賜公主鏡 席豫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b09794a8-da3c-473b-939c-a9c8687def73', '江行紀事二首 一', '江行紀事二首 一', '5b683dae-3c12-4365-a1dc-cdbb11fcc6ff', '唐', '["飄颻任舟楫，迴合傍江津。","後浦情猶在，前山賞更新。","樹深煙冪冪，灘淺石磷磷。","川路南行遠，淹留惜此辰。"]', '["飄颻任舟楫，迴合傍江津。","後浦情猶在，前山賞更新。","樹深煙冪冪，灘淺石磷磷。","川路南行远，淹留惜此辰。"]', '诗', 'shi', '', NULL, '江行紀事二首 一 席豫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('152f099c-7665-4218-a5d4-cadd9a51a327', '江行紀事二首 二', '江行紀事二首 二', '5b683dae-3c12-4365-a1dc-cdbb11fcc6ff', '唐', '["江汛春風勢，山樓曙月輝。","猿攀紫巖飲，鳥拂清潭飛。","古樹崩沙岸，新苔覆石磯。","津途賞無限，征客蹔忘歸。"]', '["江汛春风勢，山楼曙月輝。","猿攀紫巖饮，鸟拂清潭飞。","古樹崩沙岸，新苔覆石磯。","津途賞無限，征客蹔忘归。"]', '诗', 'shi', '', NULL, '江行紀事二首 二 席豫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ded4090-008e-41f9-9279-ad581a1da886', '奉和聖製答張說南出雀鼠谷', '奉和聖製答張说南出雀鼠谷', '5b683dae-3c12-4365-a1dc-cdbb11fcc6ff', '唐', '["鳴鑾初幸代，旋蓋欲橫汾。","山盡千旗出，郊平五校分。","前林已暄景，後壑尚寒氛。","風送簫韶曲，花鋪黼黻文。","鹽梅推上宰，禮樂統中軍。","獻賦紆天札，飄颻飛白雲。"]', '["鳴鑾初幸代，旋蓋欲橫汾。","山尽千旗出，郊平五校分。","前林已暄景，後壑尚寒氛。","风送簫韶曲，花鋪黼黻文。","鹽梅推上宰，禮乐統中軍。","獻賦紆天札，飄颻飞白云。"]', '诗', 'shi', '', NULL, '奉和聖製答張說南出雀鼠谷 席豫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae1df7b5-c6fa-4a73-9179-28eb08e87c7e', '奉和聖製送張說巡邊', '奉和聖製送張说巡邊', '5b683dae-3c12-4365-a1dc-cdbb11fcc6ff', '唐', '["聖主重兵權，分符屬大賢。","中軍仍執政，丞相復巡邊。","翕習戎裝動，張皇廟略宣。","朝榮承睿札，野餞轉行旃。","亭障東緣海，沙場北際天。","春冬見巖雪，朝夕候烽煙。","已勒封山記，猶聞遣戍篇。","五營將月合，八陣與雲連。","經略圖方遠，懷柔道更全。","歸來畫麟閣，藹藹武功傳。"]', '["聖主重兵權，分符屬大賢。","中軍仍執政，丞相复巡邊。","翕習戎裝动，張皇廟略宣。","朝榮承睿札，野餞轉行旃。","亭障东緣海，沙場北際天。","春冬见巖雪，朝夕候烽煙。","已勒封山記，猶闻遣戍篇。","五營將月合，八陣與云連。","經略圖方远，懷柔道更全。","归来畫麟閣，藹藹武功傳。"]', '诗', 'shi', '', NULL, '奉和聖製送張說巡邊 席豫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab10b8da-25cd-4c86-bc72-39ea5106adaf', '祭汾陰樂章', '祭汾陰乐章', 'dbc9aad0-7fe1-45f7-9802-e0fca34339d5', '唐', '["大樂和暢，殷薦明神。","一降通感，八變必臻。","有求斯應，無德不親。","降靈醉止，休徵萬人。"]', '["大乐和暢，殷薦明神。","一降通感，八变必臻。","有求斯應，無德不親。","降靈醉止，休徵万人。"]', '诗', 'shi', '', NULL, '祭汾陰樂章 韓思復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fe5d450-c2c0-4e86-b05c-22ff6fa7b92e', '祭汾陰樂章', '祭汾陰乐章', 'e37bda55-e80e-45af-847e-13c6e480ee30', '唐', '["大君出震，有事郊禋。","齋戒既肅，馨香畢陳。","樂和禮備，候暖風春。","恭惟降福，實賴明神。"]', '["大君出震，有事郊禋。","斋戒既肅，馨香畢陳。","乐和禮備，候暖风春。","恭惟降福，實賴明神。"]', '诗', 'shi', '', NULL, '祭汾陰樂章 劉晃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3a1df4d-dd21-4e1a-967e-17d85ef7aa17', '唐禪社首樂章 順和', '唐禪社首乐章 順和', '3379ae1d-ad39-42f1-aa77-0a168f065885', '唐', '["至哉含柔德，萬物資以生。","常順稱厚載，流謙通變盈。","聖心事能察，增廣陳厥誠。","黃祇僾如在，泰折俟咸亨。"]', '["至哉含柔德，万物資以生。","常順稱厚載，流謙通变盈。","聖心事能察，增廣陳厥誠。","黄祇僾如在，泰折俟咸亨。"]', '诗', 'shi', '', NULL, '唐禪社首樂章 順和 賀知章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f0ac62c-0b54-4b6d-a9f8-ce5534d52264', '太和', '太和', '3379ae1d-ad39-42f1-aa77-0a168f065885', '唐', '["肅我成命，於昭黃衹。","裘冕而祀，陟降在斯。","五音克備，八變聿施。","緝熙肆靖，厥心匪離。"]', '["肅我成命，於昭黄衹。","裘冕而祀，陟降在斯。","五音克備，八变聿施。","緝熙肆靖，厥心匪離。"]', '诗', 'shi', '', NULL, '太和 賀知章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b3e7335-b163-4dae-b4cb-bd3d9ab6c7c7', '太和 肅和', '太和 肅和', '3379ae1d-ad39-42f1-aa77-0a168f065885', '唐', '["黃祇是祗，我其夙夜。","夤畏誠絜，匪遑寧舍。","禮以琮玉，薦厥茅藉。","念茲降康，胡寧克暇。"]', '["黄祇是祗，我其夙夜。","夤畏誠絜，匪遑寧舍。","禮以琮玉，薦厥茅藉。","念茲降康，胡寧克暇。"]', '诗', 'shi', '', NULL, '太和 肅和 賀知章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97fa6464-7f5f-4ffc-ab32-0d72e4171029', '太和 雍和', '太和 雍和', '3379ae1d-ad39-42f1-aa77-0a168f065885', '唐', '["夙夜宥密，不敢寧宴。","五齊既陳，八音在縣。","粢盛以絜，房俎斯薦。","惟德惟馨，尚茲克徧。"]', '["夙夜宥密，不敢寧宴。","五齊既陳，八音在縣。","粢盛以絜，房俎斯薦。","惟德惟馨，尚茲克徧。"]', '诗', 'shi', '', NULL, '太和 雍和 賀知章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc92ee7f-f8d6-47bb-9efe-f2402a4aa123', '太和 壽和', '太和 壽和', '3379ae1d-ad39-42f1-aa77-0a168f065885', '唐', '["惟以明發，有懷載殷。","樂盈而反，禮順其禋。","立清以獻，薦欲是親。","於穆不已，裒對斯臻。"]', '["惟以明發，有懷載殷。","乐盈而反，禮順其禋。","立清以獻，薦欲是親。","於穆不已，裒对斯臻。"]', '诗', 'shi', '', NULL, '太和 壽和 賀知章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9413d4ed-a104-4098-95bd-ca20ce911d85', '太和 福和', '太和 福和', '3379ae1d-ad39-42f1-aa77-0a168f065885', '唐', '["穆穆天子，告成岱宗。","大裘如濡，執珽有顒。","樂以平志，禮以和容。","上帝臨我，云胡肅邕。"]', '["穆穆天子，告成岱宗。","大裘如濡，執珽有顒。","乐以平志，禮以和容。","上帝臨我，云胡肅邕。"]', '诗', 'shi', '', NULL, '太和 福和 賀知章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eda5a0a2-a343-4b90-82cb-fbc5425e622c', '太和 太和', '太和 太和', '3379ae1d-ad39-42f1-aa77-0a168f065885', '唐', '["昭昭有唐，天俾萬國。","列祖應命，四宗順則。","申錫無疆，宗我同德。","曾孫繼緒，享神配極。"]', '["昭昭有唐，天俾万国。","列祖應命，四宗順則。","申錫無疆，宗我同德。","曾孫繼緒，享神配極。"]', '诗', 'shi', '', NULL, '太和 太和 賀知章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d177157-4a06-44d4-9a20-6c30f98e89c1', '太和 晚發', '太和 晚發', '3379ae1d-ad39-42f1-aa77-0a168f065885', '唐', '["江臯聞曙鐘，輕栧理還舼。","海潮夜約約，川露晨溶溶。","始見沙上鳥，猶埋雲外峰。","故鄉杳無際，明發懷朋從。"]', '["江臯闻曙鐘，轻栧理還舼。","海潮夜約約，川露晨溶溶。","始见沙上鸟，猶埋云外峰。","故乡杳無際，明發懷朋從。"]', '诗', 'shi', '', NULL, '太和 晚發 賀知章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36cd0a6f-d2b1-4ee0-b9cb-d04f080b1441', '奉和御製春臺望', '奉和御製春台望', '3379ae1d-ad39-42f1-aa77-0a168f065885', '唐', '["青陽布王道，玄覽陶真性。","欣若天下春，高逾域中聖。","神臯類觀賞，帝里如懸鏡。","繚繞八川浮，岧嶢雙闕映。","曉色徧昭陽，晴雲卷建章。","華滋的皪丹青樹，顥氣氤氳金玉堂。","尚有靈蛇下鄜畤，還徵瑞寶入陳倉。","自昔秦奢漢窮武，後庭萬餘宮百數。","旗回五丈殿千門，連綿南隥出西垣。","廣畫螓蛾誇窈窕，羅生玳瑁象崑崙。","廼睠天晴興隱恤，古來土木良非一。","荆臨章觀趙叢臺，何如堯階將禹室。","層欄䆗窱下龍輿，清管逶迤半綺疏。","一聽南風引鸞舞，長謠北極仰鶉居。"]', '["青陽布王道，玄覽陶真性。","欣若天下春，高逾域中聖。","神臯類观賞，帝里如懸镜。","繚繞八川浮，岧嶢雙闕映。","晓色徧昭陽，晴云卷建章。","华滋的皪丹青樹，顥氣氤氳金玉堂。","尚有靈蛇下鄜畤，還徵瑞寶入陳倉。","自昔秦奢漢窮武，後庭万餘宮百數。","旗回五丈殿千门，連綿南隥出西垣。","廣畫螓蛾誇窈窕，羅生玳瑁象崑崙。","廼睠天晴兴隐恤，古来土木良非一。","荆臨章观趙叢台，何如堯階將禹室。","層欄䆗窱下龙輿，清管逶迤半綺疏。","一听南风引鸾舞，长謠北極仰鶉居。"]', '诗', 'shi', '', NULL, '奉和御製春臺望 賀知章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05c8a0ab-59be-412f-9ed4-d2bd5915de73', '望人家桃李花', '望人家桃李花', '3379ae1d-ad39-42f1-aa77-0a168f065885', '唐', '["山源夜雨度仙家，朝發東園桃李花。","桃花紅兮李花白，照灼城隅復南陌。","南陌青樓十二重，春風桃李爲誰容。","棄置千金輕不顧，踟躕五馬謝相逢。","徒言南國容華晚，遂歎西家飄落遠。","的皪長奉明光殿，氛氳半入披香苑。","苑中珍木元自奇，黃金作葉白銀枝。","千年萬歲不凋落，還將桃李更相宜。","桃李從來露井傍，成蹊結影矜豔陽。","莫道春花不可樹，會持仙實薦君王。"]', '["山源夜雨度仙家，朝發东园桃李花。","桃花紅兮李花白，照灼城隅复南陌。","南陌青楼十二重，春风桃李爲誰容。","棄置千金轻不顧，踟躕五马謝相逢。","徒言南国容华晚，遂歎西家飄落远。","的皪长奉明光殿，氛氳半入披香苑。","苑中珍木元自奇，黄金作葉白銀枝。","千年万歲不凋落，還將桃李更相宜。","桃李從来露井傍，成蹊結影矜豔陽。","莫道春花不可樹，會持仙實薦君王。"]', '诗', 'shi', '', NULL, '望人家桃李花 賀知章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e7232a3-99e2-4b6d-89e8-73c221072a79', '送人之軍', '送人之軍', '3379ae1d-ad39-42f1-aa77-0a168f065885', '唐', '["常經絕脉塞，復見斷腸流。","送子成今別，令人起昔愁。","隴雲晴半雨，邊草夏先秋。","萬里長城寄，無貽漢國憂。"]', '["常經絕脉塞，复见斷腸流。","送子成今別，令人起昔愁。","隴云晴半雨，邊草夏先秋。","万里长城寄，無貽漢国憂。"]', '诗', 'shi', '', NULL, '送人之軍 賀知章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7801dee-a508-4774-8d0e-51e3e5469fc8', '奉和聖製送張說上集賢學士賜宴賦得謨字', '奉和聖製送張说上集賢学士賜宴賦得謨字', '3379ae1d-ad39-42f1-aa77-0a168f065885', '唐', '["西學垂玄覽，東堂發聖謨。","天光燭武殿，時宰集鴻都。","枯朽霑皇澤，翾飛舞帝梧。","跡同遊汗漫，榮是出泥塗。","三歎承湯鼎，千歡接舜壺。","微軀不可荅，空欲詠依蒲。"]', '["西学垂玄覽，东堂發聖謨。","天光燭武殿，时宰集鴻都。","枯朽霑皇澤，翾飞舞帝梧。","跡同游汗漫，榮是出泥塗。","三歎承湯鼎，千歡接舜壺。","微軀不可荅，空欲詠依蒲。"]', '诗', 'shi', '', NULL, '奉和聖製送張說上集賢學士賜宴賦得謨字 賀知章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfc44e7f-df97-4b76-b5f3-8bf9bd6fc657', '奉和聖製送張說巡邊', '奉和聖製送張说巡邊', '3379ae1d-ad39-42f1-aa77-0a168f065885', '唐', '["荒憬盡懷忠，梯航已自通。","九攻雖不戰，五月尚持戎。","遣戍徵周牒，恢邊重漢功。","選車命元宰，授律取文雄。","胄出天弧上，謀成帝幄中。","詔旂分夏物，專土錫唐弓。","帳宿伊川右，鉦傳晉苑東。","饔人藉蕡實，樂正理絲桐。","岐陌涵餘雨，離川照晚虹。","恭聞詠方叔，千載舞皇風。"]', '["荒憬尽懷忠，梯航已自通。","九攻雖不戰，五月尚持戎。","遣戍徵周牒，恢邊重漢功。","選车命元宰，授律取文雄。","胄出天弧上，謀成帝幄中。","詔旂分夏物，專土錫唐弓。","帳宿伊川右，鉦傳晉苑东。","饔人藉蕡實，乐正理絲桐。","岐陌涵餘雨，離川照晚虹。","恭闻詠方叔，千載舞皇风。"]', '诗', 'shi', '', NULL, '奉和聖製送張說巡邊 賀知章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7185b87-f7c2-483a-8d88-dec61a065199', '題袁氏別業', '題袁氏別業', '3379ae1d-ad39-42f1-aa77-0a168f065885', '唐', '["主人不相識，偶坐爲林泉。","莫謾愁沽酒，囊中自有錢。"]', '["主人不相識，偶坐爲林泉。","莫謾愁沽酒，囊中自有錢。"]', '诗', 'shi', '', NULL, '題袁氏別業 賀知章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf4ce5bb-7a29-4b33-b8c6-55a020394ab8', '詠柳', '詠柳', '3379ae1d-ad39-42f1-aa77-0a168f065885', '唐', '["碧玉妝成一樹高，萬條垂下綠絲縧。","不知細葉誰裁出，二月春風似剪刀。"]', '["碧玉妝成一樹高，万條垂下綠絲縧。","不知細葉誰裁出，二月春风似剪刀。"]', '诗', 'shi', '', NULL, '詠柳 賀知章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eea19f7a-04c7-417d-bec7-9a93dd55e845', '采蓮曲', '采蓮曲', '3379ae1d-ad39-42f1-aa77-0a168f065885', '唐', '["稽山罷霧鬱嵯峨，鏡水無風也自波。","莫言春度芳菲盡，別有中流采芰荷。"]', '["稽山罷霧鬱嵯峨，镜水無风也自波。","莫言春度芳菲尽，別有中流采芰荷。"]', '诗', 'shi', '', NULL, '采蓮曲 賀知章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('599b8a93-47ab-4426-94c0-ca16eea0ca37', '回鄉偶書二首 一', '回乡偶书二首 一', '3379ae1d-ad39-42f1-aa77-0a168f065885', '唐', '["少小離家老大回，鄉音難改鬢毛衰。","兒童相見不相識，笑問客從何處來。"]', '["少小離家老大回，乡音难改鬢毛衰。","兒童相见不相識，笑问客從何处来。"]', '诗', 'shi', '', NULL, '回鄉偶書二首 一 賀知章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cee858c-b57c-4262-94fd-6737dd8e9996', '回鄉偶書二首 二', '回乡偶书二首 二', '3379ae1d-ad39-42f1-aa77-0a168f065885', '唐', '["離別家鄉歲月多，近來人事半銷磨。","唯有門前鏡湖水，春風不改舊時波。"]', '["離別家乡歲月多，近来人事半銷磨。","唯有门前镜湖水，春风不改旧时波。"]', '诗', 'shi', '', NULL, '回鄉偶書二首 二 賀知章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b7ac645-06f5-47f1-a8d7-1107dc7ce594', '答朝士', '答朝士', '3379ae1d-ad39-42f1-aa77-0a168f065885', '唐', '["鈒鏤銀盤盛蛤蜊，鏡湖蓴菜亂如絲。","鄉曲近來隹此味，遮渠不道是吳兒。"]', '["鈒鏤銀盤盛蛤蜊，镜湖蓴菜亂如絲。","乡曲近来隹此味，遮渠不道是吳兒。"]', '诗', 'shi', '', NULL, '答朝士 賀知章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('828a80d9-71f3-48a0-995b-0fa749c6bcb5', '句', '句', '3379ae1d-ad39-42f1-aa77-0a168f065885', '唐', '["落花真好些，一醉一回顛。"]', '["落花真好些，一醉一回顛。"]', '诗', 'shi', '', NULL, '句 賀知章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf510a24-e1e4-49c3-b828-9be2ce8931c9', '敬酬張九齡當塗界留贈之作', '敬酬張九齡當塗界留贈之作', 'ae3cd3ae-527e-4e89-9d57-b9df34c6b275', '唐', '["茂先寔王佐，仲舉信時英。","氣覩衝天發，人將下榻迎。","珪符肅有命，江國遠徂征。","九派期方越，千鈞或所輕。","高帆出風迥，孤嶼入雲平。","遄邁嗟于役，離憂空自情。","餙簪陪早歲，接壤廁專城。","曠別心彌軫，宏規義轉傾。","徒然恨飢渴，況乃諷瑤瓊。"]', '["茂先寔王佐，仲舉信时英。","氣覩衝天發，人將下榻迎。","珪符肅有命，江国远徂征。","九派期方越，千鈞或所轻。","高帆出风迥，孤嶼入云平。","遄邁嗟于役，離憂空自情。","餙簪陪早歲，接壤廁專城。","曠別心彌軫，宏規義轉傾。","徒然恨飢渴，況乃諷瑤瓊。"]', '诗', 'shi', '', NULL, '敬酬張九齡當塗界留贈之作 裴耀卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1d8badb-0d37-4681-937e-c76190fbecbb', '酬張九齡使風見示', '酬張九齡使风见示', 'ae3cd3ae-527e-4e89-9d57-b9df34c6b275', '唐', '["茲地五湖隣，艱哉萬里人。","驚飆翻是託，危浪亦相因。","宣室才華子，金閨諷議臣。","承明有三人，去去速歸輪。"]', '["茲地五湖隣，艱哉万里人。","驚飆翻是託，危浪亦相因。","宣室才华子，金閨諷議臣。","承明有三人，去去速归輪。"]', '诗', 'shi', '', NULL, '酬張九齡使風見示 裴耀卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f05aac0b-94cd-4b6a-ae77-bc159c653125', '贈張丞相', '贈張丞相', '501b635b-f65c-434c-b14c-0e801f7fa5bf', '唐', '["漢上登飛幰，荆南歷舊居。","已嘗臨砌橘，更覩躍池魚。","盛德繼微渺，深衷能卷舒。","義申蓬閣際，情切廟堂初。","郡挹文章美，人懷燮理餘。","皇恩儻照亮，豈厭承明廬。"]', '["漢上登飞幰，荆南歷旧居。","已嘗臨砌橘，更覩躍池鱼。","盛德繼微渺，深衷能卷舒。","義申蓬閣際，情切廟堂初。","郡挹文章美，人懷燮理餘。","皇恩儻照亮，豈厭承明廬。"]', '诗', 'shi', '', NULL, '贈張丞相 宋鼎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbbe3dfd-98f0-403f-b4b4-1fd4b5d5f951', '酬故人還山', '酬故人還山', '501b635b-f65c-434c-b14c-0e801f7fa5bf', '唐', '["舉櫂乘春水，歸山撫歲華。","碧潭宵見月，紅樹晚開花。","肅穆輕風度，依微隱徑斜。","危亭暗松石，幽澗落雲霞。","思鳥吟高樹，游魚戲淺沙。","安知餘興盡，相望紫煙賒。"]', '["舉櫂乘春水，归山撫歲华。","碧潭宵见月，紅樹晚开花。","肅穆轻风度，依微隐徑斜。","危亭暗松石，幽澗落云霞。","思鸟吟高樹，游鱼戲淺沙。","安知餘兴尽，相望紫煙賒。"]', '诗', 'shi', '', NULL, '酬故人還山 宋鼎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('668736cb-2e47-45b1-b6d9-e943c41e1f7f', '和張荆州九齡晨出郡舍林下', '和張荆州九齡晨出郡舍林下', '31d02f1a-6be6-4896-81fc-498ded12808c', '唐', '["優閑表政清，林薄賞秋成。","江上懸曉月，往來虧復盈。","天雲抗真意，郡閣晦高名。","坐嘯應無欲，寧辜濟物情。"]', '["優闲表政清，林薄賞秋成。","江上懸晓月，往来虧复盈。","天云抗真意，郡閣晦高名。","坐嘯應無欲，寧辜濟物情。"]', '诗', 'shi', '', NULL, '和張荆州九齡晨出郡舍林下 崔頌 shi');
